UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "dragon.ep1", "title": "第 1 集：寿宴只剩折叠凳", "sceneDesc": "寿宴门口，梁少东（一脚把折叠凳踢到你跟前，歪嘴一笑）：「吃软饭的，你根本不配上桌。」（满堂哄笑）你怀里还抱着刚替全家修好的电饭锅，锅盖「叮」地跳了一下。\\\\n他（把退婚协议拍上转盘）：「这婚，我替她离定了。签！」（转盘一转，协议停在乔账房面前）乔账房推了推眼镜：「少东家，背面印的是昨晚的点菜单，还没结账。」\\\\n你衣袋里的龙纹牌滑到桌上。梁少东（捏起来晃了晃）：「食堂购物卡？里面还剩几块钱？」包师傅瞥见牌子，锅铲当啷落地，嘴里那句「恭迎龙……」硬拐成：「汤来了！汤来了！」\\\\n一圈手机镜头对准你，全桌都在等那句三年之期已到。梁少东把笔戳到你手边：「签不签？不签就滚去门口吃。」", "sceneImage": "/static/art/covers/cover-dragon.jpg", "panels": [{"speaker": "旁白", "text": "寿宴门口，梁少东（一脚把折叠凳踢到你跟前，歪嘴一笑）：「吃软饭的，你根本不配上桌。」（满堂哄笑）你怀里还抱着刚替全家修好的电饭锅，锅盖「叮」地跳了一下。"}, {"speaker": "旁白", "text": "他（把退婚协议拍上转盘）：「这婚，我替她离定了。签！」（转盘一转，协议停在乔账房面前）乔账房推了推眼镜：「少东家，背面印的是昨晚的点菜单，还没结账。」"}, {"speaker": "旁白", "text": "你衣袋里的龙纹牌滑到桌上。梁少东（捏起来晃了晃）：「食堂购物卡？里面还剩几块钱？」包师傅瞥见牌子，锅铲当啷落地，嘴里那句「恭迎龙……」硬拐成：「汤来了！汤来了！」"}, {"speaker": "旁白", "text": "一圈手机镜头对准你，全桌都在等那句三年之期已到。梁少东把笔戳到你手边：「签不签？不签就滚去门口吃。」"}], "choices": [{"choiceId": "dragon_e1_c2", "id": "A", "label": "A", "text": "拍桌宣布三年之期已到", "styleTag": "离谱反套路", "feedback": "你一掌拍在桌上：「三年之期已到！」身后电饭锅「嘀」地开始煮饭。全场震惊了三秒，梁少东第一个回过神：「哪三年？几号到几号？拿文件来。」你摸遍衣袋，只摸出那块牌子。他笑着扬了扬一张收购意向书。", "outcome": "你一掌拍在桌上：「三年之期已到！」身后电饭锅「嘀」地开始煮饭。全场震惊了三秒，梁少东第一个回过神：「哪三年？几号到几号？拿文件来。」你摸遍衣袋，只摸出那块牌子。他笑着扬了扬一张收购意向书。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "dragon_e1_c3", "id": "B", "label": "B", "text": "给折叠凳加一套餐具", "styleTag": "打工人觉醒", "feedback": "你把折叠凳拖到门口，招呼没席位的帮厨师傅一块坐。包师傅端汤过来，顺手多摆一副碗筷。主桌还在等你发火，角落先吃上了。乔账房悄悄拽了下你袖子：「后厨说话，有人要卖食堂。」", "outcome": "你把折叠凳拖到门口，招呼没席位的帮厨师傅一块坐。包师傅端汤过来，顺手多摆一副碗筷。主桌还在等你发火，角落先吃上了。乔账房悄悄拽了下你袖子：「后厨说话，有人要卖食堂。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "dragon_e1_c1", "id": "C", "label": "C", "text": "核对寿宴账单", "styleTag": "经典套路", "feedback": "你把点菜单翻过来，圈出三处重复收费。乔账房当场签字：「属实。」梁少东（跳脚）：「保安！把他给我轰出去！」保安看完账单，先转向他：「少东家，这单谁结？」梁少东攥着手机走到门外：「老街食堂，明早就签收购。」", "outcome": "你把点菜单翻过来，圈出三处重复收费。乔账房当场签字：「属实。」梁少东（跳脚）：「保安！把他给我轰出去！」保安看完账单，先转向他：「少东家，这单谁结？」梁少东攥着手机走到门外：「老街食堂，明早就签收购。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 2, "number": 2, "id": "dragon.ep2", "title": "第 2 集：购物卡背面", "sceneDesc": "后厨门一关，乔账房递来一张收购意向书：「梁家要把食堂改成会员餐厅，连热水都分等级收费。」（笔尖点着签名栏）「明早，他就落笔。」\\\\n龙纹牌插进旧账柜，锁「咔」地开了。柜里只有一本食材账和半张盖过章的收据。乔账房翻了两遍：「交接文件不在。老馆长当年说过，藏在天天有人翻、又没人细看的地方。」\\\\n梁少东带人闯进来（把黑卡往柜台上一甩）：「这一柜破纸，我全包了。搬！」包师傅（一把抱紧菜单盒）：「卡能刷是吧？先把我欠了半年的工钱刷了。」\\\\n搬运工已经抬起柜角，梁少东在旁边数：「三、二……」半张收据，一块牌子，还有包师傅那半年工钱，你只来得及先顾一头。", "sceneImage": "/static/art/covers/cover-dragon.jpg", "panels": [{"speaker": "旁白", "text": "后厨门一关，乔账房递来一张收购意向书：「梁家要把食堂改成会员餐厅，连热水都分等级收费。」（笔尖点着签名栏）「明早，他就落笔。」"}, {"speaker": "旁白", "text": "龙纹牌插进旧账柜，锁「咔」地开了。柜里只有一本食材账和半张盖过章的收据。乔账房翻了两遍：「交接文件不在。老馆长当年说过，藏在天天有人翻、又没人细看的地方。」"}, {"speaker": "旁白", "text": "梁少东带人闯进来（把黑卡往柜台上一甩）：「这一柜破纸，我全包了。搬！」包师傅（一把抱紧菜单盒）：「卡能刷是吧？先把我欠了半年的工钱刷了。」"}, {"speaker": "旁白", "text": "搬运工已经抬起柜角，梁少东在旁边数：「三、二……」半张收据，一块牌子，还有包师傅那半年工钱，你只来得及先顾一头。"}], "choices": [{"choiceId": "dragon_e2_c1", "id": "A", "label": "A", "text": "封存旧账柜", "styleTag": "经典套路", "feedback": "你和乔账房抢在柜子离地前贴上封条，拍下编号。搬运工抬了两下不敢再动：「少东家，贴了封条的不好搬。」收据保住了，交接文件还是没影。乔账房盯着包师傅怀里的盒子，眯了眯眼。", "outcome": "你和乔账房抢在柜子离地前贴上封条，拍下编号。搬运工抬了两下不敢再动：「少东家，贴了封条的不好搬。」收据保住了，交接文件还是没影。乔账房盯着包师傅怀里的盒子，眯了眯眼。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "dragon_e2_c2", "id": "B", "label": "B", "text": "让所有人围观龙纹牌", "styleTag": "离谱反套路", "feedback": "你举起龙纹牌转了一圈，围观的越聚越多。一位大爷膝盖一软就要当场下跪，被包师傅一把架住：「大爷，地滑。」梁少东（冷笑）：「这种牌子，网上九块九包邮。」热闹有了，证明一张没多。巷口，一辆礼宾车正倒着车开进来。", "outcome": "你举起龙纹牌转了一圈，围观的越聚越多。一位大爷膝盖一软就要当场下跪，被包师傅一把架住：「大爷，地滑。」梁少东（冷笑）：「这种牌子，网上九块九包邮。」热闹有了，证明一张没多。巷口，一辆礼宾车正倒着车开进来。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "dragon_e2_c3", "id": "C", "label": "C", "text": "先结包师傅的工钱", "styleTag": "打工人觉醒", "feedback": "你先替包师傅把工钱结清。包师傅愣了愣，把菜单盒塞进你怀里：「东家，这盒子怕油，我一直贴身揣着。」旧菜单夹层里露出一角发黄的公文纸。你没当场抽出来，转手交给乔账房锁好。", "outcome": "你先替包师傅把工钱结清。包师傅愣了愣，把菜单盒塞进你怀里：「东家，这盒子怕油，我一直贴身揣着。」旧菜单夹层里露出一角发黄的公文纸。你没当场抽出来，转手交给乔账房锁好。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 3, "number": 3, "id": "dragon.ep3", "title": "第 3 集：大人物抵达后厨", "sceneDesc": "礼宾车停在食堂门口，一排黑衣人齐声高喊：「恭迎龙王归位！」梁少东抢先站到车门边摆好合影姿势。车门一开，下来的是拎着燃气检测仪的老管理员，黑衣人是他的巡检队。\\\\n老管理员看见你手里的龙纹牌，眼皮跳了一下，还是先掏出检查单：「会馆再有来头，灶也得先过安检。」门头那条金色横幅被风一吹，啪嗒掉下来一半。\\\\n梁少东不甘心，当场摆出三碗汤搞盲品：「喝得出哪碗是贵宾汤，我就认你这块牌。」包师傅（端汤经过，压低嗓子）：「三碗一口锅，我亲手舀的。」\\\\n三只碗推到你面前，梁少东把评分板竖起来，挡住了大半张桌。锅边标签和采购单，就压在你手肘底下。", "sceneImage": "/static/art/covers/cover-dragon.jpg", "panels": [{"speaker": "旁白", "text": "礼宾车停在食堂门口，一排黑衣人齐声高喊：「恭迎龙王归位！」梁少东抢先站到车门边摆好合影姿势。车门一开，下来的是拎着燃气检测仪的老管理员，黑衣人是他的巡检队。"}, {"speaker": "旁白", "text": "老管理员看见你手里的龙纹牌，眼皮跳了一下，还是先掏出检查单：「会馆再有来头，灶也得先过安检。」门头那条金色横幅被风一吹，啪嗒掉下来一半。"}, {"speaker": "旁白", "text": "梁少东不甘心，当场摆出三碗汤搞盲品：「喝得出哪碗是贵宾汤，我就认你这块牌。」包师傅（端汤经过，压低嗓子）：「三碗一口锅，我亲手舀的。」"}, {"speaker": "旁白", "text": "三只碗推到你面前，梁少东把评分板竖起来，挡住了大半张桌。锅边标签和采购单，就压在你手肘底下。"}], "choices": [{"choiceId": "dragon_e3_c3", "id": "A", "label": "A", "text": "把汤分给排队的街坊", "styleTag": "打工人觉醒", "feedback": "你把三碗汤倒回锅里，一勺一勺分给门口排队的街坊。街坊投票，只给了一个评价：「热乎。」身份比赛成了午饭，梁少东端着奖杯站在台上，找不到人领。他（把奖杯一撂）：「行，明天让你在全街面前丢人。」", "outcome": "你把三碗汤倒回锅里，一勺一勺分给门口排队的街坊。街坊投票，只给了一个评价：「热乎。」身份比赛成了午饭，梁少东端着奖杯站在台上，找不到人领。他（把奖杯一撂）：「行，明天让你在全街面前丢人。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "dragon_e3_c1", "id": "B", "label": "B", "text": "对照采购单揭开盲品", "styleTag": "经典套路", "feedback": "你（把采购单拍在评分板旁）：「同一批货，同一口锅，编号自己对。」老管理员核完一遍，把评分板翻到背面，铅笔印还没擦干净。梁少东脸一沉，转身打电话：「把那张照片发我。」", "outcome": "你（把采购单拍在评分板旁）：「同一批货，同一口锅，编号自己对。」老管理员核完一遍，把评分板翻到背面，铅笔印还没擦干净。梁少东脸一沉，转身打电话：「把那张照片发我。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "dragon_e3_c2", "id": "C", "label": "C", "text": "闭眼说这汤价值一座城", "styleTag": "离谱反套路", "feedback": "你闭眼抿了一口：「这碗汤，价值一座城。」全场震惊，包师傅手一抖，半袋盐差点进锅。梁少东鼓着掌凑过来：「好，那请出一份这座城的估价依据。」你没接上话。他翻开手机相册：「明天，给大家看点好东西。」", "outcome": "你闭眼抿了一口：「这碗汤，价值一座城。」全场震惊，包师傅手一抖，半袋盐差点进锅。梁少东鼓着掌凑过来：「好，那请出一份这座城的估价依据。」你没接上话。他翻开手机相册：「明天，给大家看点好东西。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 4, "number": 4, "id": "dragon.ep4", "title": "第 4 集：三年忍让的真相", "sceneDesc": "宴会厅门口挂出了「老街食堂改造发布会」。乔账房把一摞维修票据摞到你面前，最上面那张是三年前的：「修锅修灶，一张不落。你一直不亮牌子，是等旧账清完再接这口锅，对吧？」你没吭声。\\\\n大屏上投出一张照片：你系着围裙蹲在灶台边。梁少东歪嘴一笑：「哟，堂堂龙王，就会打杂？」包师傅眯眼瞅了半天：「这不是替我顶夜班那天吗？那晚的灶，还是你修好的。」\\\\n主持人刚拿起话筒，门口就陆续挤进来一群街坊。有人抱着你修过的保温壶，有人捏着你签过字的送餐单，七嘴八舌，把发布会挤成了证人大会。\\\\n梁少东（一把抢过话筒）：「一群蹭饭的，也配作证？」话筒「嗡」地啸叫，全场的眼睛又落回你身上。", "sceneImage": "/static/art/covers/cover-dragon.jpg", "panels": [{"speaker": "旁白", "text": "宴会厅门口挂出了「老街食堂改造发布会」。乔账房把一摞维修票据摞到你面前，最上面那张是三年前的：「修锅修灶，一张不落。你一直不亮牌子，是等旧账清完再接这口锅，对吧？」你没吭声。"}, {"speaker": "旁白", "text": "大屏上投出一张照片：你系着围裙蹲在灶台边。梁少东歪嘴一笑：「哟，堂堂龙王，就会打杂？」包师傅眯眼瞅了半天：「这不是替我顶夜班那天吗？那晚的灶，还是你修好的。」"}, {"speaker": "旁白", "text": "主持人刚拿起话筒，门口就陆续挤进来一群街坊。有人抱着你修过的保温壶，有人捏着你签过字的送餐单，七嘴八舌，把发布会挤成了证人大会。"}, {"speaker": "旁白", "text": "梁少东（一把抢过话筒）：「一群蹭饭的，也配作证？」话筒「嗡」地啸叫，全场的眼睛又落回你身上。"}], "choices": [{"choiceId": "dragon_e4_c2", "id": "A", "label": "A", "text": "请礼仪队举满龙纹横幅", "styleTag": "离谱反套路", "feedback": "礼仪队举起一面面龙纹横幅，收购宣传板被挡住了，取餐窗口也一起被挡住了。梁少东脸涨得通红，街坊隔着横幅喊：「今天到底有没有番茄蛋？」乔账房挤过来压着嗓子：「别举了，交接原件有下落了，还缺个章。」", "outcome": "礼仪队举起一面面龙纹横幅，收购宣传板被挡住了，取餐窗口也一起被挡住了。梁少东脸涨得通红，街坊隔着横幅喊：「今天到底有没有番茄蛋？」乔账房挤过来压着嗓子：「别举了，交接原件有下落了，还缺个章。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "dragon_e4_c1", "id": "B", "label": "B", "text": "按日期展示送餐与维修记录", "styleTag": "经典套路", "feedback": "你把送餐单和维修票据按日期一张张摊开，街坊挨个认：「这天是我家。」「这天是我。」大屏上那张打杂照，成了你三年值班的证据。主持人默默把「改造发布会」改成「情况说明会」。乔账房贴着你耳边：「原件找着了，就差最后一个章。」", "outcome": "你把送餐单和维修票据按日期一张张摊开，街坊挨个认：「这天是我家。」「这天是我。」大屏上那张打杂照，成了你三年值班的证据。主持人默默把「改造发布会」改成「情况说明会」。乔账房贴着你耳边：「原件找着了，就差最后一个章。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "dragon_e4_c3", "id": "C", "label": "C", "text": "宣布先吃饭后开会", "styleTag": "打工人觉醒", "feedback": "你把发布台挪出取餐通道，挨个发排队号：「先吃饭，吃完再开会。」梁少东的话筒还在啸叫，街坊已经端着餐盘选完了主食。乔账房端着饭坐到你旁边，筷子一停：「吃完跟我走，原件找到了，章还空着。」", "outcome": "你把发布台挪出取餐通道，挨个发排队号：「先吃饭，吃完再开会。」梁少东的话筒还在啸叫，街坊已经端着餐盘选完了主食。乔账房端着饭坐到你旁边，筷子一停：「吃完跟我走，原件找到了，章还空着。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 5, "number": 5, "id": "dragon.ep5", "title": "第 5 集：文件只差一个章", "sceneDesc": "乔账房把交接原件铺在案板上，公共供餐条款一条不少，只有最后一格「保管人」还空着等盖章。梁少东伸手就去拿：「借我研究研究。」这回他声音压得很低，连保安都没喊。\\\\n包师傅（锅铲往案板上一横，挡住他的手）：「东家，经营权管的是这口锅，管不了整条街。账得摊开。街坊的午饭，别让谁拿去办加冕礼。」\\\\n门口的摄影师架好了金色灯，主持人探进头：「先拍个揭晓镜头？一会儿光就没了。」梁少东马上帮腔：「对对对，先拍，文件不急。」\\\\n印泥盒就在你手边，摄影灯已经亮了。原件要存，就得趁现在。等收官那天再说「我早备份了」，没人会信。", "sceneImage": "/static/art/covers/cover-dragon.jpg", "panels": [{"speaker": "旁白", "text": "乔账房把交接原件铺在案板上，公共供餐条款一条不少，只有最后一格「保管人」还空着等盖章。梁少东伸手就去拿：「借我研究研究。」这回他声音压得很低，连保安都没喊。"}, {"speaker": "旁白", "text": "包师傅（锅铲往案板上一横，挡住他的手）：「东家，经营权管的是这口锅，管不了整条街。账得摊开。街坊的午饭，别让谁拿去办加冕礼。」"}, {"speaker": "旁白", "text": "门口的摄影师架好了金色灯，主持人探进头：「先拍个揭晓镜头？一会儿光就没了。」梁少东马上帮腔：「对对对，先拍，文件不急。」"}, {"speaker": "旁白", "text": "印泥盒就在你手边，摄影灯已经亮了。原件要存，就得趁现在。等收官那天再说「我早备份了」，没人会信。"}], "choices": [{"choiceId": "dragon_e5_c3", "id": "A", "label": "A", "text": "把揭晓会改成菜单听证会", "styleTag": "打工人觉醒", "feedback": "你把揭晓会改成菜单听证会，街坊举手投下周吃什么，番茄蛋全票通过。大家记住了你，那格保管人却还空着。乔账房把原件锁回柜里：「散了会再盖。」门外，梁少东已经在订收官宴的场地。", "outcome": "你把揭晓会改成菜单听证会，街坊举手投下周吃什么，番茄蛋全票通过。大家记住了你，那格保管人却还空着。乔账房把原件锁回柜里：「散了会再盖。」门外，梁少东已经在订收官宴的场地。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "dragon_e5_c2", "id": "B", "label": "B", "text": "先录一个盛大揭晓预告", "styleTag": "离谱反套路", "feedback": "摄影师让你转身喊了十遍「恭迎龙王归位」，一遍比一遍亮。章还躺在印泥盒里没动。梁少东拍着你的肩：「放心，收官宴我给你办个更大的，到时候一并解释。」", "outcome": "摄影师让你转身喊了十遍「恭迎龙王归位」，一遍比一遍亮。章还躺在印泥盒里没动。梁少东拍着你的肩：「放心，收官宴我给你办个更大的，到时候一并解释。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "dragon_e5_c1", "id": "C", "label": "C", "text": "扫描文件并登记保管人", "styleTag": "经典套路", "feedback": "你按下保管人章，原件当场扫描封存，副本交到乔账房手里。乔账房一页页对过页码：「齐了。」金色灯晚开了一分钟，文件一个字没少。梁少东攥着手机出了后厨：「收官宴，我来办。」", "outcome": "你按下保管人章，原件当场扫描封存，副本交到乔账房手里。乔账房一页页对过页码：「齐了。」金色灯晚开了一分钟，文件一个字没少。梁少东攥着手机出了后厨：「收官宴，我来办。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "dragon.ep6", "title": "第 6 集：全场起立不是下跪", "sceneDesc": "收官宴开席，龙纹牌摆在台中央。梁少东又一次站起来：「你倒是证明啊！」主持人翻了翻台本，小声提醒：「少东家，这句前五集您都问过了。」\\\\n乔账房清点手里能拿出来的记录，包师傅端上第一锅热饭。梁少东把黑卡拍在龙纹牌旁边：「会馆我出双倍，现在就签。」\\\\n主持人习惯性高喊：「全场跪下！」几位宾客膝盖已经弯了一半，字幕立刻更正：全场起立，给端菜的包师傅让个路。大家让出一条道，梁少东备好的震惊表情没等到特写。\\\\n灯光收拢到你身上，那张黑卡还压在桌角。最后一句台词，你来说。", "sceneImage": "/static/art/covers/cover-dragon.jpg", "panels": [{"speaker": "旁白", "text": "收官宴开席，龙纹牌摆在台中央。梁少东又一次站起来：「你倒是证明啊！」主持人翻了翻台本，小声提醒：「少东家，这句前五集您都问过了。」"}, {"speaker": "旁白", "text": "乔账房清点手里能拿出来的记录，包师傅端上第一锅热饭。梁少东把黑卡拍在龙纹牌旁边：「会馆我出双倍，现在就签。」"}, {"speaker": "旁白", "text": "主持人习惯性高喊：「全场跪下！」几位宾客膝盖已经弯了一半，字幕立刻更正：全场起立，给端菜的包师傅让个路。大家让出一条道，梁少东备好的震惊表情没等到特写。"}, {"speaker": "旁白", "text": "灯光收拢到你身上，那张黑卡还压在桌角。最后一句台词，你来说。"}], "choices": [{"choiceId": "dragon_e6_c1", "id": "A", "label": "A", "text": "公布交接记录与食堂承诺", "styleTag": "经典套路", "feedback": "你把交接记录一页页摊在台上，请每位经手人上来按手印。乔账房把黑卡推回梁少东面前：「少东家，会馆不卖，只交接。」他张了张嘴，这回嗓门没派上用场。", "outcome": "你把交接记录一页页摊在台上，请每位经手人上来按手印。乔账房把黑卡推回梁少东面前：「少东家，会馆不卖，只交接。」他张了张嘴，这回嗓门没派上用场。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "dragon_e6_c3", "id": "B", "label": "B", "text": "把龙纹牌挂到取餐窗口", "styleTag": "打工人觉醒", "feedback": "你（摘下龙纹牌，挂上取餐窗口）：「从今天起，谁来都按号取餐。」牌子总算有了人人看得懂的用途。梁少东攥着黑卡愣在原地，排他前面的大爷回过头：「小伙子，你几号？」", "outcome": "你（摘下龙纹牌，挂上取餐窗口）：「从今天起，谁来都按号取餐。」牌子总算有了人人看得懂的用途。梁少东攥着黑卡愣在原地，排他前面的大爷回过头：「小伙子，你几号？」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "dragon_e6_c2", "id": "C", "label": "C", "text": "让所有灯光只照我一个人", "styleTag": "离谱反套路", "feedback": "你（抬手）：「灯，只照我。」金光亮得主持人看不清台本。梁少东（眯着眼，一字一顿）：「证、据、呢？」你站在最像大结局的镜头里，低头补起了最基础的手续。", "outcome": "你（抬手）：「灯，只照我。」金光亮得主持人看不清台本。梁少东（眯着眼，一字一顿）：「证、据、呢？」你站在最像大结局的镜头里，低头补起了最基础的手续。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}]', endings_json = '[{"id": "dragon.end1", "type": "hidden", "priority": 100, "title": "龙王改行食堂主任", "text": "旧菜单夹层里的交接条款，和第五集的扫描件一字一字对上。你接下的是每天按时开饭的差事，没人需要冲你低头。包师傅递来一顶普通厨帽，梁少东端着餐盘，头一回排进了队里。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 42}}, "posterTag": "隐藏彩蛋", "hint": "选择搜证方向并点击画面闪烁证物收取 >= 4 份，且反派怒气 <= 42 方可解锁"}, {"id": "dragon.end2", "type": "subversive", "priority": 90, "title": "龙王今天不营业", "text": "你一次次推掉排场，最后把会馆改成街坊一起议事的食堂。众人刚要齐喊恭迎龙王归位，你递过去一本意见簿：「先写写，今天咸了还是淡了。」", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触及隐藏或烂尾即可解锁"}, {"id": "dragon.end3", "type": "unfinished", "priority": 80, "title": "龙纹续费失败", "text": "横幅挂满了整条街，文件却没留下几张。收官音乐戛然而止，大屏跳出四个字：文件待补。主持人清清嗓子：「下一部，《继承手续办理记》，敬请期待。」", "condition": {"minStats": {"anger": 60}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气累计 >= 60 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "dragon.end4", "type": "triumph", "priority": 70, "title": "三年之期饭已做好", "text": "你凭记录接下会馆，公共供餐一条没改。梁少东甩出黑卡想插队，取餐机礼貌地吐给他一张第八十号。后来他们都后悔了，后悔没早点来排队。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_01_zhuixu';

