UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "heiress.ep1", "title": "第 1 集：进门先考餐具", "sceneDesc": "旧宅门口挂着「真千金归来」的横幅。许管事不请你进门（把七把长得差不多的餐具一字排开）：「选错一把，你就根本不配进这个门。」阿棉踮脚凑到你耳边：「今天吃的是馄饨。」\\\\n桌边已经坐着另一位当事人，手里攥着一张和你一模一样的入宅通知。她刚把通知递过来想对一对，许管事（伸手一按）：「两位，先别交流。」\\\\n沈老师抱着一摞早年的学校登记表进门：「两份一起查，谁也不偏。」许管事（歪嘴一笑）：「沈老师，大家族看的是气度。先拍一张，看谁更像主人。」\\\\n闪光灯已经架好，七把餐具还亮晃晃地排在你手边。许管事（抬了抬下巴）：「请吧。」", "sceneImage": "/static/generated_scenes/heiress/heiress_ep1_p1.jpg", "panels": [{"speaker": "旁白", "text": "旧宅门口挂着「真千金归来」的横幅。许管事不请你进门（把七把长得差不多的餐具一字排开）：「选错一把，你就根本不配进这个门。」阿棉踮脚凑到你耳边：「今天吃的是馄饨。」"}, {"speaker": "旁白", "text": "桌边已经坐着另一位当事人，手里攥着一张和你一模一样的入宅通知。她刚把通知递过来想对一对，许管事（伸手一按）：「两位，先别交流。」"}, {"speaker": "旁白", "text": "沈老师抱着一摞早年的学校登记表进门：「两份一起查，谁也不偏。」许管事（歪嘴一笑）：「沈老师，大家族看的是气度。先拍一张，看谁更像主人。」"}, {"speaker": "旁白", "text": "闪光灯已经架好，七把餐具还亮晃晃地排在你手边。许管事（抬了抬下巴）：「请吧。」"}], "choices": [{"choiceId": "heiress_e1_c1", "id": "A", "label": "A", "text": "要求平等核验登记表", "styleTag": "经典套路", "feedback": "你（把登记表摊在餐具中间）：「先查这个。」你和另一位当事人各签一份查阅记录，沈老师在底下落款。许管事想把话头扯回气质，沈老师一句话把他问住：「这张表，当年是谁报上去的？」他嘴角一抽，吩咐阿棉：「把正厅那张全家福先收起来。」", "outcome": "你（把登记表摊在餐具中间）：「先查这个。」你和另一位当事人各签一份查阅记录，沈老师在底下落款。许管事想把话头扯回气质，沈老师一句话把他问住：「这张表，当年是谁报上去的？」他嘴角一抽，吩咐阿棉：「把正厅那张全家福先收起来。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "heiress_e1_c2", "id": "B", "label": "B", "text": "用最夸张的姿势挑餐具", "styleTag": "离谱反套路", "feedback": "你挑起最大的一把勺子，在灯下转了个圈。许管事立刻宣布：「答案另有标准。」你赢了镜头，却看见他从袖子里又抽出一张新评分标准，墨迹还没干。他（冲阿棉一摆手）：「把那张全家福挂出来。」", "outcome": "你挑起最大的一把勺子，在灯下转了个圈。许管事立刻宣布：「答案另有标准。」你赢了镜头，却看见他从袖子里又抽出一张新评分标准，墨迹还没干。他（冲阿棉一摆手）：「把那张全家福挂出来。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "heiress_e1_c3", "id": "C", "label": "C", "text": "请所有人都用普通汤勺", "styleTag": "打工人觉醒", "feedback": "你把七把餐具推到一边：「都用汤勺吧，馄饨要坨了。」阿棉手脚麻利地撤了桌，另一位当事人先笑出了声，冲你眨了眨眼。许管事看着你们俩，伸手把墙上那张全家福扶正了。", "outcome": "你把七把餐具推到一边：「都用汤勺吧，馄饨要坨了。」阿棉手脚麻利地撤了桌，另一位当事人先笑出了声，冲你眨了眨眼。许管事看着你们俩，伸手把墙上那张全家福扶正了。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 2, "number": 2, "id": "heiress.ep2", "title": "第 2 集：合照边角被裁掉", "sceneDesc": "正厅那张全家福，右下角被齐齐裁掉一块。沈老师伸手比了比：「原来这儿印着拍摄日期。」许管事（端着茶，没抬头）：「裁掉是为了构图。哪年拍的，不重要。」\\\\n阿棉从针线盒底下翻出一本旧相册，封皮的线明显拆过又缝上了。另一位当事人凑过来：「一起查吧，省得被人安排着互相掐。」\\\\n许管事拍拍手，正厅里坐进一排评委，没一个认识你：「气质评选，现场打分。」沈老师（把评分表按回桌上）：「打分只看今天谁顺眼。认身份，得走核验。」\\\\n评委已经举起分牌，许管事的眼睛却一直盯着阿棉怀里那本相册。", "sceneImage": "/static/generated_scenes/heiress/heiress_ep2_p1.jpg", "panels": [{"speaker": "旁白", "text": "正厅那张全家福，右下角被齐齐裁掉一块。沈老师伸手比了比：「原来这儿印着拍摄日期。」许管事（端着茶，没抬头）：「裁掉是为了构图。哪年拍的，不重要。」"}, {"speaker": "旁白", "text": "阿棉从针线盒底下翻出一本旧相册，封皮的线明显拆过又缝上了。另一位当事人凑过来：「一起查吧，省得被人安排着互相掐。」"}, {"speaker": "旁白", "text": "许管事拍拍手，正厅里坐进一排评委，没一个认识你：「气质评选，现场打分。」沈老师（把评分表按回桌上）：「打分只看今天谁顺眼。认身份，得走核验。」"}, {"speaker": "旁白", "text": "评委已经举起分牌，许管事的眼睛却一直盯着阿棉怀里那本相册。"}], "choices": [{"choiceId": "heiress_e2_c3", "id": "A", "label": "A", "text": "请阿棉拆开相册封皮", "styleTag": "打工人觉醒", "feedback": "阿棉用剪刀挑开封皮的线，里面夹着一张原始相片和一张收存说明。另一位当事人看了半天：「这一张，我从来没见过。」你把它交给沈老师收好。许管事的茶杯在托盘上轻轻磕了一下。", "outcome": "阿棉用剪刀挑开封皮的线，里面夹着一张原始相片和一张收存说明。另一位当事人看了半天：「这一张，我从来没见过。」你把它交给沈老师收好。许管事的茶杯在托盘上轻轻磕了一下。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "heiress_e2_c1", "id": "B", "label": "B", "text": "封存裁切前后的图像记录", "styleTag": "经典套路", "feedback": "你把裁切前后两个版本的图像存了档，标上来源，沈老师登记编号。这些没能当场说清一切，可许管事再也没法说那个角从来没有。他放下茶杯：「明天，请两位看看才艺。」", "outcome": "你把裁切前后两个版本的图像存了档，标上来源，沈老师登记编号。这些没能当场说清一切，可许管事再也没法说那个角从来没有。他放下茶杯：「明天，请两位看看才艺。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "heiress_e2_c2", "id": "C", "label": "C", "text": "在气质评选中拿满气场", "styleTag": "离谱反套路", "feedback": "你一个慢转身压住全场，评委的分牌齐刷刷举高。许管事当场加了一项血统分，评分台越搭越高，能信的东西一样没多。他宣布：「明天加赛，比才艺。」", "outcome": "你一个慢转身压住全场，评委的分牌齐刷刷举高。许管事当场加了一项血统分，评分台越搭越高，能信的东西一样没多。他宣布：「明天加赛，比才艺。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 3, "number": 3, "id": "heiress.ep3", "title": "第 3 集：会弹琴不代表会继承", "sceneDesc": "许管事把核验改成了才艺展示（掀开琴盖）：「弹错一个音，就请你出门。」你还没坐下，他又递来一本册子，封面烫着「继承人专属曲目」。\\\\n另一位当事人翻到版权页，愣了：「旧宅兴趣班教材？」阿棉一眼认出封面：「我小时候也弹过这本。这么算，整条街的小孩都能来继承。」\\\\n沈老师（把档案室的预约回执压在琴盖上）：「正式核验已经排上了。」许管事又拍手：「等得太久，观众会走的。再加一场比赛。」\\\\n琴凳摆好了，许管事亲手翻开琴谱，停在最难的那一页。", "sceneImage": "/static/generated_scenes/heiress/heiress_ep1_p2.jpg", "panels": [{"speaker": "旁白", "text": "许管事把核验改成了才艺展示（掀开琴盖）：「弹错一个音，就请你出门。」你还没坐下，他又递来一本册子，封面烫着「继承人专属曲目」。"}, {"speaker": "旁白", "text": "另一位当事人翻到版权页，愣了：「旧宅兴趣班教材？」阿棉一眼认出封面：「我小时候也弹过这本。这么算，整条街的小孩都能来继承。」"}, {"speaker": "旁白", "text": "沈老师（把档案室的预约回执压在琴盖上）：「正式核验已经排上了。」许管事又拍手：「等得太久，观众会走的。再加一场比赛。」"}, {"speaker": "旁白", "text": "琴凳摆好了，许管事亲手翻开琴谱，停在最难的那一页。"}], "choices": [{"choiceId": "heiress_e3_c2", "id": "A", "label": "A", "text": "宣布我还会更多稀有才艺", "styleTag": "离谱反套路", "feedback": "你宣布：「我还会更多稀有才艺！」许管事当场加项，连叠餐巾都写进了规则。围观的人越来越多，原本简单的核验又绕了一大圈。沈老师在人群外接了个电话，脸色变了：「档案室说，有人单独借过文件。」", "outcome": "你宣布：「我还会更多稀有才艺！」许管事当场加项，连叠餐巾都写进了规则。围观的人越来越多，原本简单的核验又绕了一大圈。沈老师在人群外接了个电话，脸色变了：「档案室说，有人单独借过文件。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "heiress_e3_c1", "id": "B", "label": "B", "text": "展示教材出处和预约回执", "styleTag": "经典套路", "feedback": "你把教材出处和预约回执并排放上琴盖：「才艺是才艺，身份是身份。」许管事只好收起评分板，你们对着回执清点档案室要的手续。沈老师翻到借阅登记，眉头一皱：「这几份关键文件，有人单独借出去过。」", "outcome": "你把教材出处和预约回执并排放上琴盖：「才艺是才艺，身份是身份。」许管事只好收起评分板，你们对着回执清点档案室要的手续。沈老师翻到借阅登记，眉头一皱：「这几份关键文件，有人单独借出去过。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "heiress_e3_c3", "id": "C", "label": "C", "text": "与另一位当事人合奏门铃声", "styleTag": "打工人觉醒", "feedback": "你和另一位当事人并排坐上琴凳，用最简单的几个音合奏了一段来客门铃。阿棉笑得忘了去开真门铃。被安排成宿敌的两个人，头一回有了合作镜头。门外，档案室送来一张借阅单，借阅人一栏写着：许。", "outcome": "你和另一位当事人并排坐上琴凳，用最简单的几个音合奏了一段来客门铃。阿棉笑得忘了去开真门铃。被安排成宿敌的两个人，头一回有了合作镜头。门外，档案室送来一张借阅单，借阅人一栏写着：许。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 4, "number": 4, "id": "heiress.ep4", "title": "第 4 集：谁在替你们翻译过去", "sceneDesc": "档案室的借阅记录摆上桌，关键文件被许管事单独借出过几次，日子正好跟几次错误通知对得上。许管事（整了整袖口）：「我这是替家族，把故事讲圆。」\\\\n你和另一位当事人各自讲了怎么长大的，谁吃的苦多，不算分。沈老师只记能核验的时间和地点，眼泪这回没被当成证据。\\\\n许管事（转向另一位当事人，冷笑）：「真千金归来，你就得卷铺盖走人！」你们翻开遗嘱摘要，一行行找下去，没有一条写着谁要赶谁走。\\\\n借阅单捏在你手里。许管事已经在吩咐人重新摆座，两把椅子隔着长桌，面对面放。", "sceneImage": "/static/generated_scenes/heiress/heiress_ep1_p2.jpg", "panels": [{"speaker": "旁白", "text": "档案室的借阅记录摆上桌，关键文件被许管事单独借出过几次，日子正好跟几次错误通知对得上。许管事（整了整袖口）：「我这是替家族，把故事讲圆。」"}, {"speaker": "旁白", "text": "你和另一位当事人各自讲了怎么长大的，谁吃的苦多，不算分。沈老师只记能核验的时间和地点，眼泪这回没被当成证据。"}, {"speaker": "旁白", "text": "许管事（转向另一位当事人，冷笑）：「真千金归来，你就得卷铺盖走人！」你们翻开遗嘱摘要，一行行找下去，没有一条写着谁要赶谁走。"}, {"speaker": "旁白", "text": "借阅单捏在你手里。许管事已经在吩咐人重新摆座，两把椅子隔着长桌，面对面放。"}], "choices": [{"choiceId": "heiress_e4_c3", "id": "A", "label": "A", "text": "共同签署拒绝互相驱逐的声明", "styleTag": "打工人觉醒", "feedback": "你和另一位当事人一起签了份不互相驱逐的声明，先查清事实，再各自决定往后。阿棉撤下真假座签，换上两张写着普通名字的。桌子头一回像是给人坐的。沈老师接到通知：「遗嘱原件，明早送到。」", "outcome": "你和另一位当事人一起签了份不互相驱逐的声明，先查清事实，再各自决定往后。阿棉撤下真假座签，换上两张写着普通名字的。桌子头一回像是给人坐的。沈老师接到通知：「遗嘱原件，明早送到。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "heiress_e4_c2", "id": "B", "label": "B", "text": "宣布今天只准留一位主角", "styleTag": "离谱反套路", "feedback": "你（一拍桌）：「今天只准留一位主角！」许管事眼睛一亮，立刻摆好对立座位，大家爱看的吵架又回来了。你们刚攒下的那点信任被挤到桌角，真相又慢了一步。许管事笑着说：「明天遗嘱到了，自有分晓。」", "outcome": "你（一拍桌）：「今天只准留一位主角！」许管事眼睛一亮，立刻摆好对立座位，大家爱看的吵架又回来了。你们刚攒下的那点信任被挤到桌角，真相又慢了一步。许管事笑着说：「明天遗嘱到了，自有分晓。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "heiress_e4_c1", "id": "C", "label": "C", "text": "核对借阅人和通知记录", "styleTag": "经典套路", "feedback": "你一条条念出每次改动的经手时间，许管事再也没法拿一句家族惯例糊弄过去。另一位当事人掏出自己当年收到的通知，日期和借阅单严丝合缝。许管事脸色发白：「正式文件，明天才到。」", "outcome": "你一条条念出每次改动的经手时间，许管事再也没法拿一句家族惯例糊弄过去。另一位当事人掏出自己当年收到的通知，日期和借阅单严丝合缝。许管事脸色发白：「正式文件，明天才到。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 5, "number": 5, "id": "heiress.ep5", "title": "第 5 集：遗嘱比家宴诚实", "sceneDesc": "遗嘱原件送到，白纸黑字写明了共同继承的条件和各自的责任。旧宅那把主位椅本来就坐得下两个人，通篇翻完，也找不到气质测验这一条。\\\\n许管事嫌原件不够体面，要拿去重新排版，顺手甩出一张黑卡：「印刷费，我包了。」沈老师（按住文件）：「先核页码。」阿棉（一屁股坐到复印机旁）：「这回谁也别想少印一张。」\\\\n沈老师把文件分成两摞：「结论这摞可以公开。这摞是你们俩的私事，犯不着为了金光特效贴满墙。」她看着你：「怎么存，你定。」\\\\n印刷厂打来电话，问那一百张金色海报印不印。现在存下的档案，关系到收官那天，那张旧相片能不能把话说完整。", "sceneImage": "/static/generated_scenes/heiress/heiress_ep1_p2.jpg", "panels": [{"speaker": "旁白", "text": "遗嘱原件送到，白纸黑字写明了共同继承的条件和各自的责任。旧宅那把主位椅本来就坐得下两个人，通篇翻完，也找不到气质测验这一条。"}, {"speaker": "旁白", "text": "许管事嫌原件不够体面，要拿去重新排版，顺手甩出一张黑卡：「印刷费，我包了。」沈老师（按住文件）：「先核页码。」阿棉（一屁股坐到复印机旁）：「这回谁也别想少印一张。」"}, {"speaker": "旁白", "text": "沈老师把文件分成两摞：「结论这摞可以公开。这摞是你们俩的私事，犯不着为了金光特效贴满墙。」她看着你：「怎么存，你定。」"}, {"speaker": "旁白", "text": "印刷厂打来电话，问那一百张金色海报印不印。现在存下的档案，关系到收官那天，那张旧相片能不能把话说完整。"}], "choices": [{"choiceId": "heiress_e5_c1", "id": "A", "label": "A", "text": "核验并保存授权副本", "styleTag": "经典套路", "feedback": "页码和档案编号一页页对上，你只留下必要的授权副本。许管事捏着黑卡站了半天，没找到能动手改排版的地方。沈老师把副本锁进柜子：「明天，当着所有人开。」", "outcome": "页码和档案编号一页页对上，你只留下必要的授权副本。许管事捏着黑卡站了半天，没找到能动手改排版的地方。沈老师把副本锁进柜子：「明天，当着所有人开。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "heiress_e5_c3", "id": "B", "label": "B", "text": "把旧宅公共房间改成共享活动室", "styleTag": "打工人觉醒", "feedback": "你和另一位当事人商量着把公共房间改成共享活动室，阿棉马上报名手作桌。一张实打实的使用时间表，把身份之争压了下去。许管事看着时间表，把黑卡收回口袋：「明天，我还有最后一招。」", "outcome": "你和另一位当事人商量着把公共房间改成共享活动室，阿棉马上报名手作桌。一张实打实的使用时间表，把身份之争压了下去。许管事看着时间表，把黑卡收回口袋：「明天，我还有最后一招。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "heiress_e5_c2", "id": "C", "label": "C", "text": "先印百张豪华身份海报", "styleTag": "离谱反套路", "feedback": "金色海报铺满大厅，大字写着真千金归来，底下的小字却还没核过。许管事主动请缨：「口径我来统一。」沈老师没接话，只看着你，等你决定要不要再核一遍。", "outcome": "金色海报铺满大厅，大字写着真千金归来，底下的小字却还没核过。许管事主动请缨：「口径我来统一。」沈老师没接话，只看着你，等你决定要不要再核一遍。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "heiress.ep6", "title": "第 6 集：真相不用谁离场", "sceneDesc": "核验结果送到，沈老师按能公开的范围一条条念。另一位当事人坐在你旁边，她用不着被赶走，你的位置也一样稳。\\\\n许管事最后一次拍桌，要选出赢家，嗓门一拔：「我才是真正的董事长！」阿棉眨眨眼：「咱这宅子，有董事会吗？为什么不能直接照文件办？」许管事张了张嘴，没找到顺手的词。\\\\n主持人高喊：「全场跪下！」两位当事人谁也没打算当场下跪，字幕更正：全场坐下，会议继续，两把椅子一样高。镜头扫过并排的两把椅子，金光没再把谁挤到边上。\\\\n许管事把评分板抱在胸前，不肯撒手。最后一句，你来说。", "sceneImage": "/static/generated_scenes/heiress/heiress_ep1_p2.jpg", "panels": [{"speaker": "旁白", "text": "核验结果送到，沈老师按能公开的范围一条条念。另一位当事人坐在你旁边，她用不着被赶走，你的位置也一样稳。"}, {"speaker": "旁白", "text": "许管事最后一次拍桌，要选出赢家，嗓门一拔：「我才是真正的董事长！」阿棉眨眨眼：「咱这宅子，有董事会吗？为什么不能直接照文件办？」许管事张了张嘴，没找到顺手的词。"}, {"speaker": "旁白", "text": "主持人高喊：「全场跪下！」两位当事人谁也没打算当场下跪，字幕更正：全场坐下，会议继续，两把椅子一样高。镜头扫过并排的两把椅子，金光没再把谁挤到边上。"}, {"speaker": "旁白", "text": "许管事把评分板抱在胸前，不肯撒手。最后一句，你来说。"}], "choices": [{"choiceId": "heiress_e6_c2", "id": "A", "label": "A", "text": "追加一场最终气质对决", "styleTag": "离谱反套路", "feedback": "评分板又被搬回台上，许管事一下子来了精神。大家手里明明拿着文件，还得陪你们猜哪一块杯垫更像继承人。", "outcome": "评分板又被搬回台上，许管事一下子来了精神。大家手里明明拿着文件，还得陪你们猜哪一块杯垫更像继承人。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "heiress_e6_c3", "id": "B", "label": "B", "text": "宣布共同开一场普通家宴", "styleTag": "打工人觉醒", "feedback": "你们撤掉分胜负的座位，阿棉端上来和第一集一样的馄饨。这一回，没人需要靠挑勺子挣一个座位。", "outcome": "你们撤掉分胜负的座位，阿棉端上来和第一集一样的馄饨。这一回，没人需要靠挑勺子挣一个座位。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "heiress_e6_c1", "id": "C", "label": "C", "text": "公布经过核验的必要结论", "styleTag": "经典套路", "feedback": "你讲清文件定下了什么，也说明哪些私事不公开。许管事被请出档案保管流程，交钥匙时还想开口，沈老师已经在登记簿上划掉了他的名字。往后的日子，各人自己定。", "outcome": "你讲清文件定下了什么，也说明哪些私事不公开。许管事被请出档案保管流程，交钥匙时还想开口，沈老师已经在登记簿上划掉了他的名字。往后的日子，各人自己定。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}]', endings_json = '[{"id": "heiress.end1", "type": "hidden", "priority": 100, "title": "双主角不接受二选一", "text": "旧相片和核验档案一拼，被裁掉的年份补上了。误会全出在那几张被人改过的通知上。你们各过各的日子，旧宅一起管。阿棉在门口钉了块新门牌，两个名字一样大。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 42}}, "posterTag": "隐藏彩蛋", "hint": "选择搜证方向并点击画面闪烁证物收取 >= 4 份，且反派怒气 <= 42 方可解锁"}, {"id": "heiress.end2", "type": "subversive", "priority": 90, "title": "豪门气质考试取消", "text": "你们一次次推掉身份比赛，干脆把旧宅开成街坊的活动室。许管事递来申请，想当气质考官。报名表被退了回来，理由一栏写着：没有这个岗位。", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触及隐藏或烂尾即可解锁"}, {"id": "heiress.end3", "type": "unfinished", "priority": 80, "title": "认亲认到打印机缺纸", "text": "金色海报印了一摞又一摞，正式证据却没凑齐。字幕宣布本剧进入页码核对特别篇，许管事抱着评分板，还想给缺纸也打个分。", "condition": {"minStats": {"anger": 60}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气累计 >= 60 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "heiress.end4", "type": "triumph", "priority": 70, "title": "回家不是抢椅子", "text": "你用能核验的记录争到了自己的位置，也没碰别人的那份。收官家宴撤掉了真假座签，全场震惊，两碗馄饨居然一样热。许管事把那张才艺考核表折了又折，最后塞进了碎纸机。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_02_qianjin';

-- 更新剧本《夫人她是拆迁办的》(script_03_bazong) 分集选项顺序/证物配置与结局提示
UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "landlady.ep1", "title": "第 1 集：玫瑰堵了单元门", "sceneDesc": "周六一早，单元门口被九百九十九朵玫瑰堵得严严实实。快递员抱着你的纸箱挤不进来：「姐，您这是开花店？」你刚想下楼收租，沈聿川抱着一束比他还高的花走过来。\\\\n沈聿川（摘下墨镜，歪嘴一笑）：「回来吧，我把公司股权都给你。」钟特助捧着平板在后面擦汗：「花是沈总凌晨三点摆的，花店说不退。」你：「我不是夫人，我是房东。」\\\\n沈聿川把一张黑卡递到你面前：「房租我加三倍，只要你回头。」你低头看了眼手机：租约写着每月五号前转账，今天已经八号。你：「你逾期三天了。」\\\\n单元门被花墙堵死，王大爷往墙上贴了张红纸：「本月收租进度牌」。第一行，爽点值满四十五，算准时到账；第二行，沈总热度（反派怒气）过五十五，按烂尾登记。黑卡和平板，都等着你开口。", "sceneImage": "/static/art/covers/cover-landlady.jpg", "panels": [{"speaker": "旁白", "text": "周六一早，单元门口被九百九十九朵玫瑰堵得严严实实。快递员抱着你的纸箱挤不进来：「姐，您这是开花店？」你刚想下楼收租，沈聿川抱着一束比他还高的花走过来。"}, {"speaker": "旁白", "text": "沈聿川（摘下墨镜，歪嘴一笑）：「回来吧，我把公司股权都给你。」钟特助捧着平板在后面擦汗：「花是沈总凌晨三点摆的，花店说不退。」你：「我不是夫人，我是房东。」"}, {"speaker": "旁白", "text": "沈聿川把一张黑卡递到你面前：「房租我加三倍，只要你回头。」你低头看了眼手机：租约写着每月五号前转账，今天已经八号。你：「你逾期三天了。」"}, {"speaker": "旁白", "text": "单元门被花墙堵死，王大爷往墙上贴了张红纸：「本月收租进度牌」。第一行，爽点值满四十五，算准时到账；第二行，沈总热度（反派怒气）过五十五，按烂尾登记。黑卡和平板，都等着你开口。"}], "choices": [{"choiceId": "landlady_e1_c3", "id": "A", "label": "A", "text": "递给他一副手套，让他搬花", "styleTag": "打工人觉醒", "feedback": "你（递过去一副手套）：「花可以不退，但要搬走。公共走廊不放易腐物。」沈聿川低头看看手套，再看看你，居然接了。钟特助在后面拍照：「沈总第一次搬花。」", "outcome": "你（递过去一副手套）：「花可以不退，但要搬走。公共走廊不放易腐物。」沈聿川低头看看手套，再看看你，居然接了。钟特助在后面拍照：「沈总第一次搬花。」", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "landlady_e1_c1", "id": "B", "label": "B", "text": "翻出租约，按条款算逾期", "styleTag": "经典套路", "feedback": "你（翻开租约第四条）：「逾期每日按百分之五计违约金。」沈聿川愣住：「我是来追妻的，你跟我谈违约金？」你：「违约金不谈也行，追妻得走物业登记流程。」钟特助飞快地记下：「已登记，已登记。」", "outcome": "你（翻开租约第四条）：「逾期每日按百分之五计违约金。」沈聿川愣住：「我是来追妻的，你跟我谈违约金？」你：「违约金不谈也行，追妻得走物业登记流程。」钟特助飞快地记下：「已登记，已登记。」", "qualityBonus": 12, "effects": {"pleasure": 10, "drama": 7, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "landlady_e1_c2", "id": "C", "label": "C", "text": "甩开黑卡，当场演虐恋", "styleTag": "离谱反套路", "feedback": "你（把黑卡往花堆里一甩，眼里含着三分真七分演的泪）：「沈聿川，你知道这三年我是怎么过来的吗？」整栋楼的邻居探出头，王大爷搬来小板凳：「继续继续，别停。」沈聿川动容地往前一步：「我知道，是我的错。」黑卡掉在花堆里，没人去捡。", "outcome": "你（把黑卡往花堆里一甩，眼里含着三分真七分演的泪）：「沈聿川，你知道这三年我是怎么过来的吗？」整栋楼的邻居探出头，王大爷搬来小板凳：「继续继续，别��。」沈聿川动容地往前一步：「我知道，是我的错。」黑卡掉在花堆里，没人去捡。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 14, "evidence": 0, "subversion": 0}}]}, {"ep": 2, "number": 2, "id": "landlady.ep2", "title": "第 2 集：直升机停在晾衣区", "sceneDesc": "周日一早，天台上一架直升机把你晾的床单吹成了旗帜。王大爷举着扩音器喊：「那个飞行物，天台停放要登记！」沈聿川（摘下耳麦，抬了抬下巴）：「我把整个设计团队空运来了，重新装修你的房子。」\\\\n你：「房子是租出去的，装修得问房东。」钟特助抱着一只巨大的礼盒，吃力地小跑过来：「房东，这是沈总的诚意。」他喘得像刚搬完一台钢琴。\\\\n王大爷翻开登记簿：「天台停放，每小时五十，现金还是转账？」沈聿川皱眉：「我可以买下整个楼顶。」王大爷：「楼顶是公共的，买不了。」\\\\n床单卷在螺旋桨边，礼盒放在晾衣架下，王大爷的登记簿递到了你手边。红纸上又添一行：拆套路攒够一格、热度别过五十五，当天改叫收租日。三样东西，你只能碰一样。", "sceneImage": "/static/art/covers/cover-landlady.jpg", "panels": [{"speaker": "旁白", "text": "周日一早，天台上一架直升机把你晾的床单吹成了旗帜。王大爷举着扩音器喊：「那个飞行物，天台停放要登记！」沈聿川（摘下耳麦，抬了抬下巴）：「我把整个设计团队空运来了，重新装修你的房子。」"}, {"speaker": "旁白", "text": "你：「房子是租出去的，装修得问房东。」钟特助抱着一只巨大的礼盒，吃力地小跑过来：「房东，这是沈总的诚意。」他喘得像刚搬完一台钢琴。"}, {"speaker": "旁白", "text": "王大爷翻开登记簿：「天台停放，每小时五十，现金还是转账？」沈聿川皱眉：「我可以买下整个楼顶。」王大爷：「楼顶是公共的，买不了。」"}, {"speaker": "旁白", "text": "床单卷在螺旋桨边，礼盒放在晾衣架下，王大爷的登记簿递到了你手边。红纸上又添一行：拆套路攒够一格、热度别过五十五，当天改叫收租日。三样东西，你只能碰一样。"}], "choices": [{"choiceId": "landlady_e2_c2", "id": "A", "label": "A", "text": "对直升机比手势：再转两圈", "styleTag": "离谱反套路", "feedback": "你（抬了抬下巴，对着空中的直升机摆了个潇洒的姿势）：「再转两圈，我还没拍够！」沈聿川顺势单膝跪地：「只要你满意。」王大爷拍着登记簿：「天台不许跪，地面承重不够！」床单被卷上半空，邻居们鼓起了掌。", "outcome": "你（抬了抬下巴，对着空中的直升机摆了个潇洒的姿势）：「再转两圈，我还没拍够！」沈聿川顺势单膝跪地：「只要你满意。」王大爷拍着登记簿：「天台不许跪，地面承重不够！」床单被卷上半空，邻居们鼓起了掌。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 14, "evidence": 0, "subversion": 0}}, {"choiceId": "landlady_e2_c1", "id": "B", "label": "B", "text": "按公共区域规定登记停放费", "styleTag": "经典套路", "feedback": "你拿起登记簿，在「停放事由」栏写下：追妻。王大爷认真收下了一百块：「有票据，下次别忘了带。」沈聿川看着自己的名字被写进小区登记簿，第一次觉得追妻是件需要签字的事。", "outcome": "你拿起登记簿，在「停放事由」栏写下：追妻。王大爷认真收下了一百块：「有票据，下次别忘了带。」沈聿川看着自己的名字被写进小区登记簿，第一次觉得追妻是件需要签字的事。", "qualityBonus": 12, "effects": {"pleasure": 10, "drama": 7, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "landlady_e2_c3", "id": "C", "label": "C", "text": "拆开那只最大的礼盒", "styleTag": "打工人觉醒", "feedback": "你拆开最大的礼盒，没有钻戒，只有一本厚厚的小账本：三年里每个月的暖气费垫付，楼道灯泡的更换，电梯维修的捐款，一笔一笔，字迹是沈聿川的。钟特助小声：「沈总说，不许告诉您。」你把账本合上，没吭声。", "outcome": "你拆开最大的礼盒，没有钻戒，只有一本厚厚的小账本：三年里每个月的暖气费垫付，楼道灯泡的更换，电梯维修的捐款，一笔一笔，字迹是沈聿川的。钟特助小声：「沈总说，不许告诉您。」你把账本合上，没吭声。", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 3, "number": 3, "id": "landlady.ep3", "title": "第 3 集：追妻也有甘特图", "sceneDesc": "消防楼梯里，钟特助压低声音，把平板递给你：「房东，这是沈总的追妻计划，一共六个阶段，今天是第三阶段，名字叫……当众告白。」\\\\n屏幕上是一张满满当当的甘特图：玫瑰、直升机、黑卡、感人短信，每项后面都画着进度条。你（指着最后一栏）：「这项为什么标红？」钟特助：「因为明天要拉横幅，租赁费有点贵。」\\\\n楼下传来沈聿川的喊声：「钟特助，我的西装呢？」他一身黑礼服，手里握着一支烟花筒。王大爷提着灭火器等在旁边：「小区禁止燃放，违者罚款。」\\\\n平板上有计划，楼下有烟花，物业手里有灭火器。红纸又添一行：让租客自己签罚单、进度过四十五、热度压在三十五以下，另有嘉奖。明天的当众告白，你可以改它，可以接它，也可以绕开它。", "sceneImage": "/static/art/covers/cover-landlady.jpg", "panels": [{"speaker": "旁白", "text": "消防楼梯里，钟特助压低声音，把平板递给你：「房东，这是沈总的追妻计划，一共六个阶段，今天是第三阶段，名字叫……当众告白。」"}, {"speaker": "旁白", "text": "屏幕上是一张满满当当的甘特图：玫瑰、直升机、黑卡、感人短信，每项后面都画着进度条。你（指着最后一栏）：「这项为什么标红？」钟特助：「因为明天要拉横幅，租赁费有点贵。」"}, {"speaker": "旁白", "text": "楼下传来沈聿川的喊声：「钟特助，我的西装呢？」他一身黑礼服，手里握着一支烟花筒。王大爷提着灭火器等在旁边：「小区禁止燃放，违者罚款。」"}, {"speaker": "旁白", "text": "平板上有计划，楼下有烟花，物业手里有灭火器。红纸又添一行：让租客自己签罚单、进度过四十五、热度压在三十五以下，另有嘉奖。明天的当众告白，你可以改它，可以接它，也可以绕开它。"}], "choices": [{"choiceId": "landlady_e3_c3", "id": "A", "label": "A", "text": "下楼陪王大爷开罚单", "styleTag": "打工人觉醒", "feedback": "你下楼，帮王大爷把罚单一张张开完。沈聿川看着自己的名字写在罚单上，表情像刚被扣了年终奖。王大爷递来笔：「签字，老规矩，现金或转账。」他乖乖签了。", "outcome": "你下楼，帮王大爷把罚单一张张开完。沈聿川看着自己的名字写在罚单上，表情像刚被扣了年终奖。王大爷递来笔：「签字，老规矩，现金或转账。」他乖乖签了。", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "landlady_e3_c2", "id": "B", "label": "B", "text": "让他放烟花，我来拍视频", "styleTag": "离谱反套路", "feedback": "沈聿川愣在原地，听见你说：「放，我给你拍。」他举起烟花筒，王大爷举起灭火器，钟特助举起罚单本，三个人在楼下对峙成一幅画。烟花还没点，保安就到了。你把视频发到网上，点赞三百。", "outcome": "沈聿川愣在原地，听见你说：「放，我给你拍。」他举起烟花筒，王大爷举起灭火器，钟特助举起罚单本，三个人在楼下对峙成一幅画。烟花还没点，保安就到了。你把视频发到网上，点赞三百。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 14, "evidence": 0, "subversion": 0}}, {"choiceId": "landlady_e3_c1", "id": "C", "label": "C", "text": "把预算和租金账单并排对一遍", "styleTag": "经典套路", "feedback": "你把追妻预算和租金账单并排放在一起，发现一件事：他花在直升机上的钱，够交三年房租。钟特助小声问：「房东，您想让沈总改什么？」你：「直升机的钱，拿去修楼道的灯。」", "outcome": "你把追妻预算和租金账单并排放在一起，发现一件事：他花在直升机上的钱，够交三年房租。钟特助小声问：「房东，您想让沈总改什么？」你：「直升机的钱，拿去修楼道的灯。」", "qualityBonus": 12, "effects": {"pleasure": 10, "drama": 7, "anger": 3, "evidence": 1, "subversion": 0}}]}, {"ep": 4, "number": 4, "id": "landlady.ep4", "title": "第 4 集：和好宴摆在小区院子", "sceneDesc": "傍晚，小区院子里摆起八张圆桌，红绸、香槟塔、乐队一应俱全，晾衣架上竖着横幅：老婆我错了，回家吧。邻居们端着碗围成一圈，没人急着坐下。\\\\n张婶端着饭碗，笑眯眯：「小沈这花样可以，比去年居委会联欢强。」王大爷已经坐上了主桌：「说好，吃完收摊，垃圾自己带走。」\\\\n沈聿川站到香槟塔旁，接过话筒：「各位邻居，今天我想当着大家的面，请求我太太原谅。」你：「前妻。」他：「前……暂时的。」钟特助在旁边轻咳了一声。\\\\n话筒递到了你手里，邻居们的筷子停在半空。这一桌饭，是给谁的面子，给谁的台阶，你说了算。", "sceneImage": "/static/art/covers/cover-landlady.jpg", "panels": [{"speaker": "旁白", "text": "傍晚，小区院子里摆起八张圆桌，红绸、香槟塔、乐队一应俱全，晾衣架上竖着横幅：老婆我错了，回家吧。邻居们端着碗围成一圈，没人急着坐下。"}, {"speaker": "旁白", "text": "张婶端着饭碗，笑眯眯：「小沈这花样可以，比去年居委会联欢强。」王大爷已经坐上了主桌：「说好，吃完收摊，垃圾自己带走。」"}, {"speaker": "旁白", "text": "沈聿川站到香槟塔旁，接过话筒：「各位邻居，今天我想当着大家的面，请求我太太原谅。」你：「前妻。」他：「前……暂时的。」钟特助在旁边轻咳了一声。"}, {"speaker": "旁白", "text": "话筒递到了你手里，邻居们的筷子停在半空。这一桌饭，是给谁的面子，给谁的台阶，你说了算。"}], "choices": [{"choiceId": "landlady_e4_c1", "id": "A", "label": "A", "text": "当众念出离婚与租约的公开信息", "styleTag": "经典套路", "feedback": "你（接过话筒）：「我说清楚，我和沈总三年前已离婚，现在房子出租，租金每月五号。」邻居们点头如捣蒜。张婶问：「那今天这顿算他请客，还是算他交违约金？」沈聿川：「……请客。」", "outcome": "你（接过话筒）：「我说清楚，我和沈总三年前已离婚，现在房子出租，租金每月五号。」邻居们点头如捣蒜。张婶问：「那今天这顿算他请客，还是算他交违约金？」沈聿川：「……请客。」", "qualityBonus": 12, "effects": {"pleasure": 10, "drama": 7, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "landlady_e4_c3", "id": "B", "label": "B", "text": "把话筒递给王大爷主持", "styleTag": "打工人觉醒", "feedback": "你（把话筒递给王大爷）：「今天由您主持。」王大爷站直了身子：「那咱开席，开席前每人领一张垃圾分类承诺书。」沈聿川愣愣接过承诺书，被安排在最角落那桌，和张婶的孙子同桌。", "outcome": "你（把话筒递给王大爷）：「今天由您主持。」王大爷站直了身子：「那咱开席，开席前每人领一张垃圾分类承诺书。」沈聿川愣愣接过承诺书，被安排在最角落那桌，和张婶的孙子同桌。", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "landlady_e4_c2", "id": "C", "label": "C", "text": "举着话筒问：你知道错在哪吗", "styleTag": "离谱反套路", "feedback": "你（举起话筒，把自己都吓了一跳）：「你知道你错在哪了吗？」全院鸦雀无声。沈聿川深吸一口气：「我错在……」他从头列到尾，整整说了八分钟，邻居们的汤都凉了。王大爷看了看表：「超时，按小时收费。」", "outcome": "你（举起话筒，把自己都吓了一跳）：「你知道你错在哪了吗？」全院鸦雀无声。沈聿川深吸一口气：「我错在……」他从头列到尾，整整说了八分钟，邻居们的汤都凉了。王大爷看了看表：「超时，按小时收费。」", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 14, "evidence": 0, "subversion": 0}}]}, {"ep": 5, "number": 5, "id": "landlady.ep5", "title": "第 5 集：读数比情话诚实", "sceneDesc": "夜里十点，你抱着水表电表的抄表本站在楼道里。王大爷拿着手电筒走过来：「业主委员会新规，房租和水电读数要公示，谁家都一样。」\\\\n沈聿川穿着拖鞋从三楼下来：「不用公示给我看，我相信你。」你：「不是给你看，是给全楼看。」钟特助跟在后面捧着一小盒粉笔，像捧着一份加急文件。\\\\n楼道里的公示栏是块旧黑板，右下角被谁画了一朵歪歪扭扭的小花。你的抄表本翻到最新一页，数字写得比情书还工整。\\\\n粉笔、抄表本、业主群，都在手边。这些读数往哪儿放，决定了明天有人拿它当证据，还是当笑话。", "sceneImage": "/static/art/covers/cover-landlady.jpg", "panels": [{"speaker": "旁白", "text": "夜里十点，你抱着水表电表的抄表本站在楼道里。王大爷拿着手电筒走过来：「业主委员会新规，房租和水电读数要公示，谁家都一样。」"}, {"speaker": "旁白", "text": "沈聿川穿着拖鞋从三楼下来：「不用公示给我看，我相信你。」你：「不是给你看，是给全楼看。」钟特助跟在后面捧着一小盒粉笔，像捧着一份加急文件。"}, {"speaker": "旁白", "text": "楼道里的公示栏是块旧黑板，右下角被谁画了一朵歪歪扭扭的小花。你的抄表本翻到最新一页，数字写得比情书还工整。"}, {"speaker": "旁白", "text": "粉笔、抄表本、业主群，都在手边。这些读数往哪儿放，决定了明天有人拿它当证据，还是当笑话。"}], "choices": [{"choiceId": "landlady_e5_c2", "id": "A", "label": "A", "text": "拍照发进业主群，配文追妻进度", "styleTag": "离谱反套路", "feedback": "你拍下沈聿川抱着花站在楼道的样子，发进业主群，配文：霸总追妻，进度条百分之六十。群里瞬间刷屏，张婶发来三个大拇指，王大爷回了一句：公示请按规定格式。沈聿川看到手机，委屈地把花放下了。", "outcome": "你拍下沈聿川抱着花站在楼道的样子，发进业主群，配文：霸总追妻，进度条百分之六十。群里瞬间刷屏，张婶发来三个大拇指，王大爷回了一句：公示请按规定格式。沈聿川看到手机，委屈地把花放下了。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 14, "evidence": 0, "subversion": 0}}, {"choiceId": "landlady_e5_c3", "id": "B", "label": "B", "text": "拉上沈聿川一起抄表", "styleTag": "打工人觉醒", "feedback": "你（把抄表本塞到沈聿川手里）：「来，今晚你负责念。」他认认真真念着读数，念到地下室那块表，笑了：「这块表走得比我心跳还慢。」王大爷在旁边点头：「这就对了，租客也要熟悉设备。」", "outcome": "你（把抄表本塞到沈聿川手里）：「来，今晚你负责念。」他认认真真念着读数，念到地下室那块表，笑了：「这块表走得比我心跳还慢。」王大爷在旁边点头：「这就对了，租客也要熟悉设备。」", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "landlady_e5_c1", "id": "C", "label": "C", "text": "把租金和读数抄上公示栏", "styleTag": "经典套路", "feedback": "你拿起粉笔，把每月租金、水电读数一行行抄上黑板，日期写在最右边。王大爷拿手电筒一行行核对：「清楚。」沈聿川站在黑板前看了很久，伸手帮你把最后一行的粉笔字擦得更直。", "outcome": "你拿起粉笔，把每月租金、水电读数一行行抄上黑板，日期写在最右边。王大爷拿手电筒一行行核对：「清楚。」沈聿川站在黑板前看了很久，伸手帮你把最后一行的粉笔字擦得更直。", "qualityBonus": 12, "effects": {"pleasure": 10, "drama": 7, "anger": 3, "evidence": 1, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "landlady.ep6", "title": "第 6 集：全体业主不用下跪", "sceneDesc": "晚八点，院子里亮起一排灯，沈聿川一身笔挺的西装，身后站着乐队、直升机、烟花筒和一整排抱着花的助理。邻居们搬着小板凳坐成三排，像在看露天电影。\\\\n钟特助深吸一口气：「沈总说，今天是最后一次追妻，所有项目一次上齐。」王大爷举着登记簿：「一次上齐，一次罚齐。」沈聿川没理他们，只是慢慢打开了手里的盒子。\\\\n盒子里没有戒指，是一把钥匙和一份新租约：「福安里三〇一，租期十年，租金我按市场价上浮三成。」他抬起头，难得没有歪嘴：「我不求复合，只求你别换租客。」\\\\n钥匙在盒子里闪着光，邻居们都等着你的答复。是接，是抛，还是换个说法，最后一句，你来说。", "sceneImage": "/static/art/covers/cover-landlady.jpg", "panels": [{"speaker": "旁白", "text": "晚八点，院子里亮起一排灯，沈聿川一身笔挺的西装，身后站着乐队、直升机、烟花筒和一整排抱着花的助理。邻居们搬着小板凳坐成三排，像在看露天电影。"}, {"speaker": "旁白", "text": "钟特助深吸一口气：「沈总说，今天是最后一次追妻，所有项目一次上齐。」王大爷举着登记簿：「一次上齐，一次罚齐。」沈聿川没理他们，只是慢慢打开了手里的盒子。"}, {"speaker": "旁白", "text": "盒子里没有戒指，是一把钥匙和一份新租约：「福安里三〇一，租期十年，租金我按市场价上浮三成。」他抬起头，难得没有歪嘴：「我不求复合，只求你别换租客。」"}, {"speaker": "旁白", "text": "钥匙在盒子里闪着光，邻居们都等着你的答复。是接，是抛，还是换个说法，最后一句，你来说。"}], "choices": [{"choiceId": "landlady_e6_c1", "id": "A", "label": "A", "text": "拿红笔，把新租约逐条改清楚", "styleTag": "经典套路", "feedback": "你拿出红笔，把租约一条条过：「第三条，不许往我家送花；第五条，房租五号前到账；第九条，感情问题另谈，不计入押金。」沈聿川在每一条后面认真签了名。王大爷宣布：「小区新增一位模范租客。」", "outcome": "你拿出红笔，把租约一条条过：「第三条，不许往我家送花；第五条，房租五号前到账；第九条，感情问题另谈，不计入押金。」沈聿川在每一条后面认真签了名。王大爷宣布：「小区新增一位模范租客。」", "qualityBonus": 12, "effects": {"pleasure": 10, "drama": 7, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "landlady_e6_c2", "id": "B", "label": "B", "text": "把钥匙往天上一抛：太迟了", "styleTag": "离谱反套路", "feedback": "你（一甩手，把钥匙往天上一抛）：「太迟了，沈聿川！」钥匙落进花坛，沈聿川单膝跪地，徒手找了十分钟。王大爷在旁边计时：「公共绿地，不许刨土。」邻居们的掌声里，混着此起彼伏的手机快门声。", "outcome": "你（一甩手，把钥匙往天上一抛）：「太迟了，沈聿川！」钥匙落进花坛，沈聿川单膝跪地，徒手找了十分钟。王大爷在旁边计时：「公共绿地，不许刨土。」邻居们的掌声里，混着此起彼伏的手机快门声。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 14, "evidence": 0, "subversion": 0}}, {"choiceId": "landlady_e6_c3", "id": "C", "label": "C", "text": "宣布下一集只拍收租日常", "styleTag": "打工人觉醒", "feedback": "你（拿起话筒）：「各位，下一集只拍收租日常，主演：房东与租客，不含追妻。」邻居们齐声：「好！」王大爷：「我申请客串。」沈聿川沉默片刻，居然点了头：「我也申请。」", "outcome": "你（拿起话筒）：「各位，下一集只拍收租日常，主演：房东与租客，不含追妻。」邻居们齐声：「好！」王大爷：「我申请客串。」沈聿川沉默片刻，居然点了头：「我也申请。」", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -5, "evidence": 0, "subversion": 1}}]}]', endings_json = '[{"id": "landlady.end1", "type": "hidden", "priority": 100, "title": "前夫成了模范租客", "text": "罚单上他亲手签的名字，和公示栏的读数逐月对上。你把新租约改得清清楚楚，沈聿川在每一条后面签了名，从此每月五号准时到账。邻居们改口了：五号不用看日历，看沈聿川的转账提示就行。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 22}}, "posterTag": "隐藏彩蛋", "hint": "选择搜证方向并点击画面闪烁证物收取 >= 4 份，且反派怒气 <= 22 方可解锁"}, {"id": "landlady.end2", "type": "subversive", "priority": 90, "title": "追妻现场改成收租日", "text": "你一次次把追妻现场改成了小区日常，花被搬走，烟花换成垃圾分类，直升机成了晾衣架的新邻居。沈聿川擦着汗：「这是我追过最累的一场。」你（把收据递过去）：「五号，别忘。」", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触发隐藏路线即可解锁"}, {"id": "landlady.end3", "type": "unfinished", "priority": 80, "title": "追妻计划烂尾了", "text": "横幅挂满了整栋楼，租约却没人签。烟花点着半截就被王大爷的灭火器收了场，钟特助的甘特图跳出一行字：第六阶段，待定。你（看着一地花瓣）：「下一部，《前房东的诚恳》，敬请期待。」", "condition": {"minStats": {"anger": 48}}, "posterTag": "喜剧烂尾", "hint": "反派怒气飙升至 >= 48 时触发荒诞翻车烂尾"}, {"id": "landlady.end4", "type": "triumph", "priority": 70, "title": "房租五号准时到账", "text": "你把该收的收了，该拒的拒了。沈聿川交了违约金，换了新租约，钟特助升任楼道管理员。后来他们都后悔了，后悔那天直升机没登记，罚单比花还贵。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健推进主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_03_bazong';

