UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "marriage.ep1", "title": "第 1 集：搭伙协议写了八页", "sceneDesc": "便利店餐桌上，你和刚认识的搭伙对象各签一份搭伙协议：双方自愿，随时可以结束。最醒目的一条加粗写着，垃圾轮流倒。对象扣上笔帽：「第八页也签一下，写的是谁买纸巾。」\\\\n顾表亲推门就进（把对象从头打量到脚，歪嘴一笑）：「骑旧单车的穷鬼，也配进我们顾家门？这婚你离定了！」一张烫金家宴邀请函「啪」地压在协议上，字比你的房租数字还大。\\\\n对象伸手拿纸巾，口袋里掉出一大串钥匙，标签写着一号楼、二号楼和仓库。顾表亲（抢先捡起来晃了晃）：「看见没？物业兼职，看大门的。」对象没解释，伸手把钥匙要了回去。\\\\n顾表亲把邀请函往你跟前一推：「明晚家宴，带不带这位来，你自己掂量。」弹幕已经开始刷下跪预警。", "sceneImage": "/static/art/covers/cover-marriage.jpg", "panels": [{"speaker": "旁白", "text": "便利店餐桌上，你和刚认识的搭伙对象各签一份搭伙协议：双方自愿，随时可以结束。最醒目的一条加粗写着，垃圾轮流倒。对象扣上笔帽：「第八页也签一下，写的是谁买纸巾。」"}, {"speaker": "旁白", "text": "顾表亲推门就进（把对象从头打量到脚，歪嘴一笑）：「骑旧单车的穷鬼，也配进我们顾家门？这婚你离定了！」一张烫金家宴邀请函「啪」地压在协议上，字比你的房租数字还大。"}, {"speaker": "旁白", "text": "对象伸手拿纸巾，口袋里掉出一大串钥匙，标签写着一号楼、二号楼和仓库。顾表亲（抢先捡起来晃了晃）：「看见没？物业兼职，看大门的。」对象没解释，伸手把钥匙要了回去。"}, {"speaker": "旁白", "text": "顾表亲把邀请函往你跟前一推：「明晚家宴，带不带这位来，你自己掂量。」弹幕已经开始刷下跪预警。"}], "choices": [{"choiceId": "marriage_e1_c2", "id": "A", "label": "A", "text": "当众宣布对象深不可测", "styleTag": "离谱反套路", "feedback": "你（一拍桌）：「我对象，深不可测！」全场震惊。顾表亲当场把家宴升格，掏手机拉群：「都来看看。」对象轻轻拽了下你袖子：「没商量就给咱的日子加节目，这算不算违约？」顾表亲在门口回头：「明天我跟着你们，看能装多久。」", "outcome": "你（一拍桌）：「我对象，深不可测！」全场震惊。顾表亲当场把家宴升格，掏手机拉群：「都来看看。」对象轻轻拽了下你袖子：「没商量就给咱的日子加节目，这算不算违约？」顾表亲在门口回头：「明天我跟着你们，看能装多久。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "marriage_e1_c1", "id": "B", "label": "B", "text": "确认协议与钥匙归属", "styleTag": "经典套路", "feedback": "你让对象把每把钥匙的用途写在协议背面，两份各收一份。这时对象的手机亮了，来电显示「叶管家」，屏幕上弹出一条提醒：明早巡店。顾表亲眯起眼：「管家？看大门的还配管家？」", "outcome": "你让对象把每把钥匙的用途写在协议背面，两份各收一份。这时对象的手机亮了，来电显示「叶管家」，屏幕上弹出一条提醒：明早巡店。顾表亲眯起眼：「管家？看大门的还配管家？」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "marriage_e1_c3", "id": "C", "label": "C", "text": "先问今晚谁倒垃圾", "styleTag": "打工人觉醒", "feedback": "你先问：「今晚谁倒垃圾？」对象举手：「轮到我。」顾表亲憋了一肚子的嘲讽卡在嗓子眼。你们把钥匙收好，拎着垃圾袋下楼。顾表亲在楼道里喊：「明天我跟着你们！」", "outcome": "你先问：「今晚谁倒垃圾？」对象举手：「轮到我。」顾表亲憋了一肚子的嘲讽卡在嗓子眼。你们把钥匙收好，拎着垃圾袋下楼。顾表亲在楼道里喊：「明天我跟着你们！」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 2, "number": 2, "id": "marriage.ep2", "title": "第 2 集：黑卡买不来纸袋", "sceneDesc": "第二天，你们去生活社买日用品。对象递出的会员卡没有烫金花纹，只有一个手写编号。顾表亲举着手机跟在后面，镜头对准刷卡机，就等「刷卡失败」那一声。\\\\n收银台果然「嘀」了一声：特殊账户，需人工确认。顾表亲（甩出黑卡）：「刷我的！穷鬼，别在这儿丢人。」店员（双手把黑卡递回去）：「黑卡也得排队。」对象看了眼手机：「叶管家在路上了。��\\\\n店员确认完额度，补了一句：「纸袋按实际数量领。」顾表亲一听没有无限纸袋，嗓门一下拔高：「假卡！叫你们店长来！」\\\\n后面排队的人纷纷探头。卡背面有一行小字，被对象的拇指按住了一半。", "sceneImage": "/static/art/covers/cover-marriage.jpg", "panels": [{"speaker": "旁白", "text": "第二天，你们去生活社买日用品。对象递出的会员卡没有烫金花纹，只有一个手写编号。顾表亲举着手机跟在后面，镜头对准刷卡机，就等「刷卡失败」那一声。"}, {"speaker": "旁白", "text": "收银台果然「嘀」了一声：特殊账户，需人工确认。顾表亲（甩出黑卡）：「刷我的！穷鬼，别在这儿丢人。」店员（双手把黑卡递回去）：「黑卡也得排队。」对象看了眼手机：「叶管家在路上了。」"}, {"speaker": "旁白", "text": "店员确认完额度，补了一句：「纸袋按实际数量领。」顾表亲一听没有无限纸袋，嗓门一下拔高：「假卡！叫你们店长来！」"}, {"speaker": "旁白", "text": "后面排队的人纷纷探头。卡背面有一行小字，被对象的拇指按住了一半。"}], "choices": [{"choiceId": "marriage_e2_c3", "id": "A", "label": "A", "text": "读卡背面的旧店编号", "styleTag": "打工人觉醒", "feedback": "你把卡翻过来，小字是生活社最早那间小店的编号。卡套里还夹着一张开业合影，角落那张脸，眉眼和对象一模一样。对象伸手想拿回去，你先递给了刚进门的叶管家：「先替我们收着。」", "outcome": "你把卡翻过来，小字是生活社最早那间小店的编号。卡套里还夹着一张开业合影，角落那张脸，眉眼和对象一模一样。对象伸手想拿回去，你先递给了刚进门的叶管家：「先替我们收着。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "marriage_e2_c2", "id": "B", "label": "B", "text": "要求包下整个货架证明身份", "styleTag": "离谱反套路", "feedback": "你（一指货架）：「这一排，我们全包了！」对象没接话，店员已经开始喊人盘库存。顾表亲气得直跺脚，后面排队的大妈只想知道谁来把推车挪开。门外喇叭一响，有人喊：「社长的车到了！」", "outcome": "你（一指货架）：「这一排，我们全包了！」对象没接话，店员已经开始喊人盘库存。顾表亲气得直跺脚，后面排队的大妈只想知道谁来把推车挪开。门外喇叭一响，有人喊：「社长的车到了！」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "marriage_e2_c1", "id": "C", "label": "C", "text": "请店员走账户核验流程", "styleTag": "经典套路", "feedback": "你请店员走一遍核验流程。核验单打出持卡权限和当日消费，你把副联折好收进钱包。顾表亲没拍到黑卡甩脸的高光，倒把自己堵住结账通道的全过程拍了个完整。正要删视频，叶管家推门进来：「社长，车到门口了。」", "outcome": "你请店员走一遍核验流程。核验单打出持卡权限和当日消费，你把副联折好收进钱包。顾表亲没拍到黑卡甩脸的高光，倒把自己堵住结账通道的全过程拍了个完整。正要删视频，叶管家推门进来：「社长，车到门口了。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 3, "number": 3, "id": "marriage.ep3", "title": "第 3 集：豪车来接的是纸箱", "sceneDesc": "生活社门口，顾表亲早把你的旧单车推到台阶下，就等它和贵宾车同框。一辆大货车「吱」地停稳，叶管家探出头：「社长，车到了。」全场震惊。后车厢一开，满满一车待回收的纸箱。\\\\n对象二话不说开始搬箱子。顾表亲（举着手机直乐）：「拍到了，打工的证据！」叶管家递上一张轮值表：「社长每月都排仓库班。名字在这儿，跟其他人一样大。」\\\\n围观的人越看越糊涂，这到底是豪门剧还是上班日常？小周同事挤进人群，开口第一句：「仓库周末还缺人吗？我想报名。」一张招募表，把对峙打断了。\\\\n对象拍掉手上的灰，回头问你：「明晚那顿家宴，还去吗？你说不去，咱就不去。」", "sceneImage": "/static/art/covers/cover-marriage.jpg", "panels": [{"speaker": "旁白", "text": "生活社门口，顾表亲早把你的旧单车推到台阶下，就等它和贵宾车同框。一辆大货车「吱」地停稳，叶管家探出头：「社长，车到了。」全场震惊。后车厢一开，满满一车待回收的纸箱。"}, {"speaker": "旁白", "text": "对象二话不说开始搬箱子。顾表亲（举着手机直乐）：「拍到了，打工的证据！」叶管家递上一张轮值表：「社长每月都排仓库班。名字在这儿，跟其他人一样大。」"}, {"speaker": "旁白", "text": "围观的人越看越糊涂，这到底是豪门剧还是上班日常？小周同事挤进人群，开口第一句：「仓库周末还缺人吗？我想报名。」一张招募表，把对峙打断了。"}, {"speaker": "旁白", "text": "对象拍掉手上的灰，回头问你：「明晚那顿家宴，还去吗？你说不去，咱就不去。」"}], "choices": [{"choiceId": "marriage_e3_c1", "id": "A", "label": "A", "text": "展示公开轮值表", "styleTag": "经典套路", "feedback": "你把轮值表举到顾表亲的镜头前：「拍清楚点，名字、日期都在。」叶管家在旁边逐条确认。那段「打工证据」，成了对象按时上班的记录。上车前，你们说好：明晚家宴只讲事实，谁也不替对方摊底。", "outcome": "你把轮值表举到顾表亲的镜头前：「拍清楚点，名字、日期都在。」叶管家在旁边逐条确认。那段「打工证据」，成了对象按时上班的记录。上车前，你们说好：明晚家宴只讲事实，谁也不替对方摊底。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "marriage_e3_c3", "id": "B", "label": "B", "text": "与对象一起把纸箱装完", "styleTag": "打工人觉醒", "feedback": "你撸起袖子，跟对象一起把纸箱码进仓库。顾表亲独自守着精心挑好的对峙机位，一个人也没入镜。小周同事拍了张你们扛箱子的背影发进群里：「比豪车镜头像过日子。」群里第一个回复的是顾表亲：「明晚见。」", "outcome": "你撸起袖子，跟对象一起把纸箱码进仓库。顾表亲独自守着精心挑好的对峙机位，一个人也没入镜。小周同事拍了张你们扛箱子的背影发进群里：「比豪车镜头像过日子。」群里第一个回复的是顾表亲：「明晚见。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "marriage_e3_c2", "id": "C", "label": "C", "text": "把货车当成低调豪车介绍", "styleTag": "离谱反套路", "feedback": "你（拍拍货车车门）：「低调豪车，懂的都懂。」围观的人立刻脑补出八种隐藏功能，顾表亲越听脸越黑。叶管家只好清清嗓子：「车门里，真的没有私人电梯。」顾表亲（冷笑）：「明晚家宴，我等你们出丑。」", "outcome": "你（拍拍货车车门）：「低调豪车，懂的都懂。」围观的人立刻脑补出八种隐藏功能，顾表亲越听脸越黑。叶管家只好清清嗓子：「车门里，真的没有私人电梯。」顾表亲（冷笑）：「明晚家宴，我等你们出丑。」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 4, "number": 4, "id": "marriage.ep4", "title": "第 4 集：饭局菜单比家谱长", "sceneDesc": "家宴开席，顾表亲按身价排座，把你们俩安排在门边上。对象一进门，先看见疏散通道被花架堵住，招手请服务员挪开。顾表亲（坐在主位上冷笑）：「蹭饭的，倒挺会使唤人。」\\\\n顾表亲冲门口喊：「保安！把这两个蹭饭的给我轰出去！」保安翻完名单，抬头：「正式受邀，座位在这儿。」顾表亲又甩出一份资产排行榜，叶管家扫了一眼：「生活社的名字，写错了两个字。」\\\\n主持人把话筒递到你嘴边，满桌亲戚都在等，等你证明自己嫁得值，或者当场摊牌。\\\\n对象（按住话筒，推回你手边）：「这回咱俩一起定，谁也别替谁宣布。」", "sceneImage": "/static/art/covers/cover-marriage.jpg", "panels": [{"speaker": "旁白", "text": "家宴开席，顾表亲按身价排座，把你们俩安排在门边上。对象一进门，先看见疏散通道被花架堵住，招手请服务员挪开。顾表亲（坐在主位上冷笑）：「蹭饭的，倒挺会使唤人。」"}, {"speaker": "旁白", "text": "顾表亲冲门口喊：「保安！把这两个蹭饭的给我轰出去！」保安翻完名单，抬头：「正式受邀，座位在这儿。」顾表亲又甩出一份资产排行榜，叶管家扫了一眼：「生活社的名字，写错了两个字。」"}, {"speaker": "旁白", "text": "主持人把话筒递到你嘴边，满桌亲戚都在等，等你证明自己嫁得值，或者当场摊牌。"}, {"speaker": "旁白", "text": "对象（按住话筒，推回你手边）：「这回咱俩一起定，谁也别替谁宣布。」"}], "choices": [{"choiceId": "marriage_e4_c2", "id": "A", "label": "A", "text": "要求主持按财富重新排座", "styleTag": "离谱反套路", "feedback": "你抬手：「按财富重新排座！」主持人开始搬椅子，家宴成了数字竞赛，顾表亲越比越上头。对象皱眉凑到你耳边：「协议里没有哪一条，要靠压过亲戚来证明咱俩合适。」说完，先离了席。", "outcome": "你抬手：「按财富重新排座！」主持人开始搬椅子，家宴成了数字竞赛，顾表亲越比越上头。对象皱眉凑到你耳边：「协议里没有哪一条，要靠压过亲戚来证明咱俩合适。」说完，先离了席。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "marriage_e4_c3", "id": "B", "label": "B", "text": "把所有椅子排成一圈", "styleTag": "打工人觉醒", "feedback": "你（把所有椅子拉成一圈）：「圆桌，没有主位。」大家总算能好好吃饭。顾表亲抱着座位图转了三圈，不知道该把中心画在哪儿。散席时，叶管家拦住你：「社长有话，想单独跟您说。」", "outcome": "你（把所有椅子拉成一圈）：「圆桌，没有主位。」大家总算能好好吃饭。顾表亲抱着座位图转了三圈，不知道该把中心画在哪儿。散席时，叶管家拦住你：「社长有话，想单独跟您说。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "marriage_e4_c1", "id": "C", "label": "C", "text": "只展示已公开的任职资料", "styleTag": "经典套路", "feedback": "你和对象小声对过一遍，只把能公开的任职资料投上屏幕。顾表亲的排行榜被服务员拿去垫了摇晃的桌脚，总算派上了用场。叶管家合上平板，低声对对象说：「社长，该坦白的，今晚得说了。」", "outcome": "你和对象小声对过一遍，只把能公开的任职资料投上屏幕。顾表亲的排行榜被服务员拿去垫了摇晃的桌脚，总算派上了用场。叶管家合上平板，低声对对象说：「社长，该坦白的，今晚得说了。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 5, "number": 5, "id": "marriage.ep5", "title": "第 5 集：首富身份不抵家务", "sceneDesc": "叶管家把任职文件和资产管理文件放到桌上。对象（深吸一口气）：「我才是真正的董事长。准确地说，是社长。」顿了顿，又补一句：「骑单车，是因为那条路不堵。」\\\\n你（把文件推回去）：「瞒了我这么久，我心里堵。」对象没找借口，低头道歉：「以后有事，先跟你商量。协议你想重谈就重谈，想停就停。」\\\\n门外，顾表亲正在搭第二轮揭晓，一面灯墙，灯泡拼出「首富」两个大字。屋里的桌上，财务边界和家务轮值还空着，一条都没写。\\\\n叶管家把一份可公开的副本推到你面前：「要留证，现在盖章。」灯墙的光从门缝里漏进来，顾表亲在外头喊你出去拍照。", "sceneImage": "/static/art/covers/cover-marriage.jpg", "panels": [{"speaker": "旁白", "text": "叶管家把任职文件和资产管理文件放到桌上。对象（深吸一口气）：「我才是真正的董事长。准确地说，是社长。」顿了顿，又补一句：「骑单车，是因为那条路不堵。」"}, {"speaker": "旁白", "text": "你（把文件推回去）：「瞒了我这么久，我心里堵。」对象没找借口，低头道歉：「以后有事，先跟你商量。协议你想重谈就重谈，想停就停。」"}, {"speaker": "旁白", "text": "门外，顾表亲正在搭第二轮揭晓，一面灯墙，灯泡拼出「首富」两个大字。屋里的桌上，财务边界和家务轮值还空着，一条都没写。"}, {"speaker": "旁白", "text": "叶管家把一份可公开的副本推到你面前：「要留证，现在盖章。」灯墙的光从门缝里漏进来，顾表亲在外头喊你出去拍照。"}], "choices": [{"choiceId": "marriage_e5_c1", "id": "A", "label": "A", "text": "存档公开文件，重签搭伙协议", "styleTag": "经典套路", "feedback": "你们一条条确认哪些能公开、哪些只放抽屉，副本按授权留了档。万能对象没有，倒多了一份写得更清楚的搭伙协议，第一条还是垃圾轮流倒。叶管家收好副本：「收官那天，顾家人都会来。」", "outcome": "你们一条条确认哪些能公开、哪些只放抽屉，副本按授权留了档。万能对象没有，倒多了一份写得更清楚的搭伙协议，第一条还是垃圾轮流倒。叶管家收好副本：「收官那天，顾家人都会来。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "marriage_e5_c2", "id": "B", "label": "B", "text": "先去灯墙下拍首富合照", "styleTag": "离谱反套路", "feedback": "你出门站到灯墙下，顾表亲忙着往墙上加灯泡，越加越亮。屋里的家务轮值表还是一片空白。对象在门口提醒你：「明天快递谁收？灯墙可不会签字。」顾表亲在身后喊：「明天收官，我请全城来看！」", "outcome": "你出门站到灯墙下，顾表亲忙着往墙上加灯泡，越加越亮。屋里的家务轮值表还是一片空白。对象在门口提醒你：「明天快递谁收？灯墙可不会签字。」顾表亲在身后喊：「明天收官，我请全城来看！」", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "marriage_e5_c3", "id": "C", "label": "C", "text": "把社长也排进洗碗轮值", "styleTag": "打工人觉醒", "feedback": "你先把社长排进洗碗轮值，一周两天。灯墙在外面闪，你们在屋里对日历。叶管家看着那张表，头一回觉得自己能准点下班。门外，顾表亲已经在印收官请柬。", "outcome": "你先把社长排进洗碗轮值，一周两天。灯墙在外面闪，你们在屋里对日历。叶管家看着那张表，头一回觉得自己能准点下班。门外，顾表亲已经在印收官请柬。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 6, "number": 6, "id": "marriage.ep6", "title": "第 6 集：全城震惊不如垃圾清空", "sceneDesc": "收官这天，顾表亲带着最后一张财富竞猜表登门，正撞见对象蹲在地上分垃圾。首富身份一揭开，全城震惊，地上的纸箱可一个也没自己走出去。\\\\n叶管家核对能公开的资料，小周同事拎来一份普通的乔迁礼。顾表亲（把竞猜表拍在桌上）：「说吧，到底几个亿？」对象没看那张表，看着你。\\\\n主持人张口就喊：「全场跪下！」有人膝盖都弯了，眼看要当场下跪，字幕紧急更正：全场让开，垃圾车要进场了。门口自动让出一条路，低调出场的主角是一只塞得满满的纸袋。\\\\n垃圾车的倒车提示音在门外一声接一声。这段关系怎么收，最后一句由你说。", "sceneImage": "/static/art/covers/cover-marriage.jpg", "panels": [{"speaker": "旁白", "text": "收官这天，顾表亲带着最后一张财富竞猜表登门，正撞见对象蹲在地上分垃圾。首富身份一揭开，全城震惊，地上的纸箱可一个也没自己走出去。"}, {"speaker": "旁白", "text": "叶管家核对能公开的资料，小周同事拎来一份普通的乔迁礼。顾表亲（把竞猜表拍在桌上）：「说吧，到底几个亿？」对象没看那张表，看着你。"}, {"speaker": "旁白", "text": "主持人张口就喊：「全场跪下！」有人膝盖都弯了，眼看要当场下跪，字幕紧急更正：全场让开，垃圾车要进场了。门口自动让出一条路，低调出场的主角是一只塞得满满的纸袋。"}, {"speaker": "旁白", "text": "垃圾车的倒车提示音在门外一声接一声。这段关系怎么收，最后一句由你说。"}], "choices": [{"choiceId": "marriage_e6_c3", "id": "A", "label": "A", "text": "宣布本剧下一集只拍洗碗", "styleTag": "打工人觉醒", "feedback": "你宣布：「本剧下一集，只拍洗碗。」小周同事第一个举手，想看看洗碗机到底能塞下多少碗。顾表亲放下竞猜表凑过来跟着数，头一回加入了一场跟钱无关的讨论。", "outcome": "你宣布：「本剧下一集，只拍洗碗。」小周同事第一个举手，想看看洗碗机到底能塞下多少碗。顾表亲放下竞猜表凑过来跟着数，头一回加入了一场跟钱无关的讨论。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "marriage_e6_c1", "id": "B", "label": "B", "text": "把真实信息与边界一同讲清", "styleTag": "经典套路", "feedback": "你在授权范围内把身份讲清楚，顾表亲张了几次嘴，没找到能改的字。对象接过话，把搭伙协议也讲明白：「钱的事有信托管，日子的事，我们俩管。」", "outcome": "你在授权范围内把身份讲清楚，顾表亲张了几次嘴，没找到能改的字。对象接过话，把搭伙协议也讲明白：「钱的事有信托管，日子的事，我们俩管。」", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "marriage_e6_c2", "id": "C", "label": "C", "text": "让灯墙继续亮到天明", "styleTag": "离谱反套路", "feedback": "你（一挥手）：「灯墙，亮到天明！」所有人都知道你们身份不凡了。顾表亲却开始追问下一场更大的证明，你们解释了一整夜，锅里的饭凉透了。", "outcome": "你（一挥手）：「灯墙，亮到天明！」所有人都知道你们身份不凡了。顾表亲却开始追问下一场更大的证明，你们解释了一整夜，锅里的饭凉透了。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}]', endings_json = '[{"id": "marriage.end1", "type": "hidden", "priority": 100, "title": "首富也要报销纸袋", "text": "开业合影和第五集的存档副本摆在一起，对象最舍不得的，是从一间小店起步的那段日子。你们一起重写协议，收官海报上最大的一行字是：纸袋自备。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 42}}, "posterTag": "隐藏彩蛋", "hint": "选择搜证方向并点击画面闪烁证物收取 >= 4 份，且反派怒气 <= 42 方可解锁"}, {"id": "marriage.end2", "type": "subversive", "priority": 90, "title": "我们只是高效室友", "text": "你不让身份决定关系，两人守着各自的边界，日常开销按时平摊。全城等着的豪门大戏，最后收在一张格外清楚的家务表上。", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触及隐藏或烂尾即可解锁"}, {"id": "marriage.end3", "type": "unfinished", "priority": 80, "title": "闪婚宣传片尚未完工", "text": "灯墙一面接一面地加，能信的材料一张也没留下。顾表亲宣布还要再揭晓一次，字幕弹出提醒：本剧到现在，还没吃上一顿安生饭。", "condition": {"minStats": {"anger": 60}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气累计 >= 60 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "marriage.end4", "type": "triumph", "priority": 70, "title": "有钱，碗也得自己洗", "text": "公开资料一亮，闲话自己停了，关系由你们俩商量着定。晚饭后对象自觉去洗碗，叶管家把那条首富专用围裙叠得方方正正。当初嫌搬纸箱累的几位，如今抢着问还有没有箱子要搬。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_04_baomu';

-- 更新剧本《前夫哥给爷爬》(script_05_reborn) 分集选项顺序/证物配置与结局提示
UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "reborn.ep1", "title": "第 1 集：睁眼是彩排日", "sceneDesc": "闹钟一响，手机日历跳出一行字：订婚宴，明天。你对着屏幕愣了三秒——上一世的最后一眼，是第九十九条催收短信，这一世的第一眼，是婚庆公司发来的彩排通知。\\\\n宋景明（把一份「婚前保证书」推到你手边，歪嘴一笑）：「亲爱的，长辈们想走个形式，签个字就行。你不信我吗？」林栀端着气泡水凑过来：「快签呀，不签显得你不信他。」\\\\n这一幕你太熟了，前世就是在这儿点的头。保证书最后一页印着「连带责任，自动续期」，字小得像蚂蚁搬家。司仪老马举着话筒在后面试音：「喂喂，新人签字，全场鼓掌！」\\\\n一圈亲戚围上来，宋景明已经把笔塞进你指缝。你摸出手机，备忘录是空白的：前世吃亏，就吃在什么都没留下。这一世记下一条，订婚宴那天就能多用一条。", "sceneImage": "/static/art/covers/cover-reborn.jpg", "panels": [{"speaker": "旁白", "text": "闹钟一响，手机日历跳出一行字：订婚宴，明天。你对着屏幕愣了三秒——上一世的最后一眼，是第九十九条催收短信，这一世的第一眼，是婚庆公司发来的彩排通知。"}, {"speaker": "旁白", "text": "宋景明（把一份「婚前保证书」推到你手边，歪嘴一笑）：「亲爱的，长辈们想走个形式，签个字就行。你不信我吗？」林栀端着气泡水凑过来：「快签呀，不签显得你不信他。」"}, {"speaker": "旁白", "text": "这一幕你太熟了，前世就是在这儿点的头。保证书最后一页印着「连带责任，自动续期」，字小得像蚂蚁搬家。司仪老马举着话筒在后面试音：「喂喂，新人签字，全场鼓掌！」"}, {"speaker": "旁白", "text": "一圈亲戚围上来，宋景明已经把笔塞进你指缝。你摸出手机，备忘录是空白的：前世吃亏，就吃在什么都没留下。这一世记下一条，订婚宴那天就能多用一条。"}], "choices": [{"choiceId": "reborn_e1_c3", "id": "A", "label": "A", "text": "说要试婚纱，转身出门", "styleTag": "打工人觉醒", "feedback": "你一句「婚纱还差最后一次试穿」，拎包就走。宋景明在后面喊：「那保证书呢？」你（头也不回）：「订婚不是明天吗，急什么。」出租车一路开到婚纱店门口，门铃「叮」地响了一声。", "outcome": "你一句「婚纱还差最后一次试穿」，拎包就走。宋景明在后面喊：「那保证书呢？」你（头也不回）：「订婚不是明天吗，急什么。」出租车一路开到婚纱店门口，门铃「叮」地响了一声。", "qualityBonus": 15, "effects": {"pleasure": 5, "drama": 7, "anger": -3, "evidence": 0, "subversion": 1}}, {"choiceId": "reborn_e1_c2", "id": "B", "label": "B", "text": "当场宣布我是重生的", "styleTag": "离谱反套路", "feedback": "你（声音一下拔高）：「我重生了！你们的好日子到头了！」全场安静三秒，二姨小声问：「孩子是不是紧张烧糊涂了？」宋景明立刻握住你的手：「她就是压力大。」你的复仇宣言，被他演成了体贴。", "outcome": "你（声音一下拔高）：「我重生了！你们的好日子到头了！」全场安静三秒，二姨小声问：「孩子是不是紧张烧糊涂了？」宋景明立刻握住你的手：「她就是压力大。」你的复仇宣言，被他演成了体贴。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 16, "anger": 12, "evidence": 0, "subversion": 0}}, {"choiceId": "reborn_e1_c1", "id": "C", "label": "C", "text": "读完保证书，第九条记进备忘录", "styleTag": "经典套路", "feedback": "你从头念到尾，念到第九条故意拖长音：「乙方对甲方一切债务，自愿无限连带——」亲戚们的脸色一个接一个变。宋景明（愣了一下，把笔抽回去）：「这个……我回头让律师再看一眼。」你低头在备忘录里敲下一行：第九条，自愿无限连带。林栀灌了一大口气泡水，呛着了。", "outcome": "你从头念到尾，念到第九条故意拖长音：「乙方对甲方一切债务，自愿无限连带——」亲戚们的脸色一个接一个变。宋景明（愣了一下，把笔抽回去）：「这个……我回头让律师再看一眼。」你低头在备忘录里敲下一行：第九条，自愿无限连带。林栀灌了一大口气泡水，呛着了。", "qualityBonus": 12, "effects": {"pleasure": 6, "drama": 9, "anger": 2, "evidence": 1, "subversion": 0}}]}, {"ep": 2, "number": 2, "id": "reborn.ep2", "title": "第 2 集：婚纱店的内袋", "sceneDesc": "婚纱店里，店员捧来第三套试穿款。前世你来试的这天，宋景明说在忙，陪你的只有林栀。这回她又准时出现在试衣间门口，手里拿着你的手机：「我帮你拿着，省得掉。」\\\\n林栀（把手机往身后一藏，抢先一笑）：「宋哥让我提醒你，晚上彩排别迟到。」店员压低声音：「小姐，这件婚纱的内袋是后缝上去的，您要不要摸一摸？」\\\\n你刚要伸手，林栀背后的手机「叮」地一响，屏幕亮出半行字：保证金已到账。她面不改色：「广告，现在广告真多。」\\\\n试衣间外传来顾策划的声音：「三点彩排，机位我都架好了！」店员举着内袋的线头，林栀攥着你的手机，三件事挤在一起，你只顾得上一头。", "sceneImage": "/static/art/covers/cover-reborn.jpg", "panels": [{"speaker": "旁白", "text": "婚纱店里，店员捧来第三套试穿款。前世你来试的这天，宋景明说在忙，陪你的只有林栀。这回她又准时出现在试衣间门口，手里拿着你的手机：「我帮你拿着，省得掉。」"}, {"speaker": "旁白", "text": "林栀（把手机往身后一藏，抢先一笑）：「宋哥让我提醒你，晚上彩排别迟到。」店员压低声音：「小姐，这件婚纱的内袋是后缝上去的，您要不要摸一摸？」"}, {"speaker": "旁白", "text": "你刚要伸手，林栀背后的手机「叮」地一响，屏幕亮出半行字：保证金已到账。她面不改色：「广告，现在广告真多。」"}, {"speaker": "旁白", "text": "试衣间外传来顾策划的声音：「三点彩排，机位我都架好了！」店员举着内袋的线头，林栀攥着你的手机，三件事挤在一起，你只顾得上一头。"}], "choices": [{"choiceId": "reborn_e2_c1", "id": "A", "label": "A", "text": "要回手机，截下「保证金」通知", "styleTag": "经典套路", "feedback": "你（伸手）：「手机。」林栀笑着不松，你就着她的手指点开通知栏，把那行字截了下来，对着店员亮了亮：「麻烦做个见证，这是我的手机。」店员默默点头。林栀的笑僵在脸上，半行「保证金」已经躺进了你的备忘录。", "outcome": "你（伸手）：「手机。」林栀笑着不松，你就着她的手指点开通知栏，把那行字截了下来，对着店员亮了亮：「麻烦做个见证，这是我的手机。」店员默默点头。林栀的笑僵在脸上，半行「保证金」已经躺进了你的备忘录。", "qualityBonus": 12, "effects": {"pleasure": 6, "drama": 9, "anger": 2, "evidence": 1, "subversion": 0}}, {"choiceId": "reborn_e2_c3", "id": "B", "label": "B", "text": "听店员的，摸一摸内袋", "styleTag": "打工人觉醒", "feedback": "你把手伸进内袋，摸出一张折成小方块的便签。笔迹是你自己的，墨迹还没干，可你分明还没写过。便签只有一行：「彩排别躲镜头，让顾策划全程录下来。」林栀凑过来：「什么东西？」你（哽咽了一下，把便签攥紧）：「发票。」", "outcome": "你把手伸进内袋，摸出一张折成小方块的便签。笔迹是你自己的，墨迹还没干，可你分明还没写过。便签只有一行：「彩排别躲镜头，让顾策划全程录下来。」林栀凑过来：「什么东西？」你（哽咽了一下，把便签攥紧）：「发票。」", "qualityBonus": 15, "effects": {"pleasure": 5, "drama": 8, "anger": -3, "evidence": 0, "subversion": 1}}, {"choiceId": "reborn_e2_c2", "id": "C", "label": "C", "text": "指着林栀说她的剧本我看过", "styleTag": "离谱反套路", "feedback": "你（指着林栀）：「姐妹，你的剧本我看过，下一句是“我都是为你好”。」林栀张嘴：「我都是……」后半句被她硬生生咽了回去，你把这半句记进了备忘录。店员鼓起了掌，内袋的线头还在原地晃。", "outcome": "你（指着林栀）：「姐妹，你的剧本我看过，下一句是“我都是为你好”。」林栀张嘴：「我都是……」后半句被她硬生生咽了回去，你把这半句记进了备忘录。店员鼓起了掌，内袋的线头还在原地晃。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 14, "anger": 10, "evidence": 1, "subversion": 0}}]}, {"ep": 3, "number": 3, "id": "reborn.ep3", "title": "彩排厅里的第九页", "sceneDesc": "宴会厅里，大屏幕循环播着「我们的故事」，主题曲一响，你下意识接唱出下一句。司仪老马瞪圆了眼：「新人这么熟？这首歌我们今天才定的。」前世你听它循环了一整晚。\\\\n宋景明（整了整袖口，抢先接话）：「她天天听，当然熟。」顾策划拿着流程表走过来：「临时加了个环节，签署仪式，大家要看着新人签。」\\\\n老马举起话筒现场加戏：「有请新人上台，签下爱的契约！」后排亲戚齐刷刷举起手机。大屏幕偏在这时切到下一页，第九条的字号还是蚂蚁级别。\\\\n话筒递到你手里，三百双眼睛顶着你。前世这一段，你说的是「我愿意」。今天台词本在你手上，翻哪一页，你自己拿主意。", "sceneImage": "/static/art/covers/cover-reborn.jpg", "panels": [{"speaker": "旁白", "text": "宴会厅里，大屏幕循环播着「我们的故事」，主题曲一响，你下意识接唱出下一句。司仪老马瞪圆了眼：「新人这么熟？这首歌我们今天才定的。」前世你听它循环了一整晚。"}, {"speaker": "旁白", "text": "宋景明（整了整袖口，抢先接话）：「她天天听，当然熟。」顾策划拿着流程表走过来：「临时加了个环节，签署仪式，大家要看着新人签。」"}, {"speaker": "旁白", "text": "老马举起话筒现场加戏：「有请新人上台，签下爱的契约！」后排亲戚齐刷刷举起手机。大屏幕偏在这时切到下一页，第九条的字号还是蚂蚁级别。"}, {"speaker": "旁白", "text": "话筒递到你手里，三百双眼睛顶着你。前世这一段，你说的是「我愿意」。今天台词本在你手上，翻哪一页，你自己拿主意。"}], "choices": [{"choiceId": "reborn_e3_c2", "id": "A", "label": "A", "text": "抢过话筒当众宣布复仇", "styleTag": "离谱反套路", "feedback": "你（抢过话筒）：「宋景明，你的末日到了！」全场哗然。老马反应极快，当场接话：「感谢新人带来的开场节目——复仇脱口秀！」亲戚们笑着鼓掌。你的狠话成了暖场，宋景明在台下鼓得最响。", "outcome": "你（抢过话筒）：「宋景明，你的末日到了！」全场哗然。老马反应极快，当场接话：「感谢新人带来的开场节目——复仇脱口秀！」亲戚们笑着鼓掌。你的狠话成了暖场，宋景明在台下鼓得最响。", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 16, "anger": 12, "evidence": 0, "subversion": 0}}, {"choiceId": "reborn_e3_c3", "id": "B", "label": "B", "text": "接过话筒，把主题曲唱完", "styleTag": "打工人觉醒", "feedback": "你把主题曲从头唱到尾，老马配合着打拍子，亲戚们跟着挥手机灯。宋景明站在台下，表情像在等一场不会再来的签字。老马擦着汗：「新人这一嗓子，今晚预算值了。」", "outcome": "你把主题曲从头唱到尾，老马配合着打拍子，亲戚们跟着挥手机灯。宋景明站在台下，表情像在等一场不会再来的签字。老马擦着汗：「新人这一嗓子，今晚预算值了。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 8, "anger": -4, "evidence": 0, "subversion": 1}}, {"choiceId": "reborn_e3_c1", "id": "C", "label": "C", "text": "把第九条放大到整面屏幕", "styleTag": "经典套路", "feedback": "你（让顾策划把第九条放大到整面墙）：「各位亲友，请大家一起读一读。」老马接过话筒，只好跟着念：「自愿无限连带……」念到一半他自己停了：「这条，是不是有点重？」宋景明的领结松了半格。", "outcome": "你（让顾策划把第九条放大到整面墙）：「各位亲友，请大家一起读一读。」老马接过话筒，只好跟着念：「自愿无限连带……」念到一半他自己停了：「这条，是不是有点重？」宋景明的领结松了半格。", "qualityBonus": 12, "effects": {"pleasure": 5, "drama": 10, "anger": 2, "evidence": 1, "subversion": 0}}]}, {"ep": 4, "number": 4, "id": "reborn.ep4", "title": "第 4 集：他在走廊对暗号", "sceneDesc": "晚饭后，酒店走廊的消防门边，宋景明把你拉到墙角，压低声音：「我昨晚做了个很长的梦，梦里你什么都听我的。你也梦到了吗？」他眼睛死死盯着你的反应。\\\\n你后背一紧：他也回来了？还是在试探？走廊尽头，林栀探头喊：「宋哥，投影仪调好了，明天那页放哪？」宋景明挥手让她闭嘴，手背上全是汗。\\\\n远处传来司仪老马试麦的声音：「一二三，新人在哪儿——新人在哪儿——」消防门后的灯忽明忽暗，像在催你开口。顾策划的机位小红灯，从走廊另一头静静亮着。\\\\n他要的是一句暗号。这一句接得好，他放松；接得不好，他加快。你得在三秒内决定怎么答。", "sceneImage": "/static/art/covers/cover-reborn.jpg", "panels": [{"speaker": "旁白", "text": "晚饭后，酒店走廊的消防门边，宋景明把你拉到墙角，压低声音：「我昨晚做了个很长的梦，梦里你什么都听我的。你也梦到了吗？」他眼睛死死盯着你的反应。"}, {"speaker": "旁白", "text": "你后背一紧：他也回来了？还是在试探？走廊尽头，林栀探头喊：「宋哥，投影仪调好了，明天那页放哪？」宋景明挥手让她闭嘴，手背上全是汗。"}, {"speaker": "旁白", "text": "远处传来司仪老马试麦的声音：「一二三，新人在哪儿——新人在哪儿——」消防门后的灯忽明忽暗，像在催你开口。顾策划的机位小红灯，从走廊另一头静静亮着。"}, {"speaker": "旁白", "text": "他要的是一句暗号。这一句接得好，他放松；接得不好，他加快。你得在三秒内决定怎么答。"}], "choices": [{"choiceId": "reborn_e4_c1", "id": "A", "label": "A", "text": "反问他梦里我最爱吃什么", "styleTag": "经典套路", "feedback": "你（抬了抬下巴）：「那你说说，梦里我最爱吃什么？」宋景明脱口而出：「香菜！」你（冷静看着他）：「我从来不吃香菜。」他的脸一下白了，像刚出锅的馒头。他没有重生，只是在试探。你把「香菜」这一条记进了备忘录。", "outcome": "你（抬了抬下巴）：「那你说说，梦里我最爱吃什么？」宋景明脱口而出：「香菜！」你（冷静看着他）：「我从来不吃香菜。」他的脸一下白了，像刚出锅的馒头。他没有重生，只是在试探。你把「香菜」这一条记进了备忘录。", "qualityBonus": 12, "effects": {"pleasure": 6, "drama": 10, "anger": 2, "evidence": 1, "subversion": 0}}, {"choiceId": "reborn_e4_c2", "id": "B", "label": "B", "text": "凑近说全记得，包括路由器密码", "styleTag": "离谱反套路", "feedback": "你（凑到他耳边）：「我全记得，连你家路由器密码，八个八。」他倒吸一口气，连退三步，撞响了墙边的灭火器。林栀探头：「怎么了？」他结结巴巴：「没……没事，消防演习。」你接得很满，他的警惕也满了。", "outcome": "你（凑到他耳边）：「我全记得，连你家路由器密码，八个八。」他倒吸一口气，连退三步，撞响了墙边的灭火器。林栀探头：「怎么了？」他结结巴巴：「没……没事，消防演习。」你接得很满，他的警惕也满了。", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 15, "anger": 12, "evidence": 0, "subversion": 0}}, {"choiceId": "reborn_e4_c3", "id": "C", "label": "C", "text": "说梦里只吃了顿火锅", "styleTag": "打工人觉醒", "feedback": "你（一脸茫然）：「梦？我只梦到一顿火锅，没吃完就醒了。」宋景明盯着你看了半天，慢慢靠在墙上，松了口气：「睡不好才会这样。」他以为你什么都不知道。你这顿没吃完的火锅，倒成了最好的掩护。", "outcome": "你（一脸茫然）：「梦？我只梦到一顿火锅，没吃完就醒了。」宋景明盯着你看了半天，慢慢靠在墙上，松了口气：「睡不好才会这样。」他以为你什么都不知道。你这顿没吃完的火锅，倒成了最好的掩护。", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 10, "anger": -3, "evidence": 0, "subversion": 1}}]}, {"ep": 5, "number": 5, "id": "reborn.ep5", "title": "第 5 集：存储卡里的三小时", "sceneDesc": "彩排收尾，顾策划抱着三张存储卡过来：「新人，今晚三台机位的录像都在这儿，我按流程存档。」宋景明笑着伸手拦：「彩排录像留着不吉利，删了吧，还省内存。」\\\\n林栀已经把读卡器接上笔记本，光标悬在「全部删除」上。司仪老马打圆场：「按咱们行规，彩排不留底，图个吉利！」他说话时，手里的台本翻到了折角的那一页。\\\\n顾策划（一手护着存储卡，一手指着屏幕）：「我们公司有规矩，没得到新人同意，一个文件都不动。」全厅的人看向你，这个同意权，只在你手里。\\\\n光标闪着，读卡器亮着，三张存储卡还捏在顾策划手里。录像留不留、怎么留，只差你一句话。明天订婚宴上能当场用几条，要看备忘录里记了几条。", "sceneImage": "/static/art/covers/cover-reborn.jpg", "panels": [{"speaker": "旁白", "text": "彩排收尾，顾策划抱着三张存储卡过来：「新人，今晚三台机位的录像都在这儿，我按流程存档。」宋景明笑着伸手拦：「彩排录像留着不吉利，删了吧，还省内存。」"}, {"speaker": "旁白", "text": "林栀已经把读卡器接上笔记本，光标悬在「全部删除」上。司仪老马打圆场：「按咱们行规，彩排不留底，图个吉利！」他说话时，手里的台本翻到了折角的那一页。"}, {"speaker": "旁白", "text": "顾策划（一手护着存储卡，一手指着屏幕）：「我们公司有规矩，没得到新人同意，一个文件都不动。」全厅的人看向你，这个同意权，只在你手里。"}, {"speaker": "旁白", "text": "光标闪着，读卡器亮着，三张存储卡还捏在顾策划手里。录像留不留、怎么留，只差你一句话。明天订婚宴上能当场用几条，要看备忘录里记了几条。"}], "choices": [{"choiceId": "reborn_e5_c3", "id": "A", "label": "A", "text": "把录像刻成光盘分给亲戚", "styleTag": "打工人觉醒", "feedback": "你宣布把录像刻成纪念光盘，每位亲戚一张。亲戚们排队领光盘，二姨还问封面能不能写祝福语。可没人知道哪一张是原件。顾策划小声说：「这样……也算存了。」", "outcome": "你宣布把录像刻成纪念光盘，每位亲戚一张。亲戚们排队领光盘，二姨还问封面能不能写祝福语。可没人知道哪一张是原件。顾策划小声说：「这样……也算存了。」", "qualityBonus": 15, "effects": {"pleasure": 5, "drama": 8, "anger": -3, "evidence": 0, "subversion": 1}}, {"choiceId": "reborn_e5_c1", "id": "B", "label": "B", "text": "请顾策划当场备份并封存", "styleTag": "经典套路", "feedback": "你（点头）：「麻烦顾策划，现场拷一份，原卡我自己拿。」顾策划当场备份，用封条把存储卡封好，又在备份盘上写了时间。宋景明脸上的笑像卡在百分之九十九的缓冲条。林栀默默把鼠标放回了桌上。", "outcome": "你（点头）：「麻烦顾策划，现场拷一份，原卡我自己拿。」顾策划当场备份，用封条把存储卡封好，又在备份盘上写了时间。宋景明脸上的笑像卡在百分之九十九的缓冲条。林栀默默把鼠标放回了桌上。", "qualityBonus": 12, "effects": {"pleasure": 7, "drama": 9, "anger": 2, "evidence": 1, "subversion": 0}}, {"choiceId": "reborn_e5_c2", "id": "C", "label": "C", "text": "让老马当场放精彩回放", "styleTag": "离谱反套路", "feedback": "你让老马放精彩回放，大屏幕亮起来，亲戚们看得挺欢。可存储卡还插在读卡器里，林栀手快，顺手点了个格式化。回放放到一半，画面黑了。老马对着话筒：「各位，后半段需要开会员。」", "outcome": "你让老马放精彩回放，大屏幕亮起来，亲戚们看得挺欢。可存储卡还插在读卡器里，林栀手快，顺手点了个格式化。回放放到一半，画面黑了。老马对着话筒：「各位，后半段需要开会员。」", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 16, "anger": 12, "evidence": 0, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "reborn.ep6", "title": "第 6 集：鼓掌不等于同意", "sceneDesc": "订婚宴开场，三百位宾客就座，大屏幕亮起「我们的故事」。宋景明（整了整袖口，抬手示意）：「各位，我说两句。」他身后，服务员端着盖红绸的托盘上台，保证书压在最下面。\\\\n司仪老马举着话筒，深吸一口气：「接下来是本场最重要的环节——」台本被他翻到了第九页。林栀在台下举着手机，像在等一场早就写好的直播。\\\\n你抬头看了一眼大屏幕左上角，有个不起眼的小红点，是顾策划的机位，一直开着。前世你错过的每一步，今天都有镜头对着。\\\\n话筒、笔、镜头，全都对着你。复仇不用排练，最后一句，你来说。", "sceneImage": "/static/art/covers/cover-reborn.jpg", "panels": [{"speaker": "旁白", "text": "订婚宴开场，三百位宾客就座，大屏幕亮起「我们的故事」。宋景明（整了整袖口，抬手示意）：「各位，我说两句。」他身后，服务员端着盖红绸的托盘上台，保证书压在最下面。"}, {"speaker": "旁白", "text": "司仪老马举着话筒，深吸一口气：「接下来是本场最重要的环节——」台本被他翻到了第九页。林栀在台下举着手机，像在等一场早就写好的直播。"}, {"speaker": "旁白", "text": "你抬头看了一眼大屏幕左上角，有个不起眼的小红点，是顾策划的机位，一直开着。前世你错过的每一步，今天都有镜头对着。"}, {"speaker": "旁白", "text": "话筒、笔、镜头，全都对着你。复仇不用排练，最后一句，你来说。"}], "choices": [{"choiceId": "reborn_e6_c2", "id": "A", "label": "A", "text": "掀开红绸，摔了托盘喊你们完了", "styleTag": "离谱反套路", "feedback": "你一把掀开红绸，把托盘摔在地上：「宋景明，你的好日子到头了！」全场惊呼。宋景明立刻举手：「大家看，她情绪失控了。」老马接话：「新人压力大，掌声鼓励一下。」你站在满地红绸里，一件东西也递不到大家手上。", "outcome": "你一把掀开红绸，把托盘摔在地上：「宋景明，你的好日子到头了！」全场惊呼。宋景明立刻举手：「大家看，她情绪失控了。」老马接话：「新人压力大，掌声鼓励一下。」你站在满地红绸里，一件东西也递不到大家手上。", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 18, "anger": 14, "evidence": 0, "subversion": 0}}, {"choiceId": "reborn_e6_c1", "id": "B", "label": "B", "text": "拆封播放，把备忘录一条条对上", "styleTag": "经典套路", "feedback": "你请顾策划拆封，大屏幕上宋景明、林栀、老马的彩排一帧不少：保证书、台本折角、「保证金已到账」的提示音。你对着手机备忘录一条条点名，记下几条，就能对上几条。宋景明张了张嘴，没找到顺手的词，台下二姨第一个开口，说这孩子差点替人背了锅。他手里的笔，没人再接。", "outcome": "你请顾策划拆封，大屏幕上宋景明、林栀、老马的彩排一帧不少：保证书、台本折角、「保证金已到账」的提示音。你对着手机备忘录一条条点名，记下几条，就能对上几条。宋景明张了张嘴，没找到顺手的词，台下二姨第一个开口，说这孩子差点替人背了锅。他手里的笔，没人再接。", "qualityBonus": 12, "effects": {"pleasure": 8, "drama": 10, "anger": 2, "evidence": 1, "subversion": 0}}, {"choiceId": "reborn_e6_c3", "id": "C", "label": "C", "text": "宣布订婚宴改成火锅宴", "styleTag": "打工人觉醒", "feedback": "你（接过话筒）：「今天不订婚了，涮火锅。锅底免费，保证书自愿阅读。」服务员推来一桌桌铜锅，亲戚们边涮边传阅保证书，传到第三桌，有人说：「这条不对劲。」宋景明端着蘸料碗坐在主桌，不知道该蘸什么。", "outcome": "你（接过话筒）：「今天不订婚了，涮火锅。锅底免费，保证书自愿阅读。」服务员推来一桌桌铜锅，亲戚们边涮边传阅保证书，传到第三桌，有人说：「这条不对劲。」宋景明端着蘸料碗坐在主桌，不知道该蘸什么。", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 9, "anger": -2, "evidence": 0, "subversion": 1}}]}]', endings_json = '[{"id": "reborn.end1", "type": "hidden", "priority": 100, "title": "这一世我自己剪片", "text": "备忘录里的第九条、相册里的保证金截图，和彩排录像的时间码一一对上。你带着原卡走出宴会厅，顾策划把备份盘塞进你手里：「剪辑版我也备了。」宋景明想伸手删文件，连鼠标在哪都没找到。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 18}}, "posterTag": "隐藏彩蛋", "hint": "点击画面闪烁证物收取 >= 4 份且反派怒气 <= 18 方可凑齐重磅黑料"}, {"id": "reborn.end2", "type": "subversive", "priority": 90, "title": "订婚宴改涮火锅", "text": "你一次次把剧本掰成了日常，订婚宴最后开成了街坊火锅局。宋景明准备了三套台词，一套都没轮到。你（擦擦嘴）：「这一世，我只想把锅底涮完。」", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未达成隐藏路线即可解锁"}, {"id": "reborn.end3", "type": "unfinished", "priority": 80, "title": "复仇宣言没存档", "text": "该留的没留够，该喊的喊遍了全场。大屏幕跳出一行字：补交材料中。老马清清嗓子：「下一部，《重生之补交材料》，敬请期待。」", "condition": {"minStats": {"anger": 42}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气 >= 42 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "reborn.end4", "type": "triumph", "priority": 70, "title": "这场订婚宴不续约", "text": "你把每一步都走了一遍，该读的读了，该拒的拒了。宋景明收起笔，保证书原封退了回去。后来他们都后悔了，后悔彩排那天，没把那段录像删干净。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健推进主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_05_reborn';

-- 更新剧本《我把主角团带偏了》(script_06_transmig) 分集选项顺序/证物配置与结局提示
UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "transmig.ep1", "title": "第 1 集：醒来就在泼酒前", "sceneDesc": "你睁开眼，手里端着一杯红酒，面前是哭到一半的女主。脑内响起机械音：「检测到宿主已就位，原著第三十七章，泼酒环节，三、二——」你想起来了，昨晚吐槽到凌晨的那本小说。\\\\n原著旁白（自动播放）：「苏明艳眼神淬毒，红唇一勾。」其实你只是没睡醒，手在抖。白小芷抱着蛋糕盒，眼眶说红就红：「姐姐，是我不好，我不该出现在这里。」\\\\n秦屿白从人群里大步走来（抬了抬下巴）：「苏明艳，你又想对小芷做什么？」全场手机齐刷刷举起来。管家老周在角落小声提醒：「小姐，按剧情，您现在该泼酒了。」\\\\n这本书里，你的下一章叫「领盒饭」，戏份到明晚结束。老周压低声音补了一句：「小姐，这杯酒怎么处理，后面几章就顺着怎么写。」酒杯晃出一圈涟漪，泼，是剧情；不泼，就是剧情外。你拿主意。", "sceneImage": "/static/art/covers/cover-transmig.jpg", "panels": [{"speaker": "旁白", "text": "你睁开眼，手里端着一杯红酒，面前是哭到一半的女主。脑内响起机械音：「检测到宿主已就位，原著第三十七章，泼酒环节，三、二——」你想起来了，昨晚吐槽到凌晨的那本小说。"}, {"speaker": "旁白", "text": "原著旁白（自动播放）：「苏明艳眼神淬毒，红唇一勾。」其实你只是没睡醒，手在抖。白小芷抱着蛋糕盒，眼眶说红就红：「姐姐，是我不好，我不该出现在这里。」"}, {"speaker": "旁白", "text": "秦屿白从人群里大步走来（抬了抬下巴）：「苏明艳，你又想对小芷做什么？」全场手机齐刷刷举起来。管家老周在角落小声提醒：「小姐，按剧情，您现在该泼酒了。」"}, {"speaker": "旁白", "text": "这本书里，你的下一章叫「领盒饭」，戏份到明晚结束。老周压低声音补了一句：「小姐，这杯酒怎么处理，后面几章就顺着怎么写。」酒杯晃出一圈涟漪，泼，是剧情；不泼，就是剧情外。你拿主意。"}], "choices": [{"choiceId": "transmig_e1_c1", "id": "A", "label": "A", "text": "闻一闻杯子，问是谁倒的酒", "styleTag": "经典套路", "feedback": "你低头闻了闻，是橙汁。老周压低声音：「按原著该是红酒，大概作者嫌红酒贵，改成了橙汁。」你（把杯子举高）：「这杯是橙汁，泼了也是补充维C。」白小芷愣住：「那……我不用躲了？」秦屿白的台词，卡在了半路。老周在小本上记了一笔：「本章走查案线。」", "outcome": "你低头闻了闻，是橙汁。老周压低声音：「按原著该是红酒，大概作者嫌红酒贵，改成了橙汁。」你（把杯子举高）：「这杯是橙汁，泼了也是补充维C。」白小芷愣住：「那……我不用躲了？」秦屿白的台词，卡在了半路。老周在小本上记了一笔：「本章走查案线。」", "qualityBonus": 12, "effects": {"pleasure": 5, "drama": 8, "anger": 2, "evidence": 1, "subversion": 0}}, {"choiceId": "transmig_e1_c3", "id": "B", "label": "B", "text": "放下酒杯，请白小芷分蛋糕", "styleTag": "打工人觉醒", "feedback": "你把酒杯往托盘上一放，伸手接过蛋糕盒：「蛋糕分我一半，我早饭没吃。」白小芷眨巴着眼：「啊？可你不是该泼我吗？」你：「想泼，但饿。」老周在后面悄悄记了一笔：「本章走请假线。」", "outcome": "你把酒杯往托盘上一放，伸手接过蛋糕盒：「蛋糕分我一半，我早饭没吃。」白小芷眨巴着眼：「啊？可你不是该泼我吗？」你：「想泼，但饿。」老周在后面悄悄记了一笔：「本章走请假线。」", "qualityBonus": 15, "effects": {"pleasure": 8, "drama": 7, "anger": -2, "evidence": 0, "subversion": 1}}, {"choiceId": "transmig_e1_c2", "id": "C", "label": "C", "text": "冷笑一声，把酒泼向男主", "styleTag": "离谱反套路", "feedback": "你冷笑一声，手腕一扬，整杯泼了出去——是红酒还是橙汁，没人看清。秦屿白（抹了把脸，一字一顿）：「很好，苏明艳，你这章的戏份，够了。」白小芷捂着嘴，眼里全是泪光，也不知道是演的还是真的。老周在本子上记下：「本章走原著线。」", "outcome": "你冷笑一声，手腕一扬，整杯泼了出去——是红酒还是橙汁，没人看清。秦屿白（抹了把脸，一字一顿）：「很好，苏明艳，你这章的戏份，够了。」白小芷捂着嘴，眼里全是泪光，也不知道是演的还是真的。老周在本子上记下：「本章走原著线。」", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 14, "anger": 20, "evidence": 0, "subversion": 0}}]}, {"ep": 2, "number": 2, "id": "transmig.ep2", "title": "第 2 集：满墙的台词便签", "sceneDesc": "回到苏明艳的卧室，满墙都是便利贴：「第三十八章台词：你以为你赢了？」「冷笑三声，记得抬下巴。」你一张张看过去，终于明白她为什么那么忙，原来恶毒也要背台词。\\\\n老周抱着一只纸箱敲门：「小姐，这是您下一章的行李。」你：「下一章我去哪？」老周：「原著没写，只说您拎不动。」箱子最上面，压着一本边角卷起的硬壳本子。\\\\n门又响了，白小芷抱着一件外套站在门口，吓得一哆嗦：「姐姐，我是来道歉的，虽然我也不知道错在哪。」她一边说，一边往箱子里瞄，像在找什么。\\\\n箱子、本子、老周、白小芷，都等着你开口。下一章在明晚，你手边能动的，只有这三件事。", "sceneImage": "/static/art/covers/cover-transmig.jpg", "panels": [{"speaker": "旁白", "text": "回到苏明艳的卧室，满墙都是便利贴：「第三十八章台词：你以为你赢了？」「冷笑三声，记得抬下巴。」你一张张看过去，终于明白她为什么那么忙，原来恶毒也要背台词。"}, {"speaker": "旁白", "text": "老周抱着一只纸箱敲门：「小姐，这是您下一章的行李。」你：「下一章我去哪？」老周：「原著没写，只说您拎不动。」箱子最上面，压着一本边角卷起的硬壳本子。"}, {"speaker": "旁白", "text": "门又响了，白小芷抱着一件外套站在门口，吓得一哆嗦：「姐姐，我是来道歉的，虽然我也不知道错在哪。」她一边说，一边往箱子里瞄，像在找什么。"}, {"speaker": "旁白", "text": "箱子、本子、老周、白小芷，都等着你开口。下一章在明晚，你手边能动的，只有这三件事。"}], "choices": [{"choiceId": "transmig_e2_c2", "id": "A", "label": "A", "text": "把箱子踢到墙角，宣布不演了", "styleTag": "离谱反套路", "feedback": "你（一脚把箱子踢到墙角）：「本小姐不演了！」箱子撞上墙，哗啦啦滚出一堆便利贴。白小芷捂住嘴：「姐姐，你的台词散了。」老周蹲下去一张张捡：「小姐，这是第三十八章的，别踢。」你踢掉的是自己下一章的台本。", "outcome": "你（一脚把箱子踢到墙角）：「本小姐不演了！」箱子撞上墙，哗啦啦滚出一堆便利贴。白小芷捂住嘴：「姐姐，你的台词散了。」老周蹲下去一张张捡：「小姐，这是第三十八章的，别踢。」你踢掉的是自己下一章的台本。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 13, "anger": 12, "evidence": 0, "subversion": 0}}, {"choiceId": "transmig_e2_c3", "id": "B", "label": "B", "text": "翻开箱子里那本硬壳本子", "styleTag": "打工人觉醒", "feedback": "你翻开那本硬壳本子，是苏明艳的《角色设定卡》：恶毒值，一百；台词，十二句；动机栏，一片空白，旁边用铅笔写着两个小字：待补。你（愣了愣）：「我为什么这么恶毒？」老周挠头：「原著没写，大概作者忘了。」", "outcome": "你翻开那本硬壳本子，是苏明艳的《角色设定卡》：恶毒值，一百；台词，十二句；动机栏，一片空白，旁边用铅笔写着两个小字：待补。你（愣了愣）：「我为什么这么恶毒？」老周挠头：「原著没写，大概作者忘了。」", "qualityBonus": 15, "effects": {"pleasure": 5, "drama": 9, "anger": -3, "evidence": 1, "subversion": 1}}, {"choiceId": "transmig_e2_c1", "id": "C", "label": "C", "text": "请老周把行李逐件登记", "styleTag": "经典套路", "feedback": "你让老周拿来笔，一件件念：「冬季外套两件，限量包七个，台词便利贴一百二十张。」登记到最后，老周抬头：「小姐，这些都是原著里您带不走的东西。」你：「那我就带得走。」白小芷小声：「我帮你数。」", "outcome": "你让老周拿来笔，一件件念：「冬季外套两件，限量包七个，台词便利贴一百二十张。」登记到最后，老周抬头：「小姐，这些都是原著里您带不走的东西。」你：「那我就带得走。」白小芷小声：「我帮你数。」", "qualityBonus": 12, "effects": {"pleasure": 6, "drama": 8, "anger": 3, "evidence": 0, "subversion": 0}}]}, {"ep": 3, "number": 3, "id": "transmig.ep3", "title": "第 3 集：男主多了三句台词", "sceneDesc": "第二天清晨，苏家餐厅。秦屿白（把一张烫金请柬拍在桌上，冷着脸）：「今晚的晚宴，你必须到场。」你低头看请柬，边角烫着一行小字：第三十八章。\\\\n老周端着早餐，激动得声音拔高：「少爷！您说了三句话！我记得原著里，您这时候只有一句！」秦屿白皱眉：「……我哪来的三句？」你（咬了口吐司）：「大概是您被加戏了。」\\\\n白小芷捧着粥碗，怯生生：「屿白哥哥，姐姐她好像……不一样了。」秦屿白眼神一沉：「她越反常，越要提防，我的直觉从来不出错。」你嘴里的吐司停了三秒。\\\\n请柬、早餐、被加戏的男主，都摆在眼前。今晚就是你领盒饭的场次，餐桌上能做的小动作，只有这三个。", "sceneImage": "/static/art/covers/cover-transmig.jpg", "panels": [{"speaker": "旁白", "text": "第二天清晨，苏家餐厅。秦屿白（把一张烫金请柬拍在桌上，冷着脸）：「今晚的晚宴，你必须到场。」你低头看请柬，边角烫着一行小字：第三十八章。"}, {"speaker": "旁白", "text": "老周端着早餐，激动得声音拔高：「少爷！您说了三句话！我记得原著里，您这时候只有一句！」秦屿白皱眉：「……我哪来的三句？」你（咬了口吐司）：「大概是您被加戏了。」"}, {"speaker": "旁白", "text": "白小芷捧着粥碗，怯生生：「屿白哥哥，姐姐她好像……不一样了。」秦屿白眼神一沉：「她越反常，越要提防，我的直觉从来不出错。」你嘴里的吐司停了三秒。"}, {"speaker": "旁白", "text": "请柬、早餐、被加戏的男主，都摆在眼前。今晚就是你领盒饭的场次，餐桌上能做的小动作，只有这三个。"}], "choices": [{"choiceId": "transmig_e3_c1", "id": "A", "label": "A", "text": "把请柬翻过来核对流程", "styleTag": "经典套路", "feedback": "秦屿白看着你把请柬翻到背面，上面印着座位号和流程表，第三项写着：宣读断绝书。你拿笔圈出来，把请柬推到他面前：「这一项，需要我签收吗？」他看着自己亲手批准的流程，愣了半天，第一次没接上话。", "outcome": "秦屿白看着你把请柬翻到背面，上面印着座位号和流程表，第三项写着：宣读断绝书。你拿笔圈出来，把请柬推到他面前：「这一项，需要我签收吗？」他看着自己亲手批准的流程，愣了半天，第一次没接上话。", "qualityBonus": 12, "effects": {"pleasure": 7, "drama": 8, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "transmig_e3_c2", "id": "B", "label": "B", "text": "拍案而起：谁怕谁", "styleTag": "离谱反套路", "feedback": "你（抬了抬下巴）：「谁怕谁！今晚我就让你们见识什么叫恶毒女配的终极表演！」秦屿白点头：「很好，就要这个气势。」白小芷泪光闪闪：「姐姐，你好像真的很期待。」老周在小本上记下：宿主选择，加戏。", "outcome": "你（抬了抬下巴）：「谁怕谁！今晚我就让你们见识什么叫恶毒女配的终极表演！」秦屿白点头：「很好，就要这个气势。」白小芷泪光闪闪：「姐姐，你好像真的很期待。」老周在小本上记下：宿主选择，加戏。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 15, "anger": 12, "evidence": 0, "subversion": 0}}, {"choiceId": "transmig_e3_c3", "id": "C", "label": "C", "text": "和老周把早餐吃完", "styleTag": "打工人觉醒", "feedback": "你和老周分了最后一块吐司，聊起他在原著里只有一句台词的事。老周红着眼眶：「小姐，您是第一个愿意听我说话的人。」秦屿白拿着请柬站在旁边，没人搭理。他默默坐下，喝了口粥。", "outcome": "你和老周分了最后一块吐司，聊起他在原著里只有一句台词的事。老周红着眼眶：「小姐，您是第一个愿意听我说话的人。」秦屿白拿着请柬站在旁边，没人搭理。他默默坐下，喝了口粥。", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -3, "evidence": 0, "subversion": 1}}]}, {"ep": 4, "number": 4, "id": "transmig.ep4", "title": "第 4 集：女主对上了暗号", "sceneDesc": "后花园的喷泉后面，白小芷把你拉到身边，压低声音：「奇变偶不变？」她眼眶里的泪，这会儿一滴没有。你愣了两秒，脑子里自己接了一句。\\\\n你：「符号看象限。」白小芷眼睛一亮，眼泪这才哗地涌出来：「终于遇见同行了！」她抓着你的袖子：「我设定每天哭十二次，今天已经哭九次了，再哭下去眼药水要涨价。」\\\\n白小芷（掰着手指数，得意地）：「按原著，晚宴上我要原谅你，秦屿白要护着我，然后你被架出去，我再红三次眼眶。」远处传来老周的声音：「小姐，您在哪儿？剧情要开始了！」\\\\n喷泉的水声刚好盖住你们的对话。女主和女配凑到一起，剧本还能不能照着演，你得拿个主意：愿意陪她把眼泪哭完，这一章就多一个同盟。", "sceneImage": "/static/art/covers/cover-transmig.jpg", "panels": [{"speaker": "旁白", "text": "后花园的喷泉后面，白小芷把你拉到身边，压低声音：「奇变偶不变？」她眼眶里的泪，这会儿一滴没有。你愣了两秒，脑子里自己接了一句。"}, {"speaker": "旁白", "text": "你：「符号看象限。」白小芷眼睛一亮，眼泪这才哗地涌出来：「终于遇见同行了！」她抓着你的袖子：「我设定每天哭十二次，今天已经哭九次了，再哭下去眼药水要涨价。」"}, {"speaker": "旁白", "text": "白小芷（掰着手指数，得意地）：「按原著，晚宴上我要原谅你，秦屿白要护着我，然后你被架出去，我再红三次眼眶。」远处传来老周的声音：「小姐，您在哪儿？剧情要开始了！」"}, {"speaker": "旁白", "text": "喷泉的水声刚好盖住你们的对话。女主和女配凑到一起，剧本还能不能照着演，你得拿个主意：愿意陪她把眼泪哭完，这一章就多一个同盟。"}], "choices": [{"choiceId": "transmig_e4_c3", "id": "A", "label": "A", "text": "陪她把十二次哭一次哭完", "styleTag": "打工人觉醒", "feedback": "你说那就今天一次哭完，剩下的时间都归自己。白小芷抱着你，哭得像一场暴雨，连喷泉都显得安静。白小芷哭完，拍拍裙子：「舒服了！今天剩下的次数，我不要了。」老周在远处感慨：「原著里没这一段，但我想收藏。」白小芷把一张写着暗号的餐巾纸塞进你手心：「同盟成立。」", "outcome": "你说那就今天一次哭完，剩下的时间都归自己。白小芷抱着你，哭得像一场暴雨，连喷泉都显得安静。白小芷哭完，拍拍裙子：「舒服了！今天剩下的次数，我不要了。」老周在远处感慨：「原著里没这一段，但我想收藏。」白小芷把一张写着暗号的餐巾纸塞进你手心：「同盟成立。」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 8, "anger": -4, "evidence": 0, "subversion": 0}}, {"choiceId": "transmig_e4_c1", "id": "B", "label": "B", "text": "对照原著，把要做的事列成清单", "styleTag": "经典套路", "feedback": "你们蹲在喷泉后面，用树枝在地上列清单：泼酒、断绝书、原谅、护妻、被架出。白小芷边画边念：「第三项，我不想原谅，我想吃宵夜。」你（指着清单）：「那就划掉。」两个人对着一地树枝，像在开一场很正经的剧本会。", "outcome": "你们蹲在喷泉后面，用树枝在地上列清单：泼酒、断绝书、原谅、护妻、被架出。白小芷边画边念：「第三项，我不想原谅，我想吃宵夜。」你（指着清单）：「那就划掉。」两个人对着一地树枝，像在开一场很正经的剧本会。", "qualityBonus": 12, "effects": {"pleasure": 6, "drama": 10, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "transmig_e4_c2", "id": "C", "label": "C", "text": "拉她一起冲上去撕男主剧本", "styleTag": "离谱反套路", "feedback": "你（拉住她的手）：「走，今晚咱们把男主的剧本撕了！」白小芷的眼泪立刻开闸：「好！但这回哭是真的。」两个人冲出喷泉区，老周在后面追：「小姐！您跑得太快了，原著里您不会跑！」你们的出场，吓到了整个花园的保安。", "outcome": "你（拉住她的手）：「走，今晚咱们把男主的剧本撕了！」白小芷的眼泪立刻开闸：「好！但这回哭是真的。」两个人冲出喷泉区，老周在后面追：「小姐！您跑得太快了，原著里您不会跑！」你们的出场，吓到了整个花园的保安。", "qualityBonus": 18, "effects": {"pleasure": 4, "drama": 15, "anger": 10, "evidence": 0, "subversion": 0}}]}, {"ep": 5, "number": 5, "id": "transmig.ep5", "title": "第 5 集：设定卡复印三份", "sceneDesc": "晚宴后台，离开场还剩十分钟。两名保安站在化妆间门口，其中一位翻着流程表：「苏小姐，按规定，退场人员需要上交随身物品，包括那本硬壳本子。」\\\\n老周（抱着一叠空白纸，急得直跺脚）：「小姐，这卡片只有一份，交上去就没了！复印机在隔壁，就是总卡纸。」白小芷从门缝里挤进来，攥着自己的手机：「我可以拍照做证。」\\\\n秦屿白在门外催：「还有五分钟，苏明艳，别磨蹭。」他的助理敲着门板，节奏和倒计时一模一样。你手里的设定卡，被汗浸得有点软。\\\\n复印机、手机、老周的手抄纸，哪一样能让这张卡留得下来，只剩你现在的决定。", "sceneImage": "/static/art/covers/cover-transmig.jpg", "panels": [{"speaker": "旁白", "text": "晚宴后台，离开场还剩十分钟。两名保安站在化妆间门口，其中一位翻着流程表：「苏小姐，按规定，退场人员需要上交随身物品，包括那本硬壳本子。」"}, {"speaker": "旁白", "text": "老周（抱着一叠空白纸，急得直跺脚）：「小姐，这卡片只有一份，交上去就没了！复印机在隔壁，就是总卡纸。」白小芷从门缝里挤进来，攥着自己的手机：「我可以拍照做证。」"}, {"speaker": "旁白", "text": "秦屿白在门外催：「还有五分钟，苏明艳，别磨蹭。」他的助理敲着门板，节奏和倒计时一模一样。你手里的设定卡，被汗浸得有点软。"}, {"speaker": "旁白", "text": "复印机、手机、老周的手抄纸，哪一样能让这张卡留得下来，只剩你现在的决定。"}], "choices": [{"choiceId": "transmig_e5_c2", "id": "A", "label": "A", "text": "换上最华丽的礼服亮相", "styleTag": "离谱反套路", "feedback": "你换上最华丽的礼服，在镜子前转了一圈：「今晚，我要做全场最恶毒的人。」老周举着手机：「小姐，这光，原著里写过。」白小芷帮你扶了扶皇冠。你亮得很，设定卡躺在化妆台上，没人记得它。", "outcome": "你换上最华丽的礼服，在镜子前转了一圈：「今晚，我要做全场最恶毒的人。」老周举着手机：「小姐，这光，原著里写过。」白小芷帮你扶了扶皇冠。你亮得很，设定卡躺在化妆台上，没人记得它。", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 15, "anger": 12, "evidence": 0, "subversion": 0}}, {"choiceId": "transmig_e5_c1", "id": "B", "label": "B", "text": "复印三份，请女主和老周签名见证", "styleTag": "经典套路", "feedback": "你把设定卡塞进复印机，老周在旁边又吹又拍，居然一次过。三份复印件上，白小芷和老周各签了名，你自己也签了一份。保安翻流程表的手慢了下来：「这个……不在规定的物品里。」", "outcome": "你把设定卡塞进复印机，老周在旁边又吹又拍，居然一次过。三份复印件上，白小芷和老周各签了名，你自己也签了一份。保安翻流程表的手慢了下来：「这个……不在规定的物品里。」", "qualityBonus": 12, "effects": {"pleasure": 7, "drama": 8, "anger": 3, "evidence": 1, "subversion": 0}}, {"choiceId": "transmig_e5_c3", "id": "C", "label": "C", "text": "把设定卡折成纸飞机放飞", "styleTag": "打工人觉醒", "feedback": "你（把设定卡折成纸飞机）：「这是我的情绪出口。」纸飞机飞过化妆间，落进了假花盆里。老周赶紧捡起来拍灰：「小姐，这是孤本啊！」白小芷在旁边鼓掌：「姐姐，好潇洒。」", "outcome": "你（把设定卡折成纸飞机）：「这是我的情绪出口。」纸飞机飞过化妆间，落进了假花盆里。老周赶紧捡起来拍灰：「小姐，这是孤本啊！」白小芷在旁边鼓掌：「姐姐，好潇洒。」", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 8, "anger": -3, "evidence": 0, "subversion": 1}}]}, {"ep": 6, "number": 6, "id": "transmig.ep6", "title": "第 6 集：盒饭要自己订", "sceneDesc": "晚宴厅灯光暗下，秦屿白走上台，握着话筒一字一顿：「在座各位，今晚我要宣布一件事。」台下三百人齐刷刷举起手机，白小芷攥紧了裙角。大屏幕角落有行小字：本章字数充足。\\\\n司仪翻开断绝书，两名保安已经在你身后站成两列。老周举着托盘躲在柱子后面，小声提醒：「小姐，按原著，您现在该哭着说“你们会后悔的”。」\\\\n你抬头看了看天花板的水晶灯。原著里，它会在你被架出去时恰好闪一下。这会儿它纹丝不动，大概是作者没写好灯光。\\\\n台下三百人，台上一份断绝书，保安的手已经搭上你的肩。第三十八章怎么写，最后一句，你来说。", "sceneImage": "/static/art/covers/cover-transmig.jpg", "panels": [{"speaker": "旁白", "text": "晚宴厅灯光暗下，秦屿白走上台，握着话筒一字一顿：「在座各位，今晚我要宣布一件事。」台下三百人齐刷刷举起手机，白小芷攥紧了裙角。大屏幕角落有行小字：本章字数充足。"}, {"speaker": "旁白", "text": "司仪翻开断绝书，两名保安已经在你身后站成两列。老周举着托盘躲在柱子后面，小声提醒：「小姐，按原著，您现在该哭着说“你们会后悔的”。」"}, {"speaker": "旁白", "text": "你抬头看了看天花板的水晶灯。原著里，它会在你被架出去时恰好闪一下。这会儿它纹丝不动，大概是作者没写好灯光。"}, {"speaker": "旁白", "text": "台下三百人，台上一份断绝书，保安的手已经搭上你的肩。第三十八章怎么写，最后一句，你来说。"}], "choices": [{"choiceId": "transmig_e6_c3", "id": "A", "label": "A", "text": "宣布本章改成茶话会", "styleTag": "打工人觉醒", "feedback": "你（对着话筒）：「各位，这一章改成茶话会，蛋糕免费，断绝书自取。」白小芷第一个鼓掌，老周推出点心车。宾客们端着茶，边吃边传阅断绝书，有人举手问：「请问，这一章是不是写完了？」", "outcome": "你（对着话筒）：「各位，这一章改成茶话会，蛋糕免费，断绝书自取。」白小芷第一个鼓掌，老周推出点心车。宾客们端着茶，边吃边传阅断绝书，有人举手问：「请问，这一章是不是写完了？」", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 8, "anger": -3, "evidence": 0, "subversion": 1}}, {"choiceId": "transmig_e6_c2", "id": "B", "label": "B", "text": "泼出红酒：这一章我自己写", "styleTag": "离谱反套路", "feedback": "你抄起酒杯，一扬手泼向半空，酒花在灯光下炸开，像反派专属烟花。全场安静了两秒，秦屿白（擦着脸）：「很好，非常恶毒。」保安一左一右把你架了出去，老周追在后面喊：「小姐，台词我替您背下来了！」", "outcome": "你抄起酒杯，一扬手泼向半空，酒花在灯光下炸开，像反派专属烟花。全场安静了两秒，秦屿白（擦着脸）：「很好，非常恶毒。」保安一左一右把你架了出去，老周追在后面喊：「小姐，台词我替您背下来了！」", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 18, "anger": 14, "evidence": 0, "subversion": 0}}, {"choiceId": "transmig_e6_c1", "id": "C", "label": "C", "text": "出示签名复印件，请全场看动机栏", "styleTag": "经典套路", "feedback": "你把三份复印件传到台下，亲戚、宾客一页页翻过去，最后得出统一结论：没写动机，没法执行。司仪合上断绝书，小声问本环节是不是取消。秦屿白握着话筒，没找到顺手的词，想不出下一句的格式。", "outcome": "你把三份复印件传到台下，亲戚、宾客一页页翻过去，最后得出统一结论：没写动机，没法执行。司仪合上断绝书，小声问本环节是不是取消。秦屿白握着话筒，没找到顺手的词，想不出下一句的格式。", "qualityBonus": 12, "effects": {"pleasure": 8, "drama": 9, "anger": 3, "evidence": 1, "subversion": 0}}]}]', endings_json = '[{"id": "transmig.end1", "type": "hidden", "priority": 100, "title": "第三十八章待修订", "text": "设定卡上的空白栏，连同你和白小芷的满页批注，一起摆在台上。全场翻到同一页：恶毒女配，动机待补。大屏幕跳出一行字：本章作者已阅，标记为待修订。白小芷和你分了蛋糕，老周的台词，第一次超过了一页。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 16}}, "posterTag": "隐藏彩蛋", "hint": "点击画面闪烁证物收取 >= 4 份且反派怒气 <= 16 方可幕后联合破局"}, {"id": "transmig.end2", "type": "subversive", "priority": 80, "title": "恶毒女配请了病假", "text": "你一次次把恶毒请了假，晚宴最后成了读书会。原著里的盒饭，被白小芷认领当了晚饭。老周举着小本子记了一页又一页：「这本书，我想订阅。」", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3（且怒气 < 54）即可解锁"}, {"id": "transmig.end3", "type": "unfinished", "priority": 90, "title": "断更前的最后一泼", "text": "酒泼出去了，设定卡却没人见过。保安架着你出场时，大屏幕跳出提示：本章到此结束，作者即将断更。老周追出来问：「小姐，下一部叫什么？」你：「《穿成路人甲，重新来过》。」", "condition": {"minStats": {"anger": 54}}, "posterTag": "喜剧烂尾", "hint": "反派/系统怒气 >= 54 时触发全员歪楼烂尾"}, {"id": "transmig.end4", "type": "triumph", "priority": 10, "title": "第三十九章没有盒饭", "text": "该看的你看了，该拒的你拒了。断绝书被改成了合作意向书，保安空着手站在门口，盒饭发给了全体工作人员，女配那份还多加了一个鸡腿。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "常规稳妥推进至大结局自动解锁保底爽剧收官"}]', version = version + 1 WHERE script_id = 'script_06_transmig';

-- 更新剧本《一声令下十万将士》(script_07_veteran) 分集选项顺序/证物配置与结局提示
UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "veteran.ep1", "title": "第 1 集：行军包进了面包店", "sceneDesc": "退伍第一天，你背着行军包推开「知夏烘焙」的门，门铃「叮」地响了一声。店里没有黄油香，只有一张折叠桌，桌上摊着《离婚协议》，笔帽已经拔开了。\\\\n钱满仓（整了整袖口，歪嘴一笑）：「林老板，三年没音讯的男人，值得等吗？签了字，铺面我来接手，你也轻松。」林知夏攥着笔，手在抖：「我再想想……」\\\\n刘阿姨端着一盘面包，使劲点头：「钱总是好人，知夏啊，别犟！」她一回头，看见你肩上的行军包，托盘「当啷」一声掉在地上，面包滚了一地。\\\\n行军包还在你肩上，协议摆在桌中间，笔尖离签名栏只剩一指宽。你开口之前，满屋子的人都在看你。", "sceneImage": "/static/art/covers/cover-veteran.jpg", "panels": [{"speaker": "旁白", "text": "退伍第一天，你背着行军包推开「知夏烘焙」的门，门铃「叮」地响了一声。店里没有黄油香，只有一张折叠桌，桌上摊着《离婚协议》，笔帽已经拔开了。"}, {"speaker": "旁白", "text": "钱满仓（整了整袖口，歪嘴一笑）：「林老板，三年没音讯的男人，值得等吗？签了字，铺面我来接手，你也轻松。」林知夏攥着笔，手在抖：「我再想想……」"}, {"speaker": "旁白", "text": "刘阿姨端着一盘面包，使劲点头：「钱总是好人，知夏啊，别犟！」她一回头，看见你肩上的行军包，托盘「当啷」一声掉在地上，面包滚了一地。"}, {"speaker": "旁白", "text": "行军包还在你肩上，协议摆在桌中间，笔尖离签名栏只剩一指宽。你开口之前，满屋子的人都在看你。"}], "choices": [{"choiceId": "veteran_e1_c2", "id": "A", "label": "A", "text": "把行军包往桌上一放：我回来了", "styleTag": "离谱反套路", "feedback": "你（把行军包往桌上重重一放，声音大得自己都愣了一下）：「我回来了！」满店的人往后退了半步，桌上的协议被震得跳了一下。钱满仓皱眉：「谁让他进来的？」知夏眼眶红了：「你这三年……」你张了张嘴，台词全卡在了喉咙里。", "outcome": "你（把行军包往桌上重重一放，声音大得自己都愣了一下）：「我回来了！」满店的人往后退了半步，桌上的协议被震得跳了一下。钱满仓皱眉：「谁让他进来的？」知夏眼眶红了：「你这三年……」你张了张嘴，台词全卡在了喉咙里。", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 8, "anger": 4, "evidence": 0, "subversion": 0}}, {"choiceId": "veteran_e1_c3", "id": "B", "label": "B", "text": "问今天的面包还有没有剩", "styleTag": "打工人觉醒", "feedback": "你（放下行军包，声音有点哽咽）：「还有没卖完的吗？我三年没吃过正经的奶油卷。」知夏愣了几秒，忽然笑出声，眼泪却掉了下来。钱满仓：「喂，我们在谈正事。」你：「那我边吃边听。」", "outcome": "你（放下行军包，声音有点哽咽）：「还有没卖完的吗？我三年没吃过正经的奶油卷。」知夏愣了几秒，忽然笑出声，眼泪却掉了下来。钱满仓：「喂，我们在谈正事。」你：「那我边吃边听。」", "qualityBonus": 15, "effects": {"pleasure": 3, "drama": 4, "anger": -1, "evidence": 0, "subversion": 1}}, {"choiceId": "veteran_e1_c1", "id": "C", "label": "C", "text": "走过去，把协议翻到最后一页", "styleTag": "经典套路", "feedback": "你走过去，把协议翻到最后一页，念出最小的一行字：「本协议签署后，铺面经营权一并转让。」知夏愣住：「这条我没看到。」钱满仓：「小字嘛，大家都不爱读。」刘阿姨低头看自己的空托盘，像在找地缝。", "outcome": "你走过去，把协议翻到最后一页，念出最小的一行字：「本协议签署后，铺面经营权一并转让。」知夏愣住：「这条我没看到。」钱满仓：「小字嘛，大家都不爱读。」刘阿姨低头看自己的空托盘，像在找地缝。", "qualityBonus": 12, "effects": {"pleasure": 3, "drama": 5, "anger": 1, "evidence": 1, "subversion": 0}}]}, {"ep": 2, "number": 2, "id": "veteran.ep2", "title": "第 2 集：烤箱底下的铁盒", "sceneDesc": "后厨飘着刚出炉的黄油味。知夏背对着你擦手：「你回来，怎么不提前说一声？」你：「怕你拒绝，我在门口站了十分钟。」她没回头，肩膀抖了一下。\\\\n前厅传来钱满仓的声音：「林老板，三分钟到了，签不签？」刘阿姨探头进来：「知夏啊，钱总等着呢！」知夏手里的毛巾，被她拧成了一根麻花。\\\\n你的目光落在烤箱下面，那里压着一只旧铁盒，露出半截军绿色的信封，写着你的名字。知夏顺着你的视线看过去，慌忙用脚把铁盒往里踢了踢：「那是……烘焙模具。」\\\\n前厅在催，铁盒在脚边，知夏的耳朵红到了耳尖。你只有这点时间，是问，是凶，还是蹲下去。", "sceneImage": "/static/art/covers/cover-veteran.jpg", "panels": [{"speaker": "旁白", "text": "后厨飘着刚出炉的黄油味。知夏背对着你擦手：「你回来，怎么不提前说一声？」你：「怕你拒绝，我在门口站了十分钟。」她没回头，肩膀抖了一下。"}, {"speaker": "旁白", "text": "前厅传来钱满仓的声音：「林老板，三分钟到了，签不签？」刘阿姨探头进来：「知夏啊，钱总等着呢！」知夏手里的毛巾，被她拧成了一根麻花。"}, {"speaker": "旁白", "text": "你的目光落在烤箱下面，那里压着一只旧铁盒，露出半截军绿色的信封，写着你的名字。知夏顺着你的视线看过去，慌忙用脚把铁盒往里踢了踢：「那是……烘焙模具。」"}, {"speaker": "旁白", "text": "前厅在催，铁盒在脚边，知夏的耳朵红到了耳尖。你只有这点时间，是问，是凶，还是蹲下去。"}], "choices": [{"choiceId": "veteran_e2_c1", "id": "A", "label": "A", "text": "问知夏这三年到底发生了什么", "styleTag": "经典套路", "feedback": "你（把知夏拉到面粉袋旁坐下）：「这三年，你一个人是怎么过的？」知夏一条条说：钱满仓每周来一次，带着花来，带着合同来，最后带着刘阿姨的关心来。你把每一条都记在手心里，记到最后一条，手心已经写满了。", "outcome": "你（把知夏拉到面粉袋旁坐下）：「这三年，你一个人是怎么过的？」知夏一条条说：钱满仓每周来一次，带着花来，带着合同来，最后带着刘阿姨的关心来。你把每一条都记在手心里，记到最后一条，手心已经写满了。", "qualityBonus": 12, "effects": {"pleasure": 3, "drama": 5, "anger": 1, "evidence": 1, "subversion": 0}}, {"choiceId": "veteran_e2_c2", "id": "B", "label": "B", "text": "拍着案板，让钱总滚出去", "styleTag": "离谱反套路", "feedback": "你推开后厨门，一掌拍在案板上：「谁让你们坐在我老婆的店里？滚出去！」案板上的面团被震得抖了三抖。钱满仓慢条斯理地站起来：「这位先生，请问你是……？」你说不出话，因为退伍证还在行军包底下。", "outcome": "你推开后厨门，一掌拍在案板上：「谁让你们坐在我老婆的店里？滚出去！」案板上的面团被震得抖了三抖。钱满仓慢条斯理地站起来：「这位先生，请问你是……？」你说不出话，因为退伍证还在行军包底下。", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 8, "anger": 4, "evidence": 0, "subversion": 0}}, {"choiceId": "veteran_e2_c3", "id": "C", "label": "C", "text": "蹲下，抽出烤箱底下的铁盒", "styleTag": "打工人觉醒", "feedback": "你蹲下去，把铁盒抽了出来。盒盖一开，是满满一沓便签，每张都写着日期：「今天烤糊了十二个面包，想你。」「钱总又来了，我装没听见。」最后一张压在最底下：「他们让我签，我不想签。」知夏捂住脸，哽咽起来。", "outcome": "你蹲下去，把铁盒抽了出来。盒盖一开，是满满一沓便签，每张都写着日期：「今天烤糊了十二个面包，想你。」「钱总又来了，我装没听见。」最后一张压在最底下：「他们让我签，我不想签。」知夏捂住脸，哽咽起来。", "qualityBonus": 15, "effects": {"pleasure": 3, "drama": 4, "anger": -1, "evidence": 0, "subversion": 1}}]}, {"ep": 3, "number": 3, "id": "veteran.ep3", "title": "第 3 集：骑手们喊老班长", "sceneDesc": "巷口突然响起一排电动车的喇叭声。一群骑手齐刷刷刹在店门口，黄的蓝的头盔，同声大喊：「恭迎老班长归来！」钱满仓的黑色加长车被堵在巷口，司机摇下车窗：「麻烦让一让。」\\\\n老胡摘下头盔，眼眶一红，敬了个标准的礼：「老班长，群里说你回来了，我们送完这单就赶过来了！」他身后的小甜举着外卖袋：「这单是您家的，十块钱的奶油卷，配送费我免了。」\\\\n钱满仓凑过来，压低声音，吓出一身冷汗：「这位就是传说中的战神？听说他一个人，拦下过三辆大卡车？」老胡：「对，三辆。」你：「是三辆送菜车，在窄路会车。」钱满仓：「……」\\\\n窄巷里电动车排成一排，钱总的车一寸也动不了。战友们等着你一句话，是让路，是堵死，还是一起开饭。", "sceneImage": "/static/art/covers/cover-veteran.jpg", "panels": [{"speaker": "旁白", "text": "巷口突然响起一排电动车的喇叭声。一群骑手齐刷刷刹在店门口，黄的蓝的头盔，同声大喊：「恭迎老班长归来！」钱满仓的黑色加长车被堵在巷口，司机摇下车窗：「麻烦让一让。」"}, {"speaker": "旁白", "text": "老胡摘下头盔，眼眶一红，敬了个标准的礼：「老班长，群里说你回来了，我们送完这单就赶过来了！」他身后的小甜举着外卖袋：「这单是您家的，十块钱的奶油卷，配送费我免了。」"}, {"speaker": "旁白", "text": "钱满仓凑过来，压低声音，吓出一身冷汗：「这位就是传说中的战神？听说他一个人，拦下过三辆大卡车？」老胡：「对，三辆。」你：「是三辆送菜车，在窄路会车。」钱满仓：「……」"}, {"speaker": "旁白", "text": "窄巷里电动车排成一排，钱总的车一寸也动不了。战友们等着你一句话，是让路，是堵死，还是一起开饭。"}], "choices": [{"choiceId": "veteran_e3_c3", "id": "A", "label": "A", "text": "请战友们进店吃奶油卷", "styleTag": "打工人觉醒", "feedback": "你推开店门，喊了一句奶油卷管够。骑手们鱼贯而入，把小小的面包店挤得像春运。知夏端出一盘又一盘，边端边得意地笑。钱满仓站在门口，没人理他。他看了看表，又看了看奶油卷，默默站到队尾。老胡把头盔挂在门把手上：「班长，下回有事，我们一声令下就到。」", "outcome": "你推开店门，喊了一句奶油卷管够。骑手们鱼贯而入，把小小的面包店挤得像春运。知夏端出一盘又一盘，边端边得意地笑。钱满仓站在门口，没人理他。他看了看表，又看了看奶油卷，默默站到队尾。老胡把头盔挂在门把手上：「班长，下回有事，我们一声令下就到。」", "qualityBonus": 15, "effects": {"pleasure": 3, "drama": 4, "anger": -1, "evidence": 0, "subversion": 1}}, {"choiceId": "veteran_e3_c1", "id": "B", "label": "B", "text": "指着限宽牌，请钱总倒车出巷", "styleTag": "经典套路", "feedback": "你（指着巷口的限宽牌）：「本巷限宽两米。」钱满仓的司机抬头看了一眼，脸色发白：「我们这车，两米二。」你：「那得倒出去。」老胡：「倒车我们班长最拿手，免费指挥。」钱满仓盯着限宽牌，咽了口唾沫。", "outcome": "你（指着巷口的限宽牌）：「本巷限宽两米。」钱满仓的司机抬头看了一眼，脸色发白：「我们这车，两米二。」你：「那得倒出去。」老胡：「倒车我们班长最拿手，免费指挥。」钱满仓盯着限宽牌，咽了口唾沫。", "qualityBonus": 12, "effects": {"pleasure": 3, "drama": 5, "anger": 1, "evidence": 1, "subversion": 0}}, {"choiceId": "veteran_e3_c2", "id": "C", "label": "C", "text": "一声令下，全体鸣笛", "styleTag": "离谱反套路", "feedback": "你（一声令下）：「全体，鸣笛！」几十辆电动车同时按响喇叭，巷子里像开了场迷你演唱会。钱满仓捂着耳朵：「别叫了！」隔壁面馆老板推开窗：「谁家在放喇叭？」你们收到了第一张噪音投诉。", "outcome": "你（一声令下）：「全体，鸣笛！」几十辆电动车同时按响喇叭，巷子里像开了场迷你演唱会。钱满仓捂着耳朵：「别叫了！」隔壁面馆老板推开窗：「谁家在放喇叭？」你们收到了第一张噪音投诉。", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 8, "anger": 4, "evidence": 0, "subversion": 0}}]}, {"ep": 4, "number": 4, "id": "veteran.ep4", "title": "第 4 集：倒车入库不是表演", "sceneDesc": "刘阿姨叉着腰站在巷口，手里捏着一张评分表：「想留下可以，两行字记清楚。爽点值满四十六、戏剧浓度压在七十五以下，算知夏信得过；戏剧浓度过九十五，算吹牛，当场作废。头一个考验，倒车。」她把加长车的钥匙往你手里一拍。\\\\n钱满仓靠在车边，抬了抬下巴：「路边那个车位，只比我的车长半米，退伍兵也不是神仙吧？」周围的邻居纷纷探出头，有人已经搬出了小板凳。\\\\n老胡凑过来，小声说：「老班长，这车后视镜能电动折叠，要不要……」你：「不用。」你摸了摸方向盘，像在摸一位老战友。\\\\n钥匙在手，巷口围满了人。倒怎么倒，倒给谁看，这一下要记进评分表，后面两集也多半顺着它写，你得现在拿主意。", "sceneImage": "/static/art/covers/cover-veteran.jpg", "panels": [{"speaker": "旁白", "text": "刘阿姨叉着腰站在巷口，手里捏着一张评分表：「想留下可以，两行字记清楚。爽点值满四十六、戏剧浓度压在七十五以下，算知夏信得过；戏剧浓度过九十五，算吹牛，当场作废。头一个考验，倒车。」她把加长车的钥匙往你手里一拍。"}, {"speaker": "旁白", "text": "钱满仓靠在车边，抬了抬下巴：「路边那个车位，只比我的车长半米，退伍兵也不是神仙吧？」周围的邻居纷纷探出头，有人已经搬出了小板凳。"}, {"speaker": "旁白", "text": "老胡凑过来，小声说：「老班长，这车后视镜能电动折叠，要不要……」你：「不用。」你摸了摸方向盘，像在摸一位老战友。"}, {"speaker": "旁白", "text": "钥匙在手，巷口围满了人。倒怎么倒，倒给谁看，这一下要记进评分表，后面两集也多半顺着它写，你得现在拿主意。"}], "choices": [{"choiceId": "veteran_e4_c2", "id": "A", "label": "A", "text": "单手搭椅背，头也不回地倒", "styleTag": "离谱反套路", "feedback": "你单手搭着椅背，另一只手扶着方向盘，冲人群挥了挥，车稳稳滑进车位，倒车雷达连一声都没来得及响。全巷爆发出掌声，钱满仓委屈地把车钥匙摔在地上：「这是我的车，不是你的舞台！」", "outcome": "你单手搭着椅背，另一只手扶着方向盘，冲人群挥了挥，车稳稳滑进车位，倒车雷达连一声都没来得及响。全巷爆发出掌声，钱满仓委屈地把车钥匙摔在地上：「这是我的车，不是你的舞台！」", "qualityBonus": 18, "effects": {"pleasure": 4, "drama": 30, "anger": 18, "evidence": 0, "subversion": 0}}, {"choiceId": "veteran_e4_c1", "id": "B", "label": "B", "text": "下车拿卷尺，量车位和车身", "styleTag": "经典套路", "feedback": "你下车拿出卷尺量了一遍：车位六米一，车身五米六，余量五十厘米。你（抬了抬下巴）：「够。」钱满仓：「五十厘米你敢倒？」你：「前后各二十五，够我转身。」邻居们倒吸一口气，开始掐表。", "outcome": "你下车拿出卷尺量了一遍：车位六米一，车身五米六，余量五十厘米。你（抬了抬下巴）：「够。」钱满仓：「五十厘米你敢倒？」你：「前后各二十五，够我转身。」邻居们倒吸一口气，开始掐表。", "qualityBonus": 12, "effects": {"pleasure": 22, "drama": 10, "anger": -6, "evidence": 1, "subversion": 0}}, {"choiceId": "veteran_e4_c3", "id": "C", "label": "C", "text": "把钥匙还给阿姨：我只会倒面包车", "styleTag": "打工人觉醒", "feedback": "你（把钥匙还给刘阿姨）：「这车我不会开，我只会倒面包车。」你走到店后门，把送货的小面包车一把方向倒进了路边车位，车屁股离路牙只剩一指宽。刘阿姨张了张嘴：「你这……不是倒得挺好吗？」你：「家用的。」", "outcome": "你（把钥匙还给刘阿姨）：「这车我不会开，我只会倒面包车。」你走到店后门，把送货的小面包车一把方向倒进了路边车位，车屁股离路牙只剩一指宽。刘阿姨张了张嘴：「你这……不是倒得挺好吗？」你：「家用的。」", "qualityBonus": 15, "effects": {"pleasure": 14, "drama": 8, "anger": -2, "evidence": 0, "subversion": 1}}]}, {"ep": 5, "number": 5, "id": "veteran.ep5", "title": "第 5 集：协议装进面包盒", "sceneDesc": "夜里的面包店，只剩你和知夏。刘阿姨在门口来回走了三趟，终于推门进来，攥着衣角：「知夏，我今天看见了，钱总的手机屏保，是你们家铺面的平面图。」\\\\n知夏（把围裙解下来，叠得整整齐齐）：「妈，我知道。」刘阿姨张着嘴，半天说不出话。老胡在窗外探头：「老班长，明早的签约仪式，我们去不去？」\\\\n桌上摆着你的退伍证、三年的汇款单，还有那份离婚协议的原稿。知夏小声说：「明天，别让东西丢了。」店里能锁东西的，只有那只装零钱的铁皮面包盒。\\\\n协议、汇款单、退伍证，放哪儿都不让人踏实。面包盒、战友群、纸飞机，明天用得上哪一样，你现在得挑一个。", "sceneImage": "/static/art/covers/cover-veteran.jpg", "panels": [{"speaker": "旁白", "text": "夜里的面包店，只剩你和知夏。刘阿姨在门口来回走了三趟，终于推门进来，攥着衣角：「知夏，我今天看见了，钱总的手机屏保，是你们家铺面的平面图。」"}, {"speaker": "旁白", "text": "知夏（把围裙解下来，叠得整整齐齐）：「妈，我知道。」刘阿姨张着嘴，半天说不出话。老胡在窗外探头：「老班长，明早的签约仪式，我们去不去？」"}, {"speaker": "旁白", "text": "桌上摆着你的退伍证、三年的汇款单，还有那份离婚协议的原稿。知夏小声说：「明天，别让东西丢了。」店里能锁东西的，只有那只装零钱的铁皮面包盒。"}, {"speaker": "旁白", "text": "协议、汇款单、退伍证，放哪儿都不让人踏实。面包盒、战友群、纸飞机，明天用得上哪一样，你现在得挑一个。"}], "choices": [{"choiceId": "veteran_e5_c3", "id": "A", "label": "A", "text": "把协议折成纸飞机，大家比赛", "styleTag": "打工人觉醒", "feedback": "你把离婚协议折成了纸飞机，老胡一个，小甜一个，刘阿姨也折了一个。五架纸飞机从面包店窗口飞出去，落在了钱满仓的车上。知夏笑得直不起腰：「这是明天的合同？」你：「这是明天的开场。」", "outcome": "你把离婚协议折成了纸飞机，老胡一个，小甜一个，刘阿姨也折了一个。五架纸飞机从面包店窗口飞出去，落在了钱满仓的车上。知夏笑得直不起腰：「这是明天的合同？」你：「这是明天的开场。」", "qualityBonus": 15, "effects": {"pleasure": 6, "drama": 6, "anger": -3, "evidence": 0, "subversion": 1}}, {"choiceId": "veteran_e5_c2", "id": "B", "label": "B", "text": "联系记者，明早开战神发布会", "styleTag": "离谱反套路", "feedback": "你（给记者发了条消息）：「明早，战神发布会。」对方秒回：「地点？战神是谁？」你盯着屏幕想了半天，发现自己没准备稿子。老胡在窗外喊：「班长，要不要我们练练口号？」", "outcome": "你（给记者发了条消息）：「明早，战神发布会。」对方秒回：「地点？战神是谁？」你盯着屏幕想了半天，发现自己没准备稿子。老胡在窗外喊：「班长，要不要我们练练口号？」", "qualityBonus": 18, "effects": {"pleasure": 2, "drama": 14, "anger": 8, "evidence": 0, "subversion": 0}}, {"choiceId": "veteran_e5_c1", "id": "C", "label": "C", "text": "把三样东西封进面包盒，贴上日期", "styleTag": "经典套路", "feedback": "你把退伍证、汇款单和协议原稿一起装进铁皮面包盒，盖上盖子，知夏在封条上写下日期，刘阿姨按了个手印：「我作证。」老胡在窗外竖起大拇指：「这比保险箱有仪式感。」", "outcome": "你把退伍证、汇款单和协议原稿一起装进铁皮面包盒，盖上盖子，知夏在封条上写下日期，刘阿姨按了个手印：「我作证。」老胡在窗外竖起大拇指：「这比保险箱有仪式感。」", "qualityBonus": 12, "effects": {"pleasure": 9, "drama": 6, "anger": 0, "evidence": 1, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "veteran.ep6", "title": "第 6 集：签约仪式变试吃会", "sceneDesc": "第二天上午，知夏烘焙门口拉起红色横幅：战略合作签约仪式。记者、邻居、战友挤满了巷子。钱满仓整了整西装，抢先坐到主位：「各位，今天我们见证一件大事。」\\\\n刘阿姨拿着话筒，紧张得声音发飘：「各……各位，请新郎……不对，请签约双方入座。」台下哄笑。钱满仓把文件夹推到知夏面前，封面上《离婚协议》四个字，被一条胶带贴住，改成了《合作意向书》。\\\\n知夏攥着笔，指节发白。巷口，三十辆电动车排成扇形，头盔在阳光下闪成一片。老胡冲你比了个手势：随时可以。窗台上，那只铁皮面包盒安静地躺着。\\\\n话筒、笔、面包盒、三十个头盔，全在等你。这一场不用倒车，最后一句台词，你来说。", "sceneImage": "/static/art/covers/cover-veteran.jpg", "panels": [{"speaker": "旁白", "text": "第二天上午，知夏烘焙门口拉起红色横幅：战略合作签约仪式。记者、邻居、战友挤满了巷子。钱满仓整了整西装，抢先坐到主位：「各位，今天我们见证一件大事。」"}, {"speaker": "旁白", "text": "刘阿姨拿着话筒，紧张得声音发飘：「各……各位，请新郎……不对，请签约双方入座。」台下哄笑。钱满仓把文件夹推到知夏面前，封面上《离婚协议》四个字，被一条胶带贴住，改成了《合作意向书》。"}, {"speaker": "旁白", "text": "知夏攥着笔，指节发白。巷口，三十辆电动车排成扇形，头盔在阳光下闪成一片。老胡冲你比了个手势：随时可以。窗台上，那只铁皮面包盒安静地躺着。"}, {"speaker": "旁白", "text": "话筒、笔、面包盒、三十个头盔，全在等你。这一场不用倒车，最后一句台词，你来说。"}], "choices": [{"choiceId": "veteran_e6_c1", "id": "A", "label": "A", "text": "打开面包盒，请记者当面核对", "styleTag": "经典套路", "feedback": "你拆开封条，请记者一份份翻看汇款单和退伍证，再翻到协议第七页的小字。记者们读完，齐刷刷抬头看向钱满仓。他手里的话筒不知什么时候关了。刘阿姨把话筒拿回来：「各位，今天的签约，取消。」", "outcome": "你拆开封条，请记者一份份翻看汇款单和退伍证，再翻到协议第七页的小字。记者们读完，齐刷刷抬头看向钱满仓。他手里的话筒不知什么时候关了。刘阿姨把话筒拿回来：「各位，今天的签约，取消。」", "qualityBonus": 12, "effects": {"pleasure": 14, "drama": 8, "anger": 0, "evidence": 1, "subversion": 0}}, {"choiceId": "veteran_e6_c3", "id": "B", "label": "B", "text": "宣布签约仪式改成面包试吃会", "styleTag": "打工人觉醒", "feedback": "你（把话筒递给知夏）：「今天谁来都能试吃，奶油卷管够。」邻居们鼓掌，战友们排起队，钱满仓的助手端着盘子站在一边，不知道该不该拿。刘阿姨咬了口奶油卷：「这味，比钱总家的强。」", "outcome": "你（把话筒递给知夏）：「今天谁来都能试吃，奶油卷管够。」邻居们鼓掌，战友们排起队，钱满仓的助手端着盘子站在一边，不知道该不该拿。刘阿姨咬了口奶油卷：「这味，比钱总家的强。」", "qualityBonus": 15, "effects": {"pleasure": 10, "drama": 8, "anger": -2, "evidence": 0, "subversion": 1}}, {"choiceId": "veteran_e6_c2", "id": "C", "label": "C", "text": "请全体战友列队，齐喊战神归来", "styleTag": "离谱反套路", "feedback": "你一挥手，三十辆电动车在巷口排成扇形，齐声大喊：「战神归来！」声音震得面包店招牌晃了晃。记者们的镜头转向你，钱满仓脸色发白。喊完，老胡小声问：「班长，接下来呢？」你（想了想）：「接下来……没台词。」", "outcome": "你一挥手，三十辆电动车在巷口排成扇形，齐声大喊：「战神归来！」声音震得面包店招牌晃了晃。记者们的镜头转向你，钱满仓脸色发白。喊完，老胡小声问：「班长，接下来呢？」你（想了想）：「接下来……没台词。」", "qualityBonus": 18, "effects": {"pleasure": 3, "drama": 22, "anger": 12, "evidence": 0, "subversion": 0}}]}]', endings_json = '[{"id": "veteran.end1", "type": "hidden", "priority": 100, "title": "离婚协议变员工餐单", "text": "卷尺量出的数字，和战友们一张张签到表，被你并排摆在桌上。知夏把离婚协议翻过来，背面写了一份员工餐单：每日奶油卷两个，欢迎战友续杯。钱满仓的签约笔，再也没人拿起来。", "condition": {"minStats": {"evidence": 4, "pleasure": 60}, "maxStats": {"anger": 8}}, "posterTag": "隐藏彩蛋", "hint": "点击画面闪烁证物收取 >= 4 份、爽点 >= 60 且反派怒气 <= 8 方可触发传奇加演"}, {"id": "veteran.end2", "type": "subversive", "priority": 80, "title": "战神改行做面包", "text": "你把每一次高光，都推给了面包、战友和排队。战神的名号，被你换成了店里的新品名：老班长奶油卷。钱满仓抱着空文件夹站在门口：「我是来谈合作的，怎么变成排队了？」", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且戏剧未失控时触发反套路收官"}, {"id": "veteran.end3", "type": "unfinished", "priority": 90, "title": "签约仪式没有下集", "text": "你把战友喊来了，把记者喊来了，连喇叭都喊来了，就是协议原稿没带全。直播间弹出一行字：证据不足，待补。钱满仓清清嗓子：「下一部，《战神归来：补交材料篇》，敬请期待。」", "condition": {"minStats": {"drama": 92}}, "posterTag": "喜剧烂尾", "hint": "戏剧张力失控飙升至 >= 92 时触发喜剧烂尾"}, {"id": "veteran.end4", "type": "triumph", "priority": 70, "title": "老班长准点回家", "text": "你该量的量了，该倒的倒了，该说的说了。钱满仓的合同没人签，面包店的铺面保住了。巷口那块限宽牌终于有人认真读了，连送货的货车都绕着走。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/烂尾/反套路）自动保底收官"}]', version = version + 1 WHERE script_id = 'script_07_veteran';

-- 更新剧本《专治各种不服》(script_08_healer) 分集选项顺序/证物配置与结局提示
UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "healer.ep1", "title": "第 1 集：神医招牌少了两个字", "sceneDesc": "你下山帮百物馆修理老钟，钱馆主却挂出神医降临的横幅。你指着预约单说自己是修理师，横幅底下才慢慢展开修物两个小字。\\\\n馆里排起长队，大家抱着漏水茶壶、走慢的钟和不肯合盖的盒子。入口明确写着本故事只讲物件修复，不提供健康建议，也不把真实就医当笑点。\\\\n钱馆主准备让你蒙眼修钟，说越玄乎越好卖门票。林记录拿着检修表，提醒先登记物件状态，不能为了镜头让本来还能修的东西再摔一次。\\\\n你准备开启第一场所谓神迹。可以先检查、先造势，或者先纠正招牌，让每个来的人知道自己到底在排什么队。", "sceneImage": "/static/art/covers/cover-healer.jpg", "panels": [{"speaker": "旁白", "text": "你下山帮百物馆修理老钟，钱馆主却挂出神医降临的横幅。你指着预约单说自己是修理师，横幅底下才慢慢展开修物两个小字。"}, {"speaker": "旁白", "text": "馆里排起长队，大家抱着漏水茶壶、走慢的钟和不肯合盖的盒子。入口明确写着本故事只讲物件修复，不提供健康建议，也不把真实就医当笑点。"}, {"speaker": "旁白", "text": "钱馆主准备让你蒙眼修钟，说越玄乎越好卖门票。林记录拿着检修表，提醒先登记物件状态，不能为了镜头让本来还能修的东西再摔一次。"}, {"speaker": "旁白", "text": "你准备开启第一场所谓神迹。可以先检查、先造势，或者先纠正招牌，让每个来的人知道自己到底在排什么队。"}], "choices": [{"choiceId": "healer_e1_c1", "id": "A", "label": "A", "text": "登记老钟状态后检修", "styleTag": "经典套路", "feedback": "你记下停摆时间和缺损零件，林记录拍照存档。钱馆主没等到天降金光，先等到一张人人看得懂的检修表。", "outcome": "你记下停摆时间和缺损零件，林记录拍照存档。钱馆主没等到天降金光，先等到一张人人看得懂的检修表。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "healer_e1_c2", "id": "B", "label": "B", "text": "蒙眼宣称一响震全馆", "styleTag": "离谱反套路", "feedback": "围观者瞬间举起手机，老钟却还没拆开。钱馆主立刻售出更多前排座位，把你的承诺写得比钟面还大。", "outcome": "围观者瞬间举起手机，老钟却还没拆开。钱馆主立刻售出更多前排座位，把你的承诺写得比钟面还大。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "healer_e1_c3", "id": "C", "label": "C", "text": "把招牌改成百物修理日", "styleTag": "打工人觉醒", "feedback": "阿竹搬来普通排号牌，队伍反而更清楚。你先帮一位街坊拧紧杯盖，得到的掌声不需要任何神秘称呼。", "outcome": "阿竹搬来普通排号牌，队伍反而更清楚。你先帮一位街坊拧紧杯盖，得到的掌声不需要任何神秘称呼。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 2, "number": 2, "id": "healer.ep2", "title": "第 2 集：祖传秘方是保养手册", "sceneDesc": "钱馆主拿出祖传匣子，说里面是失传秘方，准备按页出售观看资格。林记录看到封口上写着公开资料，要求先查来源。\\\\n匣子里装着旧保养手册，记载各种机关如何清洁与保存。最后几页被抽走，只剩一个写着借出未还的纸条，没有任何包治百病的内容。\\\\n阿竹认出纸条上的借阅号，说后院竹筒里存着一本更早的索引。钱馆主嫌索引不好看，提议直接把书封烫成金色。\\\\n你可以按流程封存现有资料，可以将仪式推得更大，也可以跟着阿竹去看那份不起眼的索引。", "sceneImage": "/static/art/covers/cover-healer.jpg", "panels": [{"speaker": "旁白", "text": "钱馆主拿出祖传匣子，说里面是失传秘方，准备按页出售观看资格。林记录看到封口上写着公开资料，要求先查来源。"}, {"speaker": "旁白", "text": "匣子里装着旧保养手册，记载各种机关如何清洁与保存。最后几页被抽走，只剩一个写着借出未还的纸条，没有任何包治百病的内容。"}, {"speaker": "旁白", "text": "阿竹认出纸条上的借阅号，说后院竹筒里存着一本更早的索引。钱馆主嫌索引不好看，提议直接把书封烫成金色。"}, {"speaker": "旁白", "text": "你可以按流程封存现有资料，可以将仪式推得更大，也可以跟着阿竹去看那份不起眼的索引。"}], "choices": [{"choiceId": "healer_e2_c3", "id": "A", "label": "A", "text": "寻找竹筒里的旧索引", "styleTag": "打工人觉醒", "feedback": "索引指向创办人留下的修物档案，还标着最后几页的归还位置。你交给林记录保管，不急着把寻书演成天命。", "outcome": "索引指向创办人留下的修物档案，还标着最后几页的归还位置。你交给林记录保管，不急着把寻书演成天命。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "healer_e2_c1", "id": "B", "label": "B", "text": "登记手册缺页并查借阅号", "styleTag": "经典套路", "feedback": "林记录留下页码清单，钱馆主不能再把缺页说成不可外传。材料虽不完整，至少有人开始认真追问它去了哪里。", "outcome": "林记录留下页码清单，钱馆主不能再把缺页说成不可外传。材料虽不完整，至少有人开始认真追问它去了哪里。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "healer_e2_c2", "id": "C", "label": "C", "text": "给秘方举行隆重开匣礼", "styleTag": "离谱反套路", "feedback": "匣子被灯照得发亮，翻开的却是普通保养目录。观众开始询问所谓秘方在哪里，钱馆主只好追加一层神秘包装。", "outcome": "匣子被灯照得发亮，翻开的却是普通保养目录。观众开始询问所谓秘方在哪里，钱馆主只好追加一层神秘包装。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 3, "number": 3, "id": "healer.ep3", "title": "第 3 集：一针见效其实是插销", "sceneDesc": "展馆最珍贵的木鸟不能振翅，钱馆主宣布这是百年疑难。阿竹指向松脱的插销，说昨天搬展台时它还好好的。\\\\n钱馆主要求你先摆一个高深姿势，再让摄影师拍手部特写。林记录提醒，先告知藏品保管人修复方案，再动手，镜头可以等。\\\\n观众对木鸟的来历很感兴趣，真正的故事是老匠人如何设计连杆，并不是你能不能用一句台词让木头相信奇迹。\\\\n木鸟停在桌中央。你可以公开结构，可以赌一场玄乎表演，或者把镜头交给也参与过修复的年轻学徒。", "sceneImage": "/static/art/covers/cover-healer.jpg", "panels": [{"speaker": "旁白", "text": "展馆最珍贵的木鸟不能振翅，钱馆主宣布这是百年疑难。阿竹指向松脱的插销，说昨天搬展台时它还好好的。"}, {"speaker": "旁白", "text": "钱馆主要求你先摆一个高深姿势，再让摄影师拍手部特写。林记录提醒，先告知藏品保管人修复方案，再动手，镜头可以等。"}, {"speaker": "旁白", "text": "观众对木鸟的来历很感兴趣，真正的故事是老匠人如何设计连杆，并不是你能不能用一句台词让木头相信奇迹。"}, {"speaker": "旁白", "text": "木鸟停在桌中央。你可以公开结构，可以赌一场玄乎表演，或者把镜头交给也参与过修复的年轻学徒。"}], "choices": [{"choiceId": "healer_e3_c2", "id": "A", "label": "A", "text": "宣布只需一指便可回春", "styleTag": "离谱反套路", "feedback": "木鸟确实动了，钱馆主立刻把普通插销称作传世神器。林记录摇头，提醒夸大的部分并不会自动变成事实。", "outcome": "木鸟确实动了，钱馆主立刻把普通插销称作传世神器。林记录摇头，提醒夸大的部分并不会自动变成事实。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "healer_e3_c1", "id": "B", "label": "B", "text": "说明结构并获授权后修复", "styleTag": "经典套路", "feedback": "保管人确认方案，你按记录复位插销。木鸟重新振翅，钱馆主准备好的神秘旁白，被一段清楚的机械说明替代。", "outcome": "保管人确认方案，你按记录复位插销。木鸟重新振翅，钱馆主准备好的神秘旁白，被一段清楚的机械说明替代。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "healer_e3_c3", "id": "C", "label": "C", "text": "请阿竹演示正确保养方法", "styleTag": "打工人觉醒", "feedback": "阿竹讲完后请你协助复位，修复成果变成可以传授的知识。钱馆主发现神秘感少了，观众的问题却更多了。", "outcome": "阿竹讲完后请你协助复位，修复成果变成可以传授的知识。钱馆主发现神秘感少了，观众的问题却更多了。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 4, "number": 4, "id": "healer.ep4", "title": "第 4 集：大人物的杯子漏了", "sceneDesc": "展馆来了重要赞助人，钱馆主把漏水保温杯端上红垫，要求你证明真正实力。赞助人只想知道杯子今天还能不能正常用。\\\\n你检查后发现杯盖配件不匹配，需更换相容零件。钱馆主不喜欢这个普通答案，想让你说成祖传秘术终于现世。\\\\n林记录准备报价和使用说明，阿竹找出对应配件编号。故事第一次给了夸张宣传一个对照，真正有效的帮助往往没有神秘配乐。\\\\n你可以把修复依据说清，可以继续承诺无所不能，或者请赞助人参加一场普通的动手课。", "sceneImage": "/static/art/covers/cover-healer.jpg", "panels": [{"speaker": "旁白", "text": "展馆来了重要赞助人，钱馆主把漏水保温杯端上红垫，要求你证明真正实力。赞助人只想知道杯子今天还能不能正常用。"}, {"speaker": "旁白", "text": "你检查后发现杯盖配件不匹配，需更换相容零件。钱馆主不喜欢这个普通答案，想让你说成祖传秘术终于现世。"}, {"speaker": "旁白", "text": "林记录准备报价和使用说明，阿竹找出对应配件编号。故事第一次给了夸张宣传一个���照，真正有效的帮助往往没有神秘配乐。"}, {"speaker": "旁白", "text": "你可以把修复依据说清，可以继续承诺无所不能，或者请赞助人参加一场普通的动手课。"}], "choices": [{"choiceId": "healer_e4_c3", "id": "A", "label": "A", "text": "给赞助人开一节免费保养课", "styleTag": "打工人觉醒", "feedback": "对方认真学会检查杯盖，主动提出支持公开课程。钱馆主的贵宾神迹套餐失去了最有可能买单的人。", "outcome": "对方认真学会检查杯盖，主动提出支持公开课程。钱馆主的贵宾神迹套餐失去了最有可能买单的人。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "healer_e4_c2", "id": "B", "label": "B", "text": "承诺以后所有杯子永不漏水", "styleTag": "离谱反套路", "feedback": "现场惊叹更大了，林记录却无法替你写出这样的保证。钱馆主开始筹备永恒展区，麻烦也跟着膨胀。", "outcome": "现场惊叹更大了，林记录却无法替你写出这样的保证。钱馆主开始筹备永恒展区，麻烦也跟着膨胀。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "healer_e4_c1", "id": "C", "label": "C", "text": "列出配件与费用让对方决定", "styleTag": "经典套路", "feedback": "赞助人确认后完成更换，并保留检测记录。钱馆主想抬价，报价单却已经清楚写明了每一项。", "outcome": "赞助人确认后完成更换，并保留检测记录。钱馆主想抬价，报价单却已经清楚写明了每一项。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 5, "number": 5, "id": "healer.ep5", "title": "第 5 集：继承的是手册不是光环", "sceneDesc": "林记录收到创办人授权档案，确认你有权接手百物馆的修复资料。文件要求公开保养知识，不允许用神医头衔暗示医疗能力。\\\\n钱馆主想把这一条折进装订线，称观众更愿意为秘密付钱。阿竹拿来放大镜，平静地问为什么最重要的约定总被排得最小。\\\\n你需要决定先存档还是先揭晓。真正的权利来自文件，观众的期待来自诚实说明，二者都不会因金光更亮自动完成。\\\\n最后一场开馆仪式马上开始。你可以留下可核对的档案，也可以把展示包装成新的神话，或者让所有人先学会修一个简单小物件。", "sceneImage": "/static/art/covers/cover-healer.jpg", "panels": [{"speaker": "旁白", "text": "林记录收到创办人授权档案，确认你有权接手百物馆的修复资料。文件要求公开保养知识，不允许用神医头衔暗示医疗能力。"}, {"speaker": "旁白", "text": "钱馆主想把这一条折进装订线，称观众更愿意为秘密付钱。阿竹拿来放大镜，平静地问为什么最重要的约定总被排得最小。"}, {"speaker": "旁白", "text": "你需要决定先存档还是先揭晓。真正的权利来自文件，观众的期待来自诚实说明，二者都不会因金光更亮自动完成。"}, {"speaker": "旁白", "text": "最后一场开馆仪式马上开始。你可以留下可核对的档案，也可以把展示包装成新的神话，或者让所有人先学会修一个简单小物件。"}], "choices": [{"choiceId": "healer_e5_c1", "id": "A", "label": "A", "text": "核验授权并保存完整副本", "styleTag": "经典套路", "feedback": "林记录按页存档，公开条款没有被裁掉。你接过的是可追溯的资料与责任，不是一张可以随意夸张的招牌。", "outcome": "林记录按页存档，公开条款没有被裁掉。你接过的是可追溯的资料与责任，不是一张可以随意夸张的招牌。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "healer_e5_c3", "id": "B", "label": "B", "text": "宣布开设人人能来的修理课堂", "styleTag": "打工人觉醒", "feedback": "你把工作台移到明亮处，教大家记录问题和求助专业维修。秘密感下降了，展馆反而有了更长久的使用方式。", "outcome": "你把工作台移到明亮处，教大家记录问题和求助专业维修。秘密感下降了，展馆反而有了更长久的使用方式。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "healer_e5_c2", "id": "C", "label": "C", "text": "先给神医头衔加一圈金边", "styleTag": "离谱反套路", "feedback": "钱馆主连夜升级灯箱，授权条款却仍没核清。阿竹提醒，你现在看起来更像一个会发光的说明书封面。", "outcome": "钱馆主连夜升级灯箱，授权条款却仍没核清。阿竹提醒，你现在看起来更像一个会发光的说明书封面。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "healer.ep6", "title": "第 6 集：全场跪下捡螺丝", "sceneDesc": "最终揭晓时，钱馆主把一箱小螺丝踢翻在地。主持刚喊全场跪下，字幕改成全场低头，小心脚下，大家先把通道清出来。\\\\n木鸟、老钟和保温杯被摆成一排，每件都附着检修记录。观众可以看到哪些真的修好，哪些仍需专业处理，没有万能身份替代真实边界。\\\\n林记录检查你留存的材料，阿竹举起新的招牌。要让百物馆长期开放，必须决定它靠可信服务，还是永远追加一次更夸张的开匣礼。\\\\n你选择最后一句话。讲明修复事实，宣布不可兑现的奇迹，或者让这场神医戏终于回到人人都能参与的修物日。", "sceneImage": "/static/art/covers/cover-healer.jpg", "panels": [{"speaker": "旁白", "text": "最终揭晓时，钱馆主把一箱小螺丝踢翻在地。主持刚喊全场跪下，字幕改成全场低头，小心脚下，大家先把通道清出来。"}, {"speaker": "旁白", "text": "木鸟、老钟和保温杯被摆成一排，每件都附着检修记录。观众可以看到哪些真的修好，哪些仍需专业处理，没有万能身份替代真实边界。"}, {"speaker": "旁白", "text": "林记录检查你留存的材料，阿竹举起新的招牌。要让百物馆长期开放，必须决定它靠可信服务，还是永远追加一次更夸张的开匣礼。"}, {"speaker": "旁白", "text": "你选择最后一句话。讲明修复事实，宣布不可兑现的奇迹，或者让这场神医戏终于回到人人都能参与的修物日。"}], "choices": [{"choiceId": "healer_e6_c2", "id": "A", "label": "A", "text": "宣称下一集什么都能修", "styleTag": "离谱反套路", "feedback": "掌声很响，预约单迅速写满。林记录把无法兑现的项目圈红，屏幕像一份越来越长的待办，而不是大结局。", "outcome": "掌声很响，预约单迅速写满。林记录把无法兑现的项目圈红，屏幕像一份越来越长的待办，而不是大结局。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "healer_e6_c3", "id": "B", "label": "B", "text": "带大家开第一场公开修理日", "styleTag": "打工人觉醒", "feedback": "钱馆主也分到一把扫帚，负责把工作区整理好。阿竹给每位参与者发记录卡，故事终于从一个人的神迹变成一群人的手艺。", "outcome": "钱馆主也分到一把扫帚，负责把工作区整理好。阿竹给每位参与者发记录卡，故事终于从一个人的神迹变成一群人的手艺。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "healer_e6_c1", "id": "C", "label": "C", "text": "按检修记录逐件展示成果", "styleTag": "经典套路", "feedback": "你说明完成的步骤与仍需处理的问题，观众认可这份坦诚。钱馆主没法再用同一批螺丝讲出八十种神秘来历。", "outcome": "你说明完成的步骤与仍需处理的问题，观众认可这份坦诚。钱馆主没法再用同一批螺丝讲出八十种神秘来历。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}]', endings_json = '[{"id": "healer.end1", "type": "hidden", "priority": 100, "title": "神医专修夸张宣传", "text": "索引与授权副本补齐档案，你公开创办人的真实心愿。百物馆从此以修物为业，最先被修好的东西，是门口那块过分承诺的招牌。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 42}}, "posterTag": "隐藏彩蛋", "hint": "选择搜证方向并点击画面闪烁证物收取 >= 4 份，且反派怒气 <= 42 方可解锁"}, {"id": "healer.end2", "type": "subversive", "priority": 90, "title": "妙手回春的是保温杯", "text": "你反复拒绝神化，开起公开修理课堂。海报写着妙手回春，底下同样大的字明确说明，本期主角是一只保温杯。", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触及隐藏或烂尾即可解锁"}, {"id": "healer.end3", "type": "unfinished", "priority": 80, "title": "祖传秘方待补页", "text": "灯箱亮遍全馆，资料却没有闭环。主持宣布下部剧先拍目录整理，钱馆主举着金匣子问，目录能不能也办一次揭晓。", "condition": {"minStats": {"anger": 60}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气累计 >= 60 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "healer.end4", "type": "triumph", "priority": 70, "title": "百物有修人各有长", "text": "你以记录与诚实说明完成交接，展馆有了稳定的修复流程。阿竹学会了第一项手艺，观众带走的不是神话，而是可信的帮助。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_08_healer';

-- 更新剧本《娘娘她靠整活封后》(script_09_palace) 分集选项顺序/证物配置与结局提示
UPDATE ry_duanju.dj_script SET episodes_json = '[{"ep": 1, "number": 1, "id": "palace.ep1", "title": "第 1 集：睁眼先领三套宫规", "sceneDesc": "你穿进一部架空宫廷戏，身份是御膳房记账员。柳总管递来三套互相矛盾的宫规，要求你在天亮前证明自己懂规矩。\\\\n团子掌勺说宫里今天最大的难题是桂花糕不够分，闻书官则指出三套规则都没盖启用章。宏大的宫斗开场，先卡在文件版本。\\\\n柳总管宣布你若选错糕点摆盘，就去擦整座回廊的柱子。你看看远处一排望不到头的柱子，决定不能只靠一个不服输的特写解决。\\\\n所有场景都在虚构宫廷戏里，不涉及真实历史人物或权力事件。你可以查规则、摆架势，或者从让大家公平吃糕开始。", "sceneImage": "/static/art/covers/cover-palace.jpg", "panels": [{"speaker": "旁白", "text": "你穿进一部架空宫廷戏，身份是御膳房记账员。柳总管递来三套互相矛盾的宫规，要求你在天亮前证明自己懂规矩。"}, {"speaker": "旁白", "text": "团子掌勺说宫里今天最大的难题是桂花糕不够分，闻书官则指出三套规则都没盖启用章。宏大的宫斗开场，先卡在文件版本。"}, {"speaker": "旁白", "text": "柳总管宣布你若选错糕点摆盘，就去擦整座回廊的柱子。你看看远处一排望不到头的柱子，决定不能只靠一个不服输的特写解决。"}, {"speaker": "旁白", "text": "所有场景都在虚构宫廷戏里，不涉及真实历史人物或权力事件。你可以查规则、摆架势，或者从让大家公平吃糕开始。"}], "choices": [{"choiceId": "palace_e1_c3", "id": "A", "label": "A", "text": "先把桂花糕按人数分好", "styleTag": "打工人觉醒", "feedback": "团子掌勺照着人数重切，每个人都有一块。刚准备站队的人群开始讨论甜度，紧张的阵营图暂时没了用处。", "outcome": "团子掌勺照着人数重切，每个人都有一块。刚准备站队的人群开始讨论甜度，紧张的阵营图暂时没了用处。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "palace_e1_c1", "id": "B", "label": "B", "text": "核对宫规启用日期", "styleTag": "经典套路", "feedback": "闻书官查出只有一套仍有效，柳总管不能再三选一临时改答案。你的第一项宫廷技能，是认清印章落在哪一页。", "outcome": "闻书官查出只有一套仍有效，柳总管不能再三选一临时改答案。你的第一项宫廷技能，是认清印章落在哪一页。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "palace_e1_c2", "id": "C", "label": "C", "text": "摆出我来自未来的姿态", "styleTag": "离谱反套路", "feedback": "众人确实被你的语气镇住，柳总管随即追加未来人专属礼仪题。你赢了一个特写，也多了一叠题目。", "outcome": "众人确实被你的语气镇住，柳总管随即追加未来人专属礼仪题。你赢了一个特写，也多了一叠题目。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 2, "number": 2, "id": "palace.ep2", "title": "第 2 集：冷宫里只有一台算盘", "sceneDesc": "柳总管把你调到最偏的小院，称这里是冷宫待遇。你到场才发现，院里通风好、桌子宽，还堆着多年未核的食材账册。\\\\n闻书官送来一张空白移交表，提醒先记清接到哪些册子。团子掌勺悄悄带来一包糕点纸，说旧账封条常被当包装纸重复使用。\\\\n其中一张纸露出旧库印，柳总管却派人通知，只许检查新账，不许翻老故事。你手里的糕点忽然比任何首饰都像线索。\\\\n你可以先保存账册清单，可以向镜头宣布即将翻盘，也可以摊平这张被油点遮住的包装纸。", "sceneImage": "/static/art/covers/cover-palace.jpg", "panels": [{"speaker": "旁白", "text": "柳总管把你调到最偏的小院，称这里是冷宫待遇。你到场才发现，院里通风好、桌子宽，还堆着多年未核的食材账册。"}, {"speaker": "旁白", "text": "闻书官送来一张空白移交表，提醒先记清接到哪些册子。团子掌勺悄悄带来一包糕点纸，说旧账封条常被当包装纸重复使用。"}, {"speaker": "旁白", "text": "其中一张纸露出旧库印，柳总管却派人通知，只许检查新账，不许翻老故事。你手里的糕点忽然比任何首饰都像线索。"}, {"speaker": "旁白", "text": "你可以先保存账册清单，可以向镜头宣布即将翻盘，也可以摊平这张被油点遮住的包装纸。"}], "choices": [{"choiceId": "palace_e2_c2", "id": "A", "label": "A", "text": "在院门写上本宫即将归来", "styleTag": "离谱反套路", "feedback": "围观者开始来门口合影，柳总管索性派更多人盯着。院子很热闹，算盘却还没拨动第一颗珠。", "outcome": "围观者开始来门口合影，柳总管索性派更多人盯着。院子很热闹，算盘却还没拨动第一颗珠。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "palace_e2_c1", "id": "B", "label": "B", "text": "逐册登记移交并保存封条", "styleTag": "经典套路", "feedback": "闻书官确认收到的账册数量，少一本都会留下空位。柳总管不能悄悄撤掉某册，再让你为缺件负责。", "outcome": "闻书官确认收到的账册数量，少一本都会留下空位。柳总管不能悄悄撤掉某册，再让你为缺件负责。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "palace_e2_c3", "id": "C", "label": "C", "text": "查包装纸上的旧库编号", "styleTag": "打工人觉醒", "feedback": "编号指向一册被改过名字的糕点账，你让闻书官代为保管。团子掌勺第一次觉得自己的打包习惯很有戏份。", "outcome": "编号指向一册被改过名字的糕点账，你让闻书官代为保管。团子掌勺第一次觉得自己的打包习惯很有戏份。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}, {"ep": 3, "number": 3, "id": "palace.ep3", "title": "第 3 集：赏花宴先比谁报销多", "sceneDesc": "宫里准备赏花宴，柳总管让各处比谁的摆盘更贵。你发现同一份桂花糕分别出现在花房、茶房和御膳房的费用里。\\\\n团子掌勺坚持自己只做了一炉，闻书官把三张领用单放在一起，发现签收笔迹与时间完全一致。所谓宫斗大局，突然只剩三个相同的小计。\\\\n柳总管说这叫氛围费，不该用普通账目衡量。你看着眼前的花盆，觉得它们虽然不会说话，但未必愿意为这种费用背锅。\\\\n本集你可以公开对账，可以挑战更豪华的宴会排场，也可以请所有人把花留在盆里，别再为争座位拆来拆去。", "sceneImage": "/static/art/covers/cover-palace.jpg", "panels": [{"speaker": "旁白", "text": "宫里准备赏花宴，柳总管让各处比谁的摆盘更贵。你发现同一份桂花糕分别出现在花房、茶房和御膳房的费用里。"}, {"speaker": "旁白", "text": "团子掌勺坚持自己只做了一炉，闻书官把三张领用单放在一起，发现签收笔迹与时间完全一致。所谓宫斗大局，突然只剩三个相同的小计。"}, {"speaker": "旁白", "text": "柳总管说这叫氛围费，不该用普通账目衡量。你看着眼前的花盆，觉得它们虽然不会说话，但未必愿意为这种费用背锅。"}, {"speaker": "旁白", "text": "本集你可以公开对账，可以挑战更豪华的宴会排场，也可以请所有人把花留在盆里，别再为争座位拆来拆去。"}], "choices": [{"choiceId": "palace_e3_c3", "id": "A", "label": "A", "text": "把比赛改成每人养一盆花", "styleTag": "打工人觉醒", "feedback": "团子掌勺领走一盆薄荷，其他人开始交换养护经验。柳总管站在奖台上，发现没有人还等着排尊贵名次。", "outcome": "团子掌勺领走一盆薄荷，其他人开始交换养护经验。柳总管站在奖台上，发现没有人还等着排尊贵名次。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "palace_e3_c2", "id": "B", "label": "B", "text": "宣布下一宴办得比今天还大", "styleTag": "离谱反套路", "feedback": "柳总管立刻申请更多装饰，费用表迅速长出新页。你获得宫廷大场面，也把需要解释的问题成倍放大。", "outcome": "柳总管立刻申请更多装饰，费用表迅速长出新页。你获得宫廷大场面，也把需要解释的问题成倍放大。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "palace_e3_c1", "id": "C", "label": "C", "text": "展示三张重复领用单", "styleTag": "经典套路", "feedback": "闻书官逐项核对，重复部分被标记待说明。柳总管不能用一句氛围尊贵，把同一炉糕点变出三次采购。", "outcome": "闻书官逐项核对，重复部分被标记待说明。柳总管不能用一句氛围尊贵，把同一炉糕点变出三次采购。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 4, "number": 4, "id": "palace.ep4", "title": "第 4 集：宠冠六宫的是记账本", "sceneDesc": "你把糕点用量和宴会人数列成普通表格，各处终于能提前知道自己该领多少。柳总管称你破坏古老神秘感，闻书官问他神秘感能不能当收据。\\\\n一位来客把你的表格误认成流行的宫廷秘籍，大家争相抄写。团子掌勺郑重声明秘籍核心只有一句，多少人吃多少份。\\\\n柳总管准备最后一场规矩考核，声称谁最会拐弯说话谁就能升职。你不需要通过贬低别人证明聪明，只要决定是否接受这种比赛。\\\\n你的真实任命尚未公开，手里只有逐渐齐全的记录。本集的胜负，可以是事实、排场，或把规矩改成人人听得懂的话。", "sceneImage": "/static/art/covers/cover-palace.jpg", "panels": [{"speaker": "旁白", "text": "你把糕点用量和宴会人数列成普通表格，各处终于能提前知道自己该领多少。柳总管称你破坏古老神秘感，闻书官问他神秘感能不能当收据。"}, {"speaker": "旁白", "text": "一位来客把你的表格误认成流行的宫廷秘籍，大家争相抄写。团子掌勺郑重声明秘籍核心只有一句，多少人吃多少份。"}, {"speaker": "旁白", "text": "柳总管准备最后一场规矩考核，声称谁最会拐弯说话谁就能升职。你不需要通过贬低别人证明聪明，只要决定是否接受这种比赛。"}, {"speaker": "旁白", "text": "你的真实任命尚未公开，手里只有逐渐齐全的记录。本集的胜负，可以是事实、排场，或把规矩改成人人听得懂的话。"}], "choices": [{"choiceId": "palace_e4_c1", "id": "A", "label": "A", "text": "将账目与签收记录公开对照", "styleTag": "经典套路", "feedback": "各处经手人确认份额，柳总管的模糊解释再也躲不开数字。抄秘籍的人发现，最厉害的招式居然是写清楚。", "outcome": "各处经手人确认份额，柳总管的模糊解释再也躲不开数字。抄秘籍的人发现，最厉害的招式居然是写清楚。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "palace_e4_c3", "id": "B", "label": "B", "text": "提议所有通知只写直白人话", "styleTag": "打工人觉醒", "feedback": "闻书官当场重写领用说明，团子掌勺顺畅读完。连最爱旁听宫斗的人也承认，这种胜利比较方便执行。", "outcome": "闻书官当场重写领用说明，团子掌勺顺畅读完。连最爱旁听宫斗的人也承认，这种胜利比较方便执行。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "palace_e4_c2", "id": "C", "label": "C", "text": "用八句谜语回敬考官", "styleTag": "离谱反套路", "feedback": "众人听得很震撼，却没人知道下一顿领几份糕。柳总管借机宣布需要追加解释课，你们又多了一场无用考核。", "outcome": "众人听得很震撼，却没人知道下一顿领几份糕。柳总管借机宣布需要追加解释课，你们又多了一场无用考核。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}]}, {"ep": 5, "number": 5, "id": "palace.ep5", "title": "第 5 集：密旨上写着请附明细", "sceneDesc": "闻书官找回你的正式任命，你原是来核验账目的巡账使，只因开场穿越时摔乱了资料袋。任命要求公开流程，不要求任何人向你下跪。\\\\n柳总管看见抬头后想直接跳到恭迎贵客，闻书官拦住他，请先核验编号。团子掌勺在一旁数着还没解释的那几份桂花糕。\\\\n你可以先封存完整任命和对账材料，也可以让所有人先排队震惊。如今最容易拖慢结局的，不是秘密太深，而是大家太想拍揭晓反应。\\\\n小院的算盘放在桌边，等你做出决定。这次存档会影响最终是否能把旧库编号也一并解释清楚。", "sceneImage": "/static/art/covers/cover-palace.jpg", "panels": [{"speaker": "旁白", "text": "闻书官找回你的正式任命，你原是来核验账目的巡账使，只因开场穿越时摔乱了资料袋。任命要求公开流程，不要求任何人向你下跪。"}, {"speaker": "旁白", "text": "柳总管看见抬头后想直接跳到恭迎贵客，闻书官拦住他，请先核验编号。团子掌勺在一旁数着还没解释的那几份桂花糕。"}, {"speaker": "旁白", "text": "你可以先封存完整任命和对账材料，也可以让所有人先排队震惊。如今最容易拖慢结局的，不是秘密太深，而是大家太想拍揭晓反应。"}, {"speaker": "旁白", "text": "小院的算盘放在桌边，等你做出决定。这次存档会影响最终是否能把旧库编号也一并解释清楚。"}], "choices": [{"choiceId": "palace_e5_c2", "id": "A", "label": "A", "text": "先安排全场恭迎的站位", "styleTag": "离谱反套路", "feedback": "大家排了半天才发现摄影师也在队尾。柳总管熟练地指导震惊表情，对账问题却仍然没有人正式回答。", "outcome": "大家排了半天才发现摄影师也在队尾。柳总管熟练地指导震惊表情，对账问题却仍然没有人正式回答。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "palace_e5_c3", "id": "B", "label": "B", "text": "把巡账使座椅换成公共核账桌", "styleTag": "打工人觉醒", "feedback": "你邀请各处轮流查自己的份额，团子掌勺先坐下。身份没有变成高台，变成了一张更容易找到的工作桌。", "outcome": "你邀请各处轮流查自己的份额，团子掌勺先坐下。身份没有变成高台，变成了一张更容易找到的工作桌。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}, {"choiceId": "palace_e5_c1", "id": "C", "label": "C", "text": "存档任命与全部对账副本", "styleTag": "经典套路", "feedback": "闻书官逐页核验，柳总管再不能拿排场代替说明。你终于拥有可以在结局使用的完整证据，而不是一纸模糊抬头。", "outcome": "闻书官逐页核验，柳总管再不能拿排场代替说明。你终于拥有可以在结局使用的完整证据，而不是一纸模糊抬头。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}]}, {"ep": 6, "number": 6, "id": "palace.ep6", "title": "第 6 集：全场平身因为要开饭", "sceneDesc": "最终宴会开席，闻书官宣读核验结果。柳总管还想用一句宫规深奥结束讨论，团子掌勺举起今日菜单，要求先确认到底做几炉糕。\\\\n你放好任命与账册，若证据齐全，重复领用会被纠正；若一直追排场，收官也只能停在尚待核对，金色印章并不自动填表。\\\\n主持喊全场跪下，字幕改成全场平身，凳子够坐。大家围桌而坐，来客惊讶地发现不用站队也能分到完整的一块糕。\\\\n你选择最后一场戏。让数字说清，让排场继续，或把宫斗秘籍最后一页改成正常吃饭的日常。", "sceneImage": "/static/art/covers/cover-palace.jpg", "panels": [{"speaker": "旁白", "text": "最终宴会开席，闻书官宣读核验结果。柳总管还想用一句宫规深奥结束讨论，团子掌勺举起今日菜单，要求先确认到底做几炉糕。"}, {"speaker": "旁白", "text": "你放好任命与账册，若证据齐全，重复领用会被纠正；若一直追排场，收官也只能停在尚待核对，金色印章并不自动填表。"}, {"speaker": "旁白", "text": "主持喊全场跪下，字幕改成全场平身，凳子够坐。大家围桌而坐，来客惊讶地发现不用站队也能分到完整的一块糕。"}, {"speaker": "旁白", "text": "你选择最后一场戏。让数字说清，让排场继续，或把宫斗秘籍最后一页改成正常吃饭的日常。"}], "choices": [{"choiceId": "palace_e6_c1", "id": "A", "label": "A", "text": "公布核账结果与后续规则", "styleTag": "经典套路", "feedback": "你按可查材料逐项解释，重复申领进入修正流程。闻书官写下简单清晰的新规，宴会终于不必靠猜测运转。", "outcome": "你按可查材料逐项解释，重复申领进入修正流程。闻书官写下简单清晰的新规，宴会终于不必靠猜测运转。", "qualityBonus": 12, "effects": {"pleasure": 12, "drama": 10, "anger": 7, "evidence": 1, "subversion": 0}}, {"choiceId": "palace_e6_c2", "id": "B", "label": "B", "text": "让全宫再演一次震惊", "styleTag": "离谱反套路", "feedback": "众人配合转身，柳总管甚至熟练换了三个表情。镜头很壮观，桌上的账册却仍停留在第一页。", "outcome": "众人配合转身，柳总管甚至熟练换了三个表情。镜头很壮观，桌上的账册却仍停留在第一页。", "qualityBonus": 18, "effects": {"pleasure": 6, "drama": 16, "anger": 16, "evidence": 0, "subversion": 0}}, {"choiceId": "palace_e6_c3", "id": "C", "label": "C", "text": "宣布以后糕点按人头不限阵营", "styleTag": "打工人觉醒", "feedback": "团子掌勺把最后一块糕放到公共盘里，所有人都能自己取。宫斗最难的一关，竟被一套普通分配办法绕开了。", "outcome": "团子掌勺把最后一块糕放到公共盘里，所有人都能自己取。宫斗最难的一关，竟被一套普通分配办法绕开了。", "qualityBonus": 15, "effects": {"pleasure": 7, "drama": 7, "anger": -5, "evidence": 0, "subversion": 1}}]}]', endings_json = '[{"id": "palace.end1", "type": "hidden", "priority": 100, "title": "宫斗冠军是总账会计", "text": "旧库编号与任命副本解释了重复记账的来源，你完成核验。传说中的冷宫从此改叫清静办公室，算盘成为全剧最有用的道具。", "condition": {"minStats": {"evidence": 4}, "maxStats": {"anger": 42}}, "posterTag": "隐藏彩蛋", "hint": "选择搜证方向并点击画面闪烁证物收取 >= 4 份，且反派怒气 <= 42 方可解锁"}, {"id": "palace.end2", "type": "subversive", "priority": 90, "title": "本宫只想按时吃糕", "text": "你多次拒绝阵营比赛，推行直白通知与公开分配。赏花宴没有人争宠，大家在认真讨论下一炉桂花糕能不能少甜一点。", "condition": {"minStats": {"subversion": 3}}, "posterTag": "反套路收官", "hint": "累计拆套路 >= 3 且未触及隐藏或烂尾即可解锁"}, {"id": "palace.end3", "type": "unfinished", "priority": 80, "title": "密旨待附八十张明细", "text": "你热衷恭迎，没留下充分记录。密旨后面被订上长长的待办，柳总管宣布新的规矩是先学会填明细，片尾比片头更像开工。", "condition": {"minStats": {"anger": 60}, "maxStats": {"evidence": 2}}, "posterTag": "喜剧烂尾", "hint": "反派怒气累计 >= 60 且搜证材料 <= 2 时触发翻车烂尾"}, {"id": "palace.end4", "type": "triumph", "priority": 70, "title": "穿越第一课别重复报销", "text": "你用清楚证据完成核账，把复杂宫规改成可执行流程。团子掌勺按人数开炉，宫廷终于实现最朴素的稳定，人人有糕。", "condition": {"always": true}, "posterTag": "爽剧完结", "hint": "稳健走完主线（未触发隐藏/反套路/烂尾）自动保底达成"}]', version = version + 1 WHERE script_id = 'script_09_palace';
